    onFileUpload: (file: File) => void;
    onGoogleSheetImportClick: () => void;
    onAIScanClick: () => void;
    controlDate: Date;
    onControlDateChange: (date: string) => void;
    onSaveSessionCapture: () => void;
    onDownloadImage: () => void;
    isHistoryView: boolean;
    onReturnToLive: () => void;
    view: 'dashboard' | 'reports' | 'logs';
    onToggleView: (view: 'dashboard' | 'reports' | 'logs') => void;
}

const Header: React.FC<HeaderProps> = ({ 
    onAddGenerator, 
    onFileUpload,
    onGoogleSheetImportClick,
    onAIScanClick,
    controlDate, 
    onControlDateChange, 
    view,
    onToggleView
}) => {
    return (
        <header className="bg-slate-900 text-white rounded-2xl shadow-2xl overflow-hidden border border-slate-800">
            <div className="p-4 md:p-6 bg-gradient-to-r from-slate-900 to-slate-800">
                <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
                    <div className="space-y-1">
                        <h1 className="text-2xl font-black tracking-tight flex items-center gap-2">
                            <span className="w-8 h-8 bg-red-600 rounded-lg flex items-center justify-center text-sm">G</span>
                            SISTEMA DE GENERADORES <span className="text-red-500 font-normal">v2.0</span>
                        </h1>
                        <p className="text-slate-400 text-sm font-medium">Panel de control automatizado e Inteligencia Artificial</p>
