                        >
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                            Scan con IA
                        </button>
                        <button 
                            onClick={onAddGenerator}
                            className="bg-emerald-600 hover:bg-emerald-500 text-white px-4 py-2.5 rounded-xl font-bold transition-all shadow-lg shadow-emerald-600/20"
                        >
                            + Nuevo
                        </button>
                    </div>
                </div>
            </div>

            {view === 'dashboard' && (
              <div className="px-6 py-3 bg-slate-800/30 border-t border-slate-800 flex flex-wrap items-center justify-between gap-4">
                <div className="flex items-center gap-3">
                  <span className="text-xs font-bold uppercase tracking-wider text-slate-500">Último Control:</span>
                  <input
                      type="date"
                      value={controlDate.toISOString().split('T')[0]}
                      onChange={(e) => onControlDateChange(e.target.value)}
                      className="bg-slate-900/50 text-white rounded-lg border border-slate-700 px-3 py-1.5 text-sm focus:ring-2 focus:ring-red-500 outline-none"
                  />
                </div>
                <div className="text-xs font-medium text-slate-400 italic">
                  * Cálculos basados en <span className="text-slate-200 font-bold">12h de Autonomía</span> por defecto.
                </div>
              </div>
            )}
        </header>
    );
};

export default Header;

import React, { useState, useRef } from 'react';
import { GoogleGenAI } from "@google/genai";
import { StoredGenerator } from '../types';

interface AIScanModalProps {
    isOpen: boolean;
    onClose: () => void;
    generators: StoredGenerator[];
    onConfirmUpdate: (id: number, fuel: number, hours: string) => void;
}

const AIScanModal: React.FC<AIScanModalProps> = ({ isOpen, onClose, generators, onConfirmUpdate }) => {
    const [image, setImage] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);
    const [results, setResults] = useState<{ fuel?: number; hours?: string; generatorId?: number } | null>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);

    if (!isOpen) return null;

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (ev) => setImage(ev.target?.result as string);
            reader.readAsDataURL(file);
        }
    };

    const runAI = async () => {
        if (!image) return;
        setLoading(true);
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const base64Data = image.split(',')[1];

            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: [{
                    parts: [
                        { text: "Analiza el panel de control del generador en esta imagen. Extrae el nivel de combustible (0-100) y las horas de ejecución totales. Devuelve solo un JSON con el formato: { 'fuelLevel': number, 'executionHours': 'string' }. Si ves el nombre o localidad del generador, inclúyelo también como 'name'." },
                        { inlineData: { mimeType: "image/jpeg", data: base64Data } }
                    ]
                }],
                config: { responseMimeType: "application/json" }
            });

            const data = JSON.parse(response.text || '{}');

            // Try to match name with existing generator
            let matchedId: number | undefined;
            if (data.name) {
                const found = generators.find(g => g.name.toLowerCase().includes(data.name.toLowerCase()));
                if (found) matchedId = found.id;
            }

            setResults({
                fuel: data.fuelLevel,
                hours: data.executionHours,
                generatorId: matchedId
            });
        } catch (error) {
            console.error(error);
            alert("Error procesando imagen con IA.");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-sm flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-3xl shadow-2xl w-full max-w-2xl overflow-hidden border border-slate-200">
                <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                    <h2 className="text-xl font-black text-slate-800 tracking-tight flex items-center gap-2">
                        <span className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white text-xs">AI</span>
                        ESCANEADO INTELIGENTE
                    </h2>
                    <button onClick={onClose} className="text-slate-400 hover:text-slate-600">
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                </div>

                <div className="p-6 space-y-6">
                    {!image ? (
                        <div 
                            onClick={() => fileInputRef.current?.click()}
                            className="border-2 border-dashed border-slate-300 rounded-2xl p-12 flex flex-col items-center justify-center gap-4 cursor-pointer hover:border-indigo-500 hover:bg-slate-50 transition-all group"
                        >
                            <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center group-hover:bg-indigo-100 transition-colors">
                                <svg className="w-8 h-8 text-slate-400 group-hover:text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>
                            </div>
                            <div className="text-center">
                                <p className="font-bold text-slate-700">Subir foto del tablero</p>
                                <p className="text-sm text-slate-500">Cámara o archivo (JPG, PNG)</p>
                            </div>
                        </div>
                    ) : (
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="rounded-xl overflow-hidden bg-black aspect-[4/3] flex items-center justify-center border border-slate-200">
                                <img src={image} className="max-w-full max-h-full object-contain" alt="Preview" />
                            </div>

                            <div className="space-y-4">
                                {loading ? (
                                    <div className="h-full flex flex-col items-center justify-center gap-3">
                                        <div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
                                        <p className="text-sm font-bold text-slate-600 animate-pulse">Analizando con Gemini...</p>
                                    </div>
                                ) : results ? (
                                    <div className="space-y-4 bg-slate-50 p-4 rounded-2xl border border-slate-200">
                                        <div>
                                            <label className="text-xs font-bold text-slate-400 block mb-1">ASIGNAR A:</label>
                                            <select 
                                                value={results.generatorId || ''} 
                                                onChange={(e) => setResults({...results, generatorId: Number(e.target.value)})}
                                                className="w-full p-2 rounded-lg border border-slate-300 text-sm font-bold"
                                            >
                                                <option value="">Seleccionar...</option>
                                                {generators.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                                            </select>
                                        </div>
                                        <div className="grid grid-cols-2 gap-3">
                                            <div>
                                                <label className="text-xs font-bold text-slate-400 block mb-1">COMBUSTIBLE:</label>
                                                <input 
                                                    type="number" 
                                                    value={results.fuel || 0} 
                                                    onChange={(e) => setResults({...results, fuel: Number(e.target.value)})}
                                                    className="w-full p-2 rounded-lg border border-slate-300 font-bold"
                                                />
                                            </div>
                                            <div>
                                                <label className="text-xs font-bold text-slate-400 block mb-1">HORAS:</label>
                                                <input 
                                                    type="text" 
                                                    value={results.hours || ''} 
                                                    onChange={(e) => setResults({...results, hours: e.target.value})}
                                                    className="w-full p-2 rounded-lg border border-slate-300 font-bold"
                                                />
                                            </div>
                                        </div>
                                        <button 
                                            disabled={!results.generatorId}
                                            onClick={() => {
                                                if (results.generatorId) {
                                                    onConfirmUpdate(results.generatorId, results.fuel || 0, results.hours || '0');
                                                    onClose();
                                                }
                                            }}
                                            className="w-full py-3 bg-emerald-600 text-white rounded-xl font-bold shadow-lg shadow-emerald-600/20 disabled:opacity-50"
                                        >
                                            ACTUALIZAR DATOS
                                        </button>
                                    </div>
                                ) : (
                                    <button 
                                        onClick={runAI}
                                        className="w-full h-full py-4 bg-indigo-600 text-white rounded-2xl font-black text-lg shadow-lg shadow-indigo-600/20"
                                    >
                                        PROCESAR IMAGEN
                                    </button>
                                )}
                                <button onClick={() => {setImage(null); setResults(null);}} className="w-full py-2 text-slate-400 hover:text-slate-600 text-xs font-bold uppercase underline">
                                    Cambiar imagen
                                </button>
                            </div>
                        </div>
                    )}
                </div>
                <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept="image/*" />
            </div>
        </div>
    );
};

export default AIScanModal;

import React from 'react';
import { ChangeLog } from '../types';

interface LogsViewProps {
  logs: ChangeLog[];
}

const LogsView: React.FC<LogsViewProps> = ({ logs }) => {
  return (
    <div className="bg-white rounded-2xl shadow-xl border border-slate-200 overflow-hidden">
      <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
        <div>
          <h2 className="text-xl font-black text-slate-800 tracking-tight">HISTORIAL DE CAMBIOS</h2>
          <p className="text-slate-500 text-sm">Registro de actualizaciones manuales y automáticas</p>
        </div>
        <button 
          onClick={() => {
            const csv = "Fecha,Generador,Campo,Anterior,Nuevo,Origen\n" + 
              logs.map(l => `${new Date(l.timestamp).toLocaleString()},${l.generatorName},${l.field},${l.oldValue},${l.newValue},${l.source}`).join("\n");
            const blob = new Blob([csv], { type: 'text/csv' });
            const url = window.URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.setAttribute('href', url);
            a.setAttribute('download', `reporte_cambios_${new Date().toISOString().split('T')[0]}.csv`);
            a.click();
          }}
          className="bg-slate-800 text-white px-4 py-2 rounded-xl text-sm font-bold hover:bg-slate-700 transition-colors"
        >
          Exportar CSV
        </button>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead className="bg-slate-50 text-slate-500 font-bold uppercase text-[10px] tracking-widest border-b border-slate-100">
            <tr>
              <th className="px-6 py-4 text-left">Fecha/Hora</th>
              <th className="px-6 py-4 text-left">Generador</th>
              <th className="px-6 py-4 text-left">Campo</th>
