import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { StoredGenerator } from '../types';

interface AIScanModalProps {
    isOpen: boolean;
    onClose: () => void;
    generators: StoredGenerator[];
    onConfirmUpdate: (id: number, fuel: number, hours: string) => void;
}

const AIScanModal: React.FC<AIScanModalProps> = ({ isOpen, onClose, generators, onConfirmUpdate }) => {
    const [mode, setMode] = useState<'upload' | 'camera'>('camera');
    const [image, setImage] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);
    const [results, setResults] = useState<{ fuel?: number; hours?: string; generatorId?: number } | null>(null);
    const [cameraActive, setCameraActive] = useState(false);

    const fileInputRef = useRef<HTMLInputElement>(null);
    const videoRef = useRef<HTMLVideoElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const streamRef = useRef<MediaStream | null>(null);

    // Stop camera when modal closes or mode changes
    useEffect(() => {
        return () => stopCamera();
    }, []);

    useEffect(() => {
        if (isOpen && mode === 'camera' && !image) {
            startCamera();
        } else {
            stopCamera();
        }
    }, [isOpen, mode, image]);

    const startCamera = async () => {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ 
                video: { facingMode: 'environment' }, 
                audio: false 
            });
            if (videoRef.current) {
                videoRef.current.srcObject = stream;
                streamRef.current = stream;
                setCameraActive(true);
            }
        } catch (err) {
            console.error("Error accessing camera:", err);
            setMode('upload');
            alert("No se pudo acceder a la cámara. Por favor, use la opción de subida.");
        }
    };

    const stopCamera = () => {
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
            streamRef.current = null;
        }
        setCameraActive(false);
    };

    const capturePhoto = () => {
        if (videoRef.current && canvasRef.current) {
            const video = videoRef.current;
            const canvas = canvasRef.current;
            canvas.width = video.videoWidth;
            canvas.height = video.videoHeight;
            const ctx = canvas.getContext('2d');
            if (ctx) {
                ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
                const dataUrl = canvas.toDataURL('image/jpeg');
                setImage(dataUrl);
                stopCamera();
            }
        }
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (ev) => setImage(ev.target?.result as string);
            reader.readAsDataURL(file);
        }
    };

    const runAI = async () => {
        if (!image) return;
        setLoading(true);
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const base64Data = image.split(',')[1];

            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: [{
                    parts: [
                        { text: "Analiza el panel de control del generador en esta imagen. Extrae el nivel de combustible (0-100) y las horas de ejecución totales. Devuelve solo un JSON con el formato: { 'fuelLevel': number, 'executionHours': 'string', 'name': 'string' }. Si no ves el nombre, deja 'name' vacío." },
                        { inlineData: { mimeType: "image/jpeg", data: base64Data } }
                    ]
                }],
                config: { responseMimeType: "application/json" }
            });

            const data = JSON.parse(response.text || '{}');

            let matchedId: number | undefined;
            if (data.name) {
                const found = generators.find(g => g.name.toLowerCase().includes(data.name.toLowerCase()));
                if (found) matchedId = found.id;
            }

            setResults({
                fuel: data.fuelLevel,
                hours: data.executionHours,
                generatorId: matchedId
            });
        } catch (error) {
            console.error(error);
            alert("Error procesando imagen con IA.");
        } finally {
            setLoading(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-md flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-3xl shadow-2xl w-full max-w-4xl overflow-hidden border border-slate-200 flex flex-col max-h-[90vh]">
                {/* Header */}
                <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                    <div className="flex items-center gap-4">
                        <h2 className="text-xl font-black text-slate-800 tracking-tight flex items-center gap-2">
                            <span className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white text-xs">AI</span>
                            ESCANEADO INTELIGENTE
                        </h2>
                        {!image && !loading && (
                            <div className="flex bg-slate-200 p-1 rounded-xl text-xs font-bold">
                                <button 
                                    onClick={() => setMode('camera')}
                                    className={`px-3 py-1.5 rounded-lg transition-all ${mode === 'camera' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                                >
                                    CÁMARA
                                </button>
                                <button 
                                    onClick={() => setMode('upload')}
                                    className={`px-3 py-1.5 rounded-lg transition-all ${mode === 'upload' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                                >
                                    ARCHIVO
                                </button>
                            </div>
                        )}
                    </div>
                    <button onClick={onClose} className="text-slate-400 hover:text-slate-600 p-2">
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                </div>

                {/* Content */}
                <div className="flex-1 overflow-y-auto p-6">
                    {!image ? (
                        <div className="h-full min-h-[400px]">
                            {mode === 'camera' ? (
                                <div className="relative h-full bg-black rounded-2xl overflow-hidden group">
                                    <video 
                                        ref={videoRef} 
                                        autoPlay 
                                        playsInline 
                                        className="w-full h-full object-cover"
                                    />
                                    {/* Overlay guide */}
                                    <div className="absolute inset-0 border-2 border-white/20 pointer-events-none flex items-center justify-center">
                                        <div className="w-64 h-32 border border-white/40 rounded-lg flex items-center justify-center">
                                            <div className="w-2 h-2 bg-red-500 rounded-full animate-pulse" />
                                        </div>
                                    </div>
                                    <div className="absolute bottom-8 left-0 right-0 flex justify-center">
                                        <button 
                                            onClick={capturePhoto}
                                            className="w-16 h-16 bg-white rounded-full border-4 border-slate-300 hover:border-indigo-500 flex items-center justify-center shadow-2xl transition-all active:scale-90"
                                        >
                                            <div className="w-10 h-10 bg-red-600 rounded-full" />
                                        </button>
                                    </div>
                                    <p className="absolute top-4 left-1/2 -translate-x-1/2 text-white/70 text-[10px] font-bold uppercase tracking-widest bg-black/40 px-3 py-1 rounded-full">
                                        Apunta al tablero del generador
                                    </p>
                                </div>
                            ) : (
                                <div 
                                    onClick={() => fileInputRef.current?.click()}
                                    className="h-full border-2 border-dashed border-slate-300 rounded-2xl p-12 flex flex-col items-center justify-center gap-4 cursor-pointer hover:border-indigo-500 hover:bg-slate-50 transition-all group"
                                >
                                    <div className="w-20 h-20 bg-slate-100 rounded-full flex items-center justify-center group-hover:bg-indigo-100 transition-colors">
                                        <svg className="w-10 h-10 text-slate-400 group-hover:text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>
                                    </div>
                                    <div className="text-center">
                                        <p className="font-bold text-slate-700 text-lg">Subir archivo de imagen</p>
                                        <p className="text-sm text-slate-500">Haz clic para buscar o arrastra una foto aquí</p>
                                    </div>
                                </div>
                            )}
                        </div>
                    ) : (
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 h-full">
                            <div className="relative rounded-2xl overflow-hidden bg-slate-900 border border-slate-200 shadow-inner">
                                <img src={image} className="w-full h-full object-contain" alt="Captured" />
                                <button 
                                    onClick={() => {setImage(null); setResults(null);}} 
                                    className="absolute top-4 left-4 bg-white/90 hover:bg-white text-slate-800 p-2 rounded-xl text-xs font-bold shadow-lg flex items-center gap-2"
                                >
                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
                                    REPETIR
                                </button>
                            </div>

                            <div className="space-y-6 flex flex-col justify-center">
                                {loading ? (
                                    <div className="flex flex-col items-center justify-center gap-6 py-12">
                                        <div className="relative w-20 h-20">
                                            <div className="absolute inset-0 border-4 border-indigo-100 rounded-full" />
                                            <div className="absolute inset-0 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin" />
                                        </div>
                                        <div className="text-center">
                                            <p className="text-lg font-black text-slate-800 animate-pulse">Analizando imagen con Gemini</p>
                                            <p className="text-slate-500 text-sm">Extrayendo datos de ejecución y combustible...</p>
                                        </div>
                                    </div>
                                ) : results ? (
                                    <div className="space-y-6 bg-slate-50 p-6 rounded-3xl border border-slate-200">
                                        <div className="space-y-4">
                                            <div>
                                                <label className="text-xs font-black text-slate-400 block mb-2 tracking-widest uppercase">Generador Detectado:</label>
                                                <select 
                                                    value={results.generatorId || ''} 
                                                    onChange={(e) => setResults({...results, generatorId: Number(e.target.value)})}
                                                    className="w-full p-3 bg-white rounded-xl border border-slate-200 text-sm font-bold shadow-sm focus:ring-2 focus:ring-indigo-500 outline-none"
