                                            </div>
                                            <div className="grid grid-cols-2 gap-4">
                                                <div>
                                                    <label className="text-xs font-black text-slate-400 block mb-2 tracking-widest uppercase">Combustible:</label>
                                                    <div className="relative">
                                                        <input 
                                                            type="number" 
                                                            value={results.fuel || 0} 
                                                            onChange={(e) => setResults({...results, fuel: Number(e.target.value)})}
                                                            className="w-full p-3 pl-10 bg-white rounded-xl border border-slate-200 font-bold shadow-sm"
                                                        />
                                                        <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 font-bold">%</span>
