                                                        />
                                                        <svg className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                        <button 
                                            disabled={!results.generatorId}
                                            onClick={() => {
                                                if (results.generatorId) {
                                                    onConfirmUpdate(results.generatorId, results.fuel || 0, results.hours || '0');
                                                    onClose();
                                                }
                                            }}
                                            className="w-full py-4 bg-emerald-600 hover:bg-emerald-500 text-white rounded-2xl font-black text-lg shadow-xl shadow-emerald-600/20 disabled:opacity-50 transition-all flex items-center justify-center gap-2"
                                        >
                                            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" /></svg>
                                            CARGAR INFORMACIÓN
                                        </button>
                                    </div>
                                ) : (
                                    <div className="space-y-4">
                                        <button 
                                            onClick={runAI}
                                            className="w-full py-6 bg-indigo-600 hover:bg-indigo-500 text-white rounded-3xl font-black text-xl shadow-2xl shadow-indigo-600/30 transition-all active:scale-95 flex flex-col items-center gap-1"
                                        >
                                            PROCESAR CON IA
                                            <span className="text-[10px] font-bold text-white/60 tracking-widest uppercase">Analizar ahora</span>
                                        </button>
                                        <p className="text-center text-slate-400 text-xs px-8 italic">
                                            La Inteligencia Artificial detectará automáticamente el estado del generador en la imagen.
                                        </p>
                                    </div>
                                )}
                            </div>
                        </div>
                    )}
                </div>

                {/* Hidden canvas for processing */}
                <canvas ref={canvasRef} className="hidden" />
                <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept="image/*" />
            </div>
        </div>
    );
};

