export default AIScanModal;

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { StoredGenerator } from '../types';

interface AIScanModalProps {
    isOpen: boolean;
    onClose: () => void;
    generators: StoredGenerator[];
    onConfirmUpdate: (id: number, fuel: number, hours: string) => void;
}

const AIScanModal: React.FC<AIScanModalProps> = ({ isOpen, onClose, generators, onConfirmUpdate }) => {
    const [mode, setMode] = useState<'upload' | 'camera' | 'screen'>('camera');
    const [image, setImage] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);
    const [results, setResults] = useState<{ fuel?: number; hours?: string; generatorId?: number } | null>(null);
    const [isStreamActive, setIsStreamActive] = useState(false);

    const fileInputRef = useRef<HTMLInputElement>(null);
    const videoRef = useRef<HTMLVideoElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const streamRef = useRef<MediaStream | null>(null);

    // Limpieza al cerrar
    useEffect(() => {
        if (!isOpen) {
            stopMedia();
        }
    }, [isOpen]);

    const stopMedia = () => {
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
            streamRef.current = null;
        }
        if (videoRef.current) {
            videoRef.current.srcObject = null;
        }
        setIsStreamActive(false);
    };

    const startCamera = async () => {
        stopMedia();
        setMode('camera');
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ 
                video: { facingMode: 'environment' }, 
                audio: false 
            });
            handleStream(stream);
        } catch (err) {
            console.error("Error al acceder a la cámara:", err);
            alert("No se pudo acceder a la cámara. Verifica los permisos.");
            setMode('upload');
        }
    };

    const startScreenCapture = async () => {
        stopMedia();
        setMode('screen');
        try {
            // Nota: getDisplayMedia debe ser llamado en un evento de clic directo
            const stream = await navigator.mediaDevices.getDisplayMedia({ 
                video: { cursor: "always" } as any, 
                audio: false 
            });
            handleStream(stream);

            // Si el usuario deja de compartir desde el botón nativo del navegador
            stream.getVideoTracks()[0].onended = () => {
                stopMedia();
            };
        } catch (err) {
            console.error("Error al capturar pantalla:", err);
            // Si el usuario cancela, simplemente volvemos a un estado neutro
            if (err instanceof Error && err.name !== 'NotAllowedError') {
                alert("Error al intentar capturar la pantalla.");
            }
            setIsStreamActive(false);
        }
    };

    const handleStream = (stream: MediaStream) => {
        if (videoRef.current) {
            videoRef.current.srcObject = stream;
            streamRef.current = stream;
            setIsStreamActive(true);
            videoRef.current.play().catch(console.error);
        }
    };

    const handleModeChange = (newMode: 'upload' | 'camera' | 'screen') => {
        setImage(null);
        setResults(null);
        if (newMode === 'upload') {
            stopMedia();
            setMode('upload');
        } else if (newMode === 'camera') {
            startCamera();
        } else if (newMode === 'screen') {
            startScreenCapture();
        }
    };

    const captureFrame = () => {
        if (videoRef.current && canvasRef.current && isStreamActive) {
            const video = videoRef.current;
            const canvas = canvasRef.current;

            // Aseguramos que el video tenga dimensiones válidas
            if (video.videoWidth === 0 || video.videoHeight === 0) return;

            canvas.width = video.videoWidth;
            canvas.height = video.videoHeight;
            const ctx = canvas.getContext('2d');
            if (ctx) {
                ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
                const dataUrl = canvas.toDataURL('image/jpeg', 0.95);
                setImage(dataUrl);
                stopMedia();
            }
        }
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (ev) => setImage(ev.target?.result as string);
            reader.readAsDataURL(file);
        }
    };

    const runAI = async () => {
        if (!image) return;
        setLoading(true);
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const base64Data = image.split(',')[1];

