                    parts: [
                        { text: "Eres un asistente experto en monitoreo de generadores. Analiza esta imagen (puede ser una foto de panel físico o una captura de pantalla de otro sistema). Extrae: 1. Nivel de combustible (número del 0 al 100), 2. Horas de ejecución totales (texto), 3. Nombre o localidad del generador si es visible. Devuelve exclusivamente un JSON: { 'fuelLevel': number, 'executionHours': 'string', 'name': 'string' }. Si falta algún dato, deja el campo vacío o en 0." },
                        { inlineData: { mimeType: "image/jpeg", data: base64Data } }
                    ]
                }],
                config: { responseMimeType: "application/json" }
            });

            const data = JSON.parse(response.text || '{}');

            let matchedId: number | undefined;
            if (data.name) {
                const found = generators.find(g => 
                    g.name.toLowerCase().includes(data.name.toLowerCase()) || 
                    data.name.toLowerCase().includes(g.name.toLowerCase())
                );
                if (found) matchedId = found.id;
            }

            setResults({
                fuel: data.fuelLevel,
                hours: data.executionHours,
                generatorId: matchedId
            });
        } catch (error) {
            console.error(error);
            alert("Error procesando con IA. Intenta capturar la información de forma más clara.");
        } finally {
            setLoading(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-md flex items-center justify-center z-50 p-4">
