                                            }}
                                            className="w-full py-5 bg-emerald-600 hover:bg-emerald-500 text-white rounded-2xl font-black text-lg shadow-xl shadow-emerald-600/20 disabled:opacity-50 transition-all flex items-center justify-center gap-3 active:scale-[0.98]"
                                        >
