import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { StoredGenerator } from '../types';

interface AIScanModalProps {
    isOpen: boolean;
    onClose: () => void;
    generators: StoredGenerator[];
    onConfirmUpdate: (id: number, fuel: number, hours: string) => void;
}

const AIScanModal: React.FC<AIScanModalProps> = ({ isOpen, onClose, generators, onConfirmUpdate }) => {
    const [mode, setMode] = useState<'upload' | 'camera' | 'screen'>('camera');
    const [image, setImage] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);
    const [results, setResults] = useState<{ fuel?: number; hours?: string; generatorId?: number } | null>(null);
    const [isStreamActive, setIsStreamActive] = useState(false);

    const fileInputRef = useRef<HTMLInputElement>(null);
    const videoRef = useRef<HTMLVideoElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const streamRef = useRef<MediaStream | null>(null);

    // Detener todo al cerrar el modal
    useEffect(() => {
        if (!isOpen) {
            stopMedia();
        }
    }, [isOpen]);

    const stopMedia = () => {
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
            streamRef.current = null;
        }
        if (videoRef.current) {
            videoRef.current.srcObject = null;
        }
        setIsStreamActive(false);
    };

    const handleStream = async (stream: MediaStream) => {
        if (videoRef.current) {
            videoRef.current.srcObject = stream;
            streamRef.current = stream;

            try {
                // Forzamos el play para asegurar que el stream se visualice
                await videoRef.current.play();
                setIsStreamActive(true);
            } catch (err) {
                console.error("Error al reproducir video del stream:", err);
                setIsStreamActive(false);
            }
        }
    };

    const startCamera = async () => {
        stopMedia();
        setMode('camera');
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ 
                video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } }, 
                audio: false 
            });
            await handleStream(stream);
        } catch (err) {
            console.error("Error al acceder a la cámara:", err);
            alert("No se pudo acceder a la cámara. Revisa los permisos de tu navegador.");
            setMode('upload');
        }
    };

    const startScreenCapture = async () => {
        stopMedia();
        setMode('screen');
        try {
            // Importante: getDisplayMedia REQUIERE ser llamado en un evento de click directo.
            const stream = await navigator.mediaDevices.getDisplayMedia({ 
                video: { 
                    cursor: "always",
                    displaySurface: "monitor" // Sugiere captura de monitor por defecto
                } as any, 
                audio: false 
            });

            await handleStream(stream);

            // Detectar cuando el usuario deja de compartir desde el banner del navegador
            stream.getVideoTracks()[0].onended = () => {
                stopMedia();
            };
        } catch (err) {
            console.error("Error en captura de pantalla:", err);
            if (err instanceof Error && err.name !== 'NotAllowedError') {
                alert("Ocurrió un error al intentar capturar la pantalla. Intenta nuevamente.");
            }
            setIsStreamActive(false);
        }
    };

    const handleModeChange = (newMode: 'upload' | 'camera' | 'screen') => {
        setImage(null);
        setResults(null);
        if (newMode === 'upload') {
            stopMedia();
            setMode('upload');
        } else if (newMode === 'camera') {
            startCamera();
        } else if (newMode === 'screen') {
            startScreenCapture();
        }
    };

    const captureFrame = () => {
        if (videoRef.current && canvasRef.current && isStreamActive) {
            const video = videoRef.current;
            const canvas = canvasRef.current;

            if (video.videoWidth === 0 || video.videoHeight === 0) {
                alert("El video no está listo. Intenta de nuevo.");
                return;
            }

            canvas.width = video.videoWidth;
            canvas.height = video.videoHeight;
            const ctx = canvas.getContext('2d');
            if (ctx) {
                ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
                const dataUrl = canvas.toDataURL('image/jpeg', 0.95);
                setImage(dataUrl);
                stopMedia();
            }
        }
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (ev) => setImage(ev.target?.result as string);
            reader.readAsDataURL(file);
        }
    };

    const runAI = async () => {
        if (!image) return;
        setLoading(true);
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const base64Data = image.split(',')[1];

            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: [{
                    parts: [
                        { text: "Eres un asistente experto en monitoreo de generadores. Analiza esta captura de pantalla de otro sistema o tablero físico. Extrae: 1. Nivel de combustible (número del 0 al 100), 2. Horas de ejecución totales (texto con unidad si existe), 3. Nombre o localidad del generador si es visible. Devuelve exclusivamente un JSON: { 'fuelLevel': number, 'executionHours': 'string', 'name': 'string' }. Si no encuentras un dato, pon 0 o vacío." },
                        { inlineData: { mimeType: "image/jpeg", data: base64Data } }
                    ]
                }],
                config: { responseMimeType: "application/json" }
            });

            const data = JSON.parse(response.text || '{}');

            let matchedId: number | undefined;
            if (data.name) {
                const found = generators.find(g => 
                    g.name.toLowerCase().includes(data.name.toLowerCase()) || 
                    data.name.toLowerCase().includes(g.name.toLowerCase())
                );
                if (found) matchedId = found.id;
            }

            setResults({
                fuel: data.fuelLevel,
                hours: data.executionHours,
                generatorId: matchedId
            });
        } catch (error) {
            console.error(error);
            alert("No se pudo extraer la información. Asegúrate de que los datos sean visibles en la captura.");
        } finally {
            setLoading(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-md flex items-center justify-center z-50 p-4">
