                <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                    <div className="flex flex-col sm:flex-row sm:items-center gap-4">
                        <h2 className="text-xl font-black text-slate-800 tracking-tight flex items-center gap-2">
                            <span className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white text-xs">AI</span>
                            AUTOMATIZACIÓN POR IA
                        </h2>
                        {!image && !loading && (
                            <div className="flex bg-slate-200 p-1 rounded-xl text-[10px] font-black tracking-wider">
                                <button 
                                    onClick={() => handleModeChange('camera')}
                                    className={`px-4 py-2 rounded-lg transition-all ${mode === 'camera' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                                >
                                    CÁMARA
                                </button>
                                <button 
                                    onClick={() => handleModeChange('screen')}
                                    className={`px-4 py-2 rounded-lg transition-all ${mode === 'screen' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                                >
                                    PANTALLA
                                </button>
                                <button 
                                    onClick={() => handleModeChange('upload')}
                                    className={`px-4 py-2 rounded-lg transition-all ${mode === 'upload' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                                >
                                    ARCHIVO
                                </button>
                            </div>
                        )}
                    </div>
                    <button onClick={onClose} className="text-slate-400 hover:text-slate-600 p-2 bg-slate-100 rounded-full transition-colors hover:bg-slate-200">
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                </div>

                {/* Content */}
                <div className="flex-1 overflow-y-auto p-6 bg-slate-50/50">
                    {!image ? (
                        <div className="h-[450px]">
                            {mode === 'camera' || mode === 'screen' ? (
                                <div className="relative h-full bg-slate-900 rounded-2xl overflow-hidden border-4 border-white shadow-2xl flex items-center justify-center">
                                    <video 
                                        ref={videoRef} 
                                        autoPlay 
                                        playsInline 
                                        muted
                                        className="w-full h-full object-contain"
                                    />

                                    {!isStreamActive && (
                                        <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-900 text-white gap-6 text-center px-6">
                                            <div className="w-16 h-16 bg-white/10 rounded-full flex items-center justify-center animate-pulse">
                                                <svg className="w-8 h-8 text-white/40" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
                                            </div>
                                            <div className="space-y-2">
                                                <p className="text-lg font-bold">Fuente Inactiva</p>
                                                <p className="text-slate-400 text-sm max-w-xs">Presiona el botón para iniciar la captura {mode === 'camera' ? 'de tu cámara' : 'de tu pantalla'}.</p>
                                            </div>
                                            <button 
                                                onClick={() => mode === 'camera' ? startCamera() : startScreenCapture()}
                                                className="px-8 py-4 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl shadow-indigo-600/30 transition-all active:scale-95"
                                            >
                                                Activar {mode === 'camera' ? 'Cámara' : 'Captura de Pantalla'}
                                            </button>
                                        </div>
                                    )}

                                    {isStreamActive && (
                                        <>
                                            <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
                                                <div className="w-2/3 h-1/2 border-2 border-indigo-500/20 rounded-3xl relative">
                                                    <div className="absolute -top-1 -left-1 w-10 h-10 border-t-4 border-l-4 border-indigo-500 rounded-tl-xl" />
                                                    <div className="absolute -top-1 -right-1 w-10 h-10 border-t-4 border-r-4 border-indigo-500 rounded-tr-xl" />
                                                    <div className="absolute -bottom-1 -left-1 w-10 h-10 border-b-4 border-l-4 border-indigo-500 rounded-bl-xl" />
                                                    <div className="absolute -bottom-1 -right-1 w-10 h-10 border-b-4 border-r-4 border-indigo-500 rounded-br-xl" />
                                                </div>
                                            </div>

                                            <div className="absolute bottom-10 left-0 right-0 flex flex-col items-center gap-4">
                                                <button 
                                                    onClick={captureFrame}
                                                    className="group relative w-24 h-24 bg-white rounded-full p-1 shadow-[0_0_50px_rgba(255,255,255,0.3)] transition-all active:scale-90 hover:scale-105"
                                                >
                                                    <div className="w-full h-full rounded-full border-4 border-slate-100 flex items-center justify-center">
                                                        <div className="w-16 h-16 bg-indigo-600 rounded-full group-hover:bg-indigo-500 transition-colors shadow-inner" />
                                                    </div>
                                                </button>
                                                <span className="text-white text-[11px] font-black tracking-[0.2em] uppercase bg-black/60 px-6 py-2 rounded-full backdrop-blur-md border border-white/20">
                                                    Capturar Ahora
                                                </span>
                                            </div>
                                        </>
                                    )}
                                </div>
                            ) : (
                                <div 
