                                    className="h-full border-4 border-dashed border-slate-200 rounded-3xl flex flex-col items-center justify-center gap-6 cursor-pointer hover:border-indigo-400 hover:bg-indigo-50/30 transition-all group bg-white"
                                >
                                    <div className="w-24 h-24 bg-slate-50 rounded-3xl flex items-center justify-center group-hover:bg-indigo-100 transition-colors rotate-3 group-hover:rotate-0">
