                                <div className="absolute bottom-4 left-4 right-4 flex justify-between">
                                    <button 
                                        onClick={() => {setImage(null); setResults(null); if (mode !== 'upload') handleModeChange(mode);}} 
                                        className="bg-white/90 hover:bg-white text-slate-800 px-5 py-2.5 rounded-2xl text-xs font-black shadow-xl flex items-center gap-2 transition-all active:scale-95"
                                    >
                                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
                                        REPETIR CAPTURA
                                    </button>
                                </div>
                            </div>

                            <div className="flex flex-col justify-center">
                                {loading ? (
                                    <div className="bg-white p-12 rounded-[2.5rem] border border-slate-200 shadow-xl flex flex-col items-center gap-8 text-center">
                                        <div className="relative">
                                            <div className="w-24 h-24 border-8 border-indigo-50 rounded-full" />
                                            <div className="absolute inset-0 border-8 border-indigo-600 border-t-transparent rounded-full animate-spin" />
                                        </div>
                                        <div className="space-y-2">
                                            <p className="text-2xl font-black text-slate-800">Analizando con Gemini</p>
                                            <p className="text-slate-500 text-sm">Extrayendo horas y nivel de combustible...</p>
                                        </div>
                                    </div>
                                ) : results ? (
                                    <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-xl space-y-8">
                                        <div className="space-y-6">
                                            <div>
                                                <label className="text-[10px] font-black text-slate-400 block mb-2 tracking-[0.2em] uppercase">Generador Detectado:</label>
                                                <select 
                                                    value={results.generatorId || ''} 
                                                    onChange={(e) => setResults({...results, generatorId: Number(e.target.value)})}
                                                    className="w-full p-5 bg-slate-50 rounded-2xl border-2 border-slate-100 text-sm font-bold shadow-sm focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 outline-none transition-all"
                                                >
                                                    <option value="">-- Seleccionar de la lista --</option>
                                                    {generators.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                                                </select>
                                            </div>

                                            <div className="grid grid-cols-2 gap-6">
                                                <div className="bg-slate-50 p-5 rounded-2xl border-2 border-slate-100 text-center">
                                                    <label className="text-[10px] font-black text-slate-400 block mb-3 tracking-widest uppercase text-center">Combustible</label>
                                                    <div className="flex items-center justify-center gap-1">
                                                        <input 
                                                            type="number" 
                                                            value={results.fuel || 0} 
                                                            onChange={(e) => setResults({...results, fuel: Number(e.target.value)})}
                                                            className="w-20 text-center bg-transparent text-4xl font-black text-slate-800 focus:outline-none"
                                                        />
                                                        <span className="text-2xl font-bold text-slate-300">%</span>
                                                    </div>
                                                </div>
                                                <div className="bg-slate-50 p-5 rounded-2xl border-2 border-slate-100 text-center">
                                                    <label className="text-[10px] font-black text-slate-400 block mb-3 tracking-widest uppercase text-center">Horas Ejec.</label>
                                                    <input 
                                                        type="text" 
                                                        value={results.hours || ''} 
                                                        onChange={(e) => setResults({...results, hours: e.target.value})}
                                                        className="w-full text-center bg-transparent text-2xl font-black text-slate-800 focus:outline-none"
                                                    />
                                                </div>
                                            </div>
                                        </div>

                                        <button 
                                            disabled={!results.generatorId}
                                            onClick={() => {
                                                if (results.generatorId) {
                                                    onConfirmUpdate(results.generatorId, results.fuel || 0, results.hours || '0');
                                                    onClose();
                                                }
                                            }}
                                            className="w-full py-6 bg-emerald-600 hover:bg-emerald-500 text-white rounded-2xl font-black text-xl shadow-2xl shadow-emerald-600/30 disabled:opacity-50 disabled:grayscale transition-all flex items-center justify-center gap-3 active:scale-[0.98]"
                                        >
                                            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" /></svg>
                                            SINCRONIZAR DATOS
                                        </button>
                                    </div>
                                ) : (
                                    <div className="space-y-6">
                                        <button 
                                            onClick={runAI}
                                            className="w-full py-12 bg-indigo-600 hover:bg-indigo-500 text-white rounded-[2.5rem] font-black text-3xl shadow-[0_20px_50px_rgba(79,70,229,0.4)] transition-all active:scale-95 flex flex-col items-center gap-2 group"
                                        >
                                            PROCESAR IMAGEN
                                            <span className="text-xs font-bold text-white/50 tracking-[0.3em] uppercase group-hover:text-white transition-colors">Extracción por Inteligencia Artificial</span>
                                        </button>
                                    </div>
                                )}
                            </div>
                        </div>
                    )}
                </div>

                <canvas ref={canvasRef} className="hidden" />
                <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept="image/*" />
            </div>
        </div>
    );
};

