const calculateDaysSince = (dateStr: string, fromDate: Date): number => {
  const parts = dateStr.split('/');
  if (parts.length !== 3) return 0;
  const [day, month, year] = parts;
  const formattedDate = new Date(`${year}-${month}-${day}`);
  if (isNaN(formattedDate.getTime())) return 0;

  const controlDate = new Date(fromDate);
  controlDate.setHours(0, 0, 0, 0);
  formattedDate.setHours(0,0,0,0);

  const diffTime = controlDate.getTime() - formattedDate.getTime();
  if (diffTime < 0) return 0;
  return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
};

const App: React.FC = () => {
  const [view, setView] = useState<'dashboard' | 'reports' | 'logs'>('dashboard');

  const [generators, setGenerators] = useState<StoredGenerator[]>(() => {
    try {
      const saved = localStorage.getItem('generators');
      return saved ? JSON.parse(saved) : INITIAL_GENERATORS;
    } catch {
      return INITIAL_GENERATORS;
    }
  });

  const [logs, setLogs] = useState<ChangeLog[]>(() => {
    try {
      const saved = localStorage.getItem('change_logs');
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  const [reports, setReports] = useState<Report[]>(() => {
    try {
        const saved = localStorage.getItem('reports');
        return saved ? JSON.parse(saved) : EXCEL_GENERATORS.map(name => ({ generatorName: name, entries: [] }));
    } catch {
        return [];
    }
  });

  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'name', direction: 'ascending' });
  const [selectedRowId, setSelectedRowId] = useState<number | null>(null);
  const [editingCell, setEditingCell] = useState<{ id: number; key: keyof Generator } | null>(null);
  const [controlDate, setControlDate] = useState(new Date());
  const [isSheetModalOpen, setIsSheetModalOpen] = useState(false);
  const [isAIModalOpen, setIsAIModalOpen] = useState(false);

  // Automatización: Refrescar dashboard cada 5 minutos
  useEffect(() => {
    const refreshInterval = setInterval(() => {
      console.log("Auto-refrescando dashboard para actualizar cálculos de tiempo...");
      setControlDate(new Date());
    }, 5 * 60 * 1000);

    return () => clearInterval(refreshInterval);
  }, []);

  useEffect(() => {
    localStorage.setItem('generators', JSON.stringify(generators));
    localStorage.setItem('reports', JSON.stringify(reports));
    localStorage.setItem('change_logs', JSON.stringify(logs));
  }, [generators, reports, logs]);

  const addLog = (generatorName: string, field: string, oldVal: any, newVal: any, source: ChangeLog['source']) => {
    const newLog: ChangeLog = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toISOString(),
      generatorName,
      field,
      oldValue: oldVal,
      newValue: newVal,
      source
    };
    setLogs(prev => [newLog, ...prev].slice(0, 500));
  };

  const calculateStatus = (fuelLevel: number): Status => {
    if (fuelLevel >= 71) return Status.Optimal;
    if (fuelLevel === 70) return Status.Warning;
    return Status.NeedsRecharge;
  };

  const processedGenerators: Generator[] = useMemo(() => {
    return generators.map(g => ({
      ...g,
      status: calculateStatus(g.fuelLevel),
      timeSinceLastRecharge: calculateDaysSince(g.lastRechargeDate, controlDate),
    }));
  }, [generators, controlDate]);

  const sortedGenerators = useMemo(() => {
    const sortableItems = [...processedGenerators];
    if (sortConfig.key) {
      sortableItems.sort((a, b) => {
        const aValue = a[sortConfig.key];
        const bValue = b[sortConfig.key];
        if (typeof aValue === 'string' && typeof bValue === 'string') {
          return sortConfig.direction === 'ascending' ? aValue.localeCompare(bValue) : bValue.localeCompare(aValue);
        }
        return sortConfig.direction === 'ascending' ? (aValue as number) - (bValue as number) : (bValue as number) - (aValue as number);
      });
    }
    return sortableItems;
  }, [processedGenerators, sortConfig]);

  const handleGeneratorUpdate = (id: number, key: keyof StoredGenerator, value: string, source: ChangeLog['source'] = 'Manual') => {
    setGenerators(prev => 
      prev.map(gen => {
        if (gen.id === id) {
          let updatedValue: string | number = value;
          if (key === 'fuelLevel') {
            const numericValue = parseFloat(value.replace(',', '.'));
            updatedValue = isNaN(numericValue) ? gen[key] : numericValue;
          }

          if (gen[key] !== updatedValue) {
            addLog(gen.name, key, gen[key], updatedValue, source);
          }

          return { ...gen, [key]: updatedValue };
        }
        return gen;
      })
    );
    setEditingCell(null);
  };

  const handleAIUpdate = (id: number, fuel: number, hours: string) => {
    handleGeneratorUpdate(id, 'fuelLevel', String(fuel), 'AI');
    handleGeneratorUpdate(id, 'executionHours', hours, 'AI');
  };

  return (
    <div className="min-h-screen bg-slate-50 p-4 sm:p-6 lg:p-8 font-sans">
      <div id="capture-container" className="max-w-7xl mx-auto space-y-6">
        <Header 
          onAddGenerator={() => {
            const newId = generators.length > 0 ? Math.max(...generators.map(g => g.id)) + 1 : 1;
            setGenerators(prev => [...prev, {
              id: newId,
              name: `Generador ${newId}`,
              executionHours: '0 Hr',
              fuelLevel: 100,
              lastRechargeDate: new Date().toLocaleDateString('es-ES')
            }]);
          }}
          onFileUpload={() => {}}
          onGoogleSheetImportClick={() => setIsSheetModalOpen(true)}
          onAIScanClick={() => setIsAIModalOpen(true)}
          controlDate={controlDate}
          onControlDateChange={(ds) => setControlDate(new Date(`${ds}T00:00:00`))}
          onSaveSessionCapture={() => alert('Sesión capturada localmente')}
          onDownloadImage={() => alert('Funcionalidad de descarga activada')}
          isHistoryView={false}
          onReturnToLive={() => setControlDate(new Date())}
          view={view}
          onToggleView={(v) => setView(v)}
        />

        {view === 'dashboard' && (
          <div className="bg-white rounded-xl shadow-xl border border-slate-200 overflow-hidden">
            <div className="overflow-x-auto">
              <GeneratorTable 
                generators={sortedGenerators} 
                onSort={(key) => setSortConfig(prev => ({ key, direction: prev.key === key && prev.direction === 'ascending' ? 'descending' : 'ascending' }))} 
                sortConfig={sortConfig}
                selectedRowId={selectedRowId}
                onRowClick={setSelectedRowId}
                editingCell={editingCell}
                onCellDoubleClick={(id, key) => setEditingCell({ id, key })}
                onUpdate={handleGeneratorUpdate}
                onCancelEdit={() => setEditingCell(null)}
                onDelete={(id) => setGenerators(prev => prev.filter(g => g.id !== id))}
                isReadOnly={false}
              />
            </div>
            <Legend />
          </div>
        )}

        {view === 'reports' && (
          <ReportsView 
            reports={reports}
            generators={generators}
            onAddEntry={(name) => {
              setReports(prev => prev.map(r => r.generatorName === name ? { ...r, entries: [...r.entries, { id: Date.now(), n: String(r.entries.length + 1), geLocalidad: '', fechaAltCarga: '', entradaEnFuncionamiento: '', hIn: '', hFin: '', tdfHs: '', autonomia: '' }] } : r));
            }}
            onUpdateEntry={(name, id, key, val) => {
              setReports(prev => prev.map(r => r.generatorName === name ? { ...r, entries: r.entries.map(e => e.id === id ? { ...e, [key]: val } : e) } : r));
            }}
            onDeleteEntry={(name, id) => {
              setReports(prev => prev.map(r => r.generatorName === name ? { ...r, entries: r.entries.filter(e => e.id !== id) } : r));
            }}
            onAddReport={(name) => setReports(prev => [...prev, { generatorName: name, entries: [] }])}
          />
        )}

        {view === 'logs' && <LogsView logs={logs} />}
      </div>

      <GoogleSheetImportModal isOpen={isSheetModalOpen} onClose={() => setIsSheetModalOpen(false)} onImport={async () => {}} />
      <AIScanModal 
        isOpen={isAIModalOpen} 
        onClose={() => setIsAIModalOpen(false)} 
        generators={generators}
        onConfirmUpdate={handleAIUpdate}
      />
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { StoredGenerator } from '../types';

interface AIScanModalProps {
    isOpen: boolean;
    onClose: () => void;
    generators: StoredGenerator[];
    onConfirmUpdate: (id: number, fuel: number, hours: string) => void;
}

const AIScanModal: React.FC<AIScanModalProps> = ({ isOpen, onClose, generators, onConfirmUpdate }) => {
    const [mode, setMode] = useState<'upload' | 'camera' | 'screen'>('camera');
    const [image, setImage] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);
    const [results, setResults] = useState<{ fuel?: number; hours?: string; generatorId?: number } | null>(null);
    const [isStreamActive, setIsStreamActive] = useState(false);

    const fileInputRef = useRef<HTMLInputElement>(null);
    const videoRef = useRef<HTMLVideoElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const streamRef = useRef<MediaStream | null>(null);

    // SOPORTE PARA PEGAR DESDE FLAMESHOT (Ctrl + V)
    useEffect(() => {
        const handlePaste = (e: ClipboardEvent) => {
            const items = e.clipboardData?.items;
            if (!items) return;

            for (let i = 0; i < items.length; i++) {
                if (items[i].type.indexOf("image") !== -1) {
                    const blob = items[i].getAsFile();
                    if (blob) {
                        const reader = new FileReader();
                        reader.onload = (event) => {
                            const result = event.target?.result as string;
                            setImage(result);
                            stopMedia();
                            setMode('upload');
                        };
                        reader.readAsDataURL(blob);
                        break;
                    }
                }
            }
        };

        if (isOpen) {
            window.addEventListener('paste', handlePaste);
        }
        return () => window.removeEventListener('paste', handlePaste);
    }, [isOpen]);

    useEffect(() => {
        if (!isOpen) {
            stopMedia();
        }
    }, [isOpen]);

    const stopMedia = () => {
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
            streamRef.current = null;
        }
        if (videoRef.current) {
            videoRef.current.srcObject = null;
        }
        setIsStreamActive(false);
    };

    const handleStream = async (stream: MediaStream) => {
        if (videoRef.current) {
            videoRef.current.srcObject = stream;
            streamRef.current = stream;

            try {
                // Forzamos el inicio del video. Es vital para capturar el frame luego.
                await videoRef.current.play();
                setIsStreamActive(true);
            } catch (err) {
                console.error("No se pudo iniciar la reproducción del stream:", err);
                setIsStreamActive(false);
            }
        }
    };

    const startCamera = async () => {
        stopMedia();
        setMode('camera');
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ 
                video: { facingMode: 'environment', width: { ideal: 1920 }, height: { ideal: 1080 } }, 
                audio: false 
            });
            await handleStream(stream);
        } catch (err) {
            console.error("Error al acceder a la cámara:", err);
            alert("No se pudo acceder a la cámara. Verifica los permisos.");
            setMode('upload');
        }
    };

    const startScreenCapture = async () => {
        stopMedia();
        setMode('screen');
        try {
            // El navegador mostrará el diálogo de selección de pantalla
            const stream = await navigator.mediaDevices.getDisplayMedia({ 
                video: { 
                    cursor: "always",
                    displaySurface: "browser"
                } as any, 
                audio: false 
            });

            await handleStream(stream);

            stream.getVideoTracks()[0].onended = () => {
                stopMedia();
            };
        } catch (err) {
            console.error("Error en captura de pantalla:", err);
            if (err instanceof Error && err.name !== 'NotAllowedError') {
                alert("Error al intentar capturar la pantalla. Si usas Linux Wayland, revisa tu xdg-desktop-portal.");
            }
            setIsStreamActive(false);
        }
    };

    const handleModeChange = (newMode: 'upload' | 'camera' | 'screen') => {
        setImage(null);
        setResults(null);
        if (newMode === 'upload') {
            stopMedia();
            setMode('upload');
        } else if (newMode === 'camera') {
            startCamera();
        } else if (newMode === 'screen') {
            startScreenCapture();
        }
    };

    const captureFrame = () => {
        if (videoRef.current && canvasRef.current && isStreamActive) {
            const video = videoRef.current;
            const canvas = canvasRef.current;

            if (video.videoWidth === 0) {
                alert("El video no ha cargado aún. Espera un segundo.");
                return;
            }

            canvas.width = video.videoWidth;
            canvas.height = video.videoHeight;
            const ctx = canvas.getContext('2d');
            if (ctx) {
                ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
                setImage(canvas.toDataURL('image/jpeg', 0.9));
                stopMedia();
            }
        }
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (ev) => setImage(ev.target?.result as string);
            reader.readAsDataURL(file);
        }
    };

    const runAI = async () => {
        if (!image) return;
        setLoading(true);
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const base64Data = image.split(',')[1];

            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: [{
                    parts: [
                        { text: "Eres un asistente de monitoreo. Analiza esta imagen. Extrae: 1. Nivel combustible (0-100), 2. Horas ejecución totales (texto), 3. Nombre del generador. Devuelve JSON: { 'fuelLevel': number, 'executionHours': 'string', 'name': 'string' }. Si falta algo, devuelve 0 o vacío." },
                        { inlineData: { mimeType: "image/jpeg", data: base64Data } }
                    ]
                }],
                config: { responseMimeType: "application/json" }
            });

            const data = JSON.parse(response.text || '{}');
            let matchedId: number | undefined;
            if (data.name) {
                const found = generators.find(g => g.name.toLowerCase().includes(data.name.toLowerCase()));
                if (found) matchedId = found.id;
            }

            setResults({
                fuel: data.fuelLevel,
                hours: data.executionHours,
                generatorId: matchedId
            });
        } catch (error) {
            console.error(error);
            alert("Error al procesar con IA. Intenta con una imagen más clara.");
        } finally {
            setLoading(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-md flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-3xl shadow-2xl w-full max-w-5xl overflow-hidden border border-slate-200 flex flex-col max-h-[95vh]">
                <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                    <div className="flex flex-col sm:flex-row sm:items-center gap-4">
                        <h2 className="text-xl font-black text-slate-800 tracking-tight flex items-center gap-2">
                            <span className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white text-xs">AI</span>
                            AUTOMATIZACIÓN POR IA
                        </h2>
                        {!image && !loading && (
                            <div className="flex bg-slate-200 p-1 rounded-xl text-[10px] font-black tracking-wider">
                                <button onClick={() => handleModeChange('camera')} className={`px-4 py-2 rounded-lg transition-all ${mode === 'camera' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>CÁMARA</button>
                                <button onClick={() => handleModeChange('screen')} className={`px-4 py-2 rounded-lg transition-all ${mode === 'screen' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>PANTALLA</button>
                                <button onClick={() => handleModeChange('upload')} className={`px-4 py-2 rounded-lg transition-all ${mode === 'upload' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>ARCHIVO</button>
                            </div>
                        )}
                    </div>
                    <button onClick={onClose} className="text-slate-400 hover:text-slate-600 p-2 bg-slate-100 rounded-full transition-colors">
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                </div>

                <div className="flex-1 overflow-y-auto p-6 bg-slate-50/50">
                    {!image ? (
                        <div className="h-[450px]">
                            {mode === 'camera' || mode === 'screen' ? (
                                <div className="relative h-full bg-slate-900 rounded-2xl overflow-hidden border-4 border-white shadow-2xl flex items-center justify-center">
                                    <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-contain" />

                                    {!isStreamActive && (
                                        <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-900 text-white gap-6 text-center px-6">
                                            <div className="w-16 h-16 bg-white/10 rounded-full flex items-center justify-center animate-pulse">
                                                <svg className="w-8 h-8 text-white/40" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
                                            </div>
                                            <div className="space-y-2">
                                                <p className="text-lg font-bold">Fuente Inactiva</p>
                                                <p className="text-slate-400 text-sm">Haz clic abajo para {mode === 'camera' ? 'abrir cámara' : 'compartir pantalla'}.</p>
                                            </div>
                                            <button onClick={() => mode === 'camera' ? startCamera() : startScreenCapture()} className="px-8 py-4 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl font-black text-sm uppercase tracking-widest transition-all">
                                                ACTIVAR CAPTURA
                                            </button>
                                        </div>
                                    )}

                                    {isStreamActive && (
                                        <div className="absolute bottom-10 left-0 right-0 flex flex-col items-center gap-4">
                                            <button onClick={captureFrame} className="group relative w-24 h-24 bg-white rounded-full p-1 shadow-2xl transition-all active:scale-90">
                                                <div className="w-full h-full rounded-full border-4 border-slate-100 flex items-center justify-center">
                                                    <div className="w-16 h-16 bg-indigo-600 rounded-full group-hover:bg-indigo-500 shadow-inner" />
                                                </div>
                                            </button>
                                            <span className="text-white text-[11px] font-black tracking-widest uppercase bg-black/60 px-6 py-2 rounded-full backdrop-blur-md">Tomar Captura</span>
                                        </div>
                                    )}
                                </div>
                            ) : (
                                <div onClick={() => fileInputRef.current?.click()} className="h-full border-4 border-dashed border-slate-200 rounded-3xl flex flex-col items-center justify-center gap-6 cursor-pointer hover:border-indigo-400 hover:bg-indigo-50/30 transition-all group bg-white">
                                    <div className="w-24 h-24 bg-slate-50 rounded-3xl flex items-center justify-center group-hover:bg-indigo-100 transition-colors">
                                        <svg className="w-12 h-12 text-slate-400 group-hover:text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                                    </div>
                                    <div className="text-center">
                                        <p className="font-black text-slate-800 text-xl">Sube una Imagen o <span className="text-indigo-600 underline">Pega (Ctrl+V)</span></p>
                                        <p className="text-sm text-slate-500 max-w-xs mx-auto mt-2">Usa Flameshot para capturar y pega aquí directamente.</p>
                                    </div>
                                    <span className="px-8 py-3 bg-slate-800 text-white rounded-2xl text-xs font-black uppercase tracking-widest transition-all">Explorar Archivos</span>
                                </div>
                            )}
                        </div>
                    ) : (
                        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 min-h-[450px]">
                            <div className="relative rounded-3xl overflow-hidden bg-slate-900 border-4 border-white shadow-2xl flex items-center justify-center">
                                <img src={image} className="max-w-full max-h-full object-contain" alt="Captured" />
                                <div className="absolute bottom-4 left-4 right-4 flex justify-between">
                                    <button onClick={() => {setImage(null); setResults(null); if (mode !== 'upload') handleModeChange(mode);}} className="bg-white/90 hover:bg-white text-slate-800 px-5 py-2.5 rounded-2xl text-xs font-black shadow-xl flex items-center gap-2">
                                        REPETIR CAPTURA
                                    </button>
                                </div>
                            </div>

                            <div className="flex flex-col justify-center">
                                {loading ? (
                                    <div className="bg-white p-12 rounded-[2.5rem] border border-slate-200 shadow-xl flex flex-col items-center gap-8 text-center">
                                        <div className="relative w-24 h-24"><div className="absolute inset-0 border-8 border-indigo-600 border-t-transparent rounded-full animate-spin" /></div>
                                        <p className="text-2xl font-black text-slate-800">Analizando con Gemini...</p>
                                    </div>
                                ) : results ? (
                                    <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-xl space-y-8">
                                        <div className="space-y-6">
                                            <div>
                                                <label className="text-[10px] font-black text-slate-400 block mb-2 tracking-widest uppercase text-center">Generador Detectado:</label>
                                                <select value={results.generatorId || ''} onChange={(e) => setResults({...results, generatorId: Number(e.target.value)})} className="w-full p-5 bg-slate-50 rounded-2xl border-2 border-slate-100 text-sm font-bold outline-none">
                                                    <option value="">-- Seleccionar --</option>
                                                    {generators.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                                                </select>
                                            </div>
                                            <div className="grid grid-cols-2 gap-6">
                                                <div className="bg-slate-50 p-5 rounded-2xl border-2 border-slate-100 text-center">
                                                    <label className="text-[10px] font-black text-slate-400 block mb-3 uppercase">Combustible</label>
                                                    <input type="number" value={results.fuel || 0} onChange={(e) => setResults({...results, fuel: Number(e.target.value)})} className="w-full text-center bg-transparent text-4xl font-black text-slate-800 focus:outline-none" />
                                                </div>
                                                <div className="bg-slate-50 p-5 rounded-2xl border-2 border-slate-100 text-center">
                                                    <label className="text-[10px] font-black text-slate-400 block mb-3 uppercase">Horas Ejec.</label>
                                                    <input type="text" value={results.hours || ''} onChange={(e) => setResults({...results, hours: e.target.value})} className="w-full text-center bg-transparent text-2xl font-black text-slate-800 focus:outline-none" />
                                                </div>
                                            </div>
                                        </div>
                                        <button disabled={!results.generatorId} onClick={() => { if (results.generatorId) onConfirmUpdate(results.generatorId, results.fuel || 0, results.hours || '0'); onClose(); }} className="w-full py-6 bg-emerald-600 hover:bg-emerald-500 text-white rounded-2xl font-black text-xl shadow-2xl transition-all">SINCRONIZAR DATOS</button>
                                    </div>
                                ) : (
                                    <button onClick={runAI} className="w-full py-12 bg-indigo-600 hover:bg-indigo-500 text-white rounded-[2.5rem] font-black text-3xl shadow-2xl transition-all">PROCESAR IMAGEN</button>
                                )}
                            </div>
                        </div>
                    )}
                </div>
                <canvas ref={canvasRef} className="hidden" />
                <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept="image/*" />
            </div>
        </div>
    );
};

export default AIScanModal;

import React, { useState, useMemo, useCallback, useEffect } from 'react';
import { Generator, StoredGenerator, Status, SortConfig, Report, ChangeLog } from './types';
import { INITIAL_GENERATORS, EXCEL_GENERATORS } from './constants';
import GeneratorTable from './components/GeneratorTable';
import Header from './components/Header';
import Legend from './components/Legend';
import ReportsView from './components/ReportsView';
import GoogleSheetImportModal from './components/GoogleSheetImportModal';
import AIScanModal from './components/AIScanModal';
import LogsView from './components/LogsView';

const calculateDaysSince = (dateStr: string, fromDate: Date): number => {
  const parts = dateStr.split('/');
  if (parts.length !== 3) return 0;
  const [day, month, year] = parts;
  const formattedDate = new Date(`${year}-${month}-${day}`);
  if (isNaN(formattedDate.getTime())) return 0;

  const controlDate = new Date(fromDate);
  controlDate.setHours(0, 0, 0, 0);
  formattedDate.setHours(0,0,0,0);

  const diffTime = controlDate.getTime() - formattedDate.getTime();
  if (diffTime < 0) return 0;
  return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
};

const App: React.FC = () => {
  const [view, setView] = useState<'dashboard' | 'reports' | 'logs'>('dashboard');

  const [generators, setGenerators] = useState<StoredGenerator[]>(() => {
    try {
      const saved = localStorage.getItem('generators');
      return saved ? JSON.parse(saved) : INITIAL_GENERATORS;
    } catch {
      return INITIAL_GENERATORS;
    }
  });

  const [logs, setLogs] = useState<ChangeLog[]>(() => {
    try {
      const saved = localStorage.getItem('change_logs');
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  const [reports, setReports] = useState<Report[]>(() => {
    try {
        const saved = localStorage.getItem('reports');
        return saved ? JSON.parse(saved) : EXCEL_GENERATORS.map(name => ({ generatorName: name, entries: [] }));
    } catch {
        return [];
    }
  });

  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'name', direction: 'ascending' });
  const [selectedRowId, setSelectedRowId] = useState<number | null>(null);
  const [editingCell, setEditingCell] = useState<{ id: number; key: keyof Generator } | null>(null);
  const [controlDate, setControlDate] = useState(new Date());
  const [isSheetModalOpen, setIsSheetModalOpen] = useState(false);
  const [isAIModalOpen, setIsAIModalOpen] = useState(false);

  // AUTOMATIZACIÓN: Refrescar cada 5 minutos
  useEffect(() => {
    const refreshInterval = setInterval(() => {
      console.log("Sincronizando dashboard (Refresco de 5 minutos)...");
      setControlDate(new Date());
    }, 5 * 60 * 1000);

    return () => clearInterval(refreshInterval);
  }, []);

  useEffect(() => {
    localStorage.setItem('generators', JSON.stringify(generators));
    localStorage.setItem('reports', JSON.stringify(reports));
    localStorage.setItem('change_logs', JSON.stringify(logs));
  }, [generators, reports, logs]);

  const addLog = (generatorName: string, field: string, oldVal: any, newVal: any, source: ChangeLog['source']) => {
    const newLog: ChangeLog = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toISOString(),
      generatorName,
      field,
      oldValue: oldVal,
      newValue: newVal,
      source
    };
    setLogs(prev => [newLog, ...prev].slice(0, 500));
  };

  const calculateStatus = (fuelLevel: number): Status => {
    if (fuelLevel >= 71) return Status.Optimal;
    if (fuelLevel === 70) return Status.Warning;
    return Status.NeedsRecharge;
  };

  const processedGenerators: Generator[] = useMemo(() => {
    return generators.map(g => ({
      ...g,
      status: calculateStatus(g.fuelLevel),
      timeSinceLastRecharge: calculateDaysSince(g.lastRechargeDate, controlDate),
    }));
  }, [generators, controlDate]);

  const sortedGenerators = useMemo(() => {
    const sortableItems = [...processedGenerators];
    if (sortConfig.key) {
      sortableItems.sort((a, b) => {
        const aValue = a[sortConfig.key];
        const bValue = b[sortConfig.key];
        if (typeof aValue === 'string' && typeof bValue === 'string') {
          return sortConfig.direction === 'ascending' ? aValue.localeCompare(bValue) : bValue.localeCompare(aValue);
        }
        return sortConfig.direction === 'ascending' ? (aValue as number) - (bValue as number) : (bValue as number) - (aValue as number);
      });
    }
    return sortableItems;
  }, [processedGenerators, sortConfig]);

  const handleGeneratorUpdate = (id: number, key: keyof StoredGenerator, value: string, source: ChangeLog['source'] = 'Manual') => {
    setGenerators(prev => 
      prev.map(gen => {
        if (gen.id === id) {
          let updatedValue: string | number = value;
          if (key === 'fuelLevel') {
            const numericValue = parseFloat(value.replace(',', '.'));
            updatedValue = isNaN(numericValue) ? gen[key] : numericValue;
          }

          if (gen[key] !== updatedValue) {
            addLog(gen.name, key, gen[key], updatedValue, source);
          }

          return { ...gen, [key]: updatedValue };
        }
        return gen;
      })
    );
    setEditingCell(null);
  };

  const handleAIUpdate = (id: number, fuel: number, hours: string) => {
    handleGeneratorUpdate(id, 'fuelLevel', String(fuel), 'AI');
    handleGeneratorUpdate(id, 'executionHours', hours, 'AI');
  };

  return (
    <div className="min-h-screen bg-slate-50 p-4 sm:p-6 lg:p-8 font-sans">
      <div id="capture-container" className="max-w-7xl mx-auto space-y-6">
        <Header 
          onAddGenerator={() => {
            const newId = generators.length > 0 ? Math.max(...generators.map(g => g.id)) + 1 : 1;
            setGenerators(prev => [...prev, {
              id: newId,
              name: `Generador ${newId}`,
              executionHours: '0 Hr',
              fuelLevel: 100,
              lastRechargeDate: new Date().toLocaleDateString('es-ES')
            }]);
          }}
          onFileUpload={() => {}}
          onGoogleSheetImportClick={() => setIsSheetModalOpen(true)}
          onAIScanClick={() => setIsAIModalOpen(true)}
          controlDate={controlDate}
          onControlDateChange={(ds) => setControlDate(new Date(`${ds}T00:00:00`))}
          onSaveSessionCapture={() => alert('Sesión capturada localmente')}
          onDownloadImage={() => alert('Funcionalidad de descarga activada')}
          isHistoryView={false}
          onReturnToLive={() => setControlDate(new Date())}
          view={view}
          onToggleView={(v) => setView(v)}
        />

        {view === 'dashboard' && (
          <div className="bg-white rounded-xl shadow-xl border border-slate-200 overflow-hidden">
            <div className="overflow-x-auto">
              <GeneratorTable 
                generators={sortedGenerators} 
                onSort={(key) => setSortConfig(prev => ({ key, direction: prev.key === key && prev.direction === 'ascending' ? 'descending' : 'ascending' }))} 
                sortConfig={sortConfig}
                selectedRowId={selectedRowId}
                onRowClick={setSelectedRowId}
                editingCell={editingCell}
                onCellDoubleClick={(id, key) => setEditingCell({ id, key })}
                onUpdate={handleGeneratorUpdate}
                onCancelEdit={() => setEditingCell(null)}
                onDelete={(id) => setGenerators(prev => prev.filter(g => g.id !== id))}
                isReadOnly={false}
              />
            </div>
            <Legend />
          </div>
        )}

        {view === 'reports' && (
          <ReportsView 
            reports={reports}
            generators={generators}
            onAddEntry={(name) => {
              setReports(prev => prev.map(r => r.generatorName === name ? { ...r, entries: [...r.entries, { id: Date.now(), n: String(r.entries.length + 1), geLocalidad: '', fechaAltCarga: '', entradaEnFuncionamiento: '', hIn: '', hFin: '', tdfHs: '', autonomia: '' }] } : r));
            }}
            onUpdateEntry={(name, id, key, val) => {
              setReports(prev => prev.map(r => r.generatorName === name ? { ...r, entries: r.entries.map(e => e.id === id ? { ...e, [key]: val } : e) } : r));
            }}
            onDeleteEntry={(name, id) => {
              setReports(prev => prev.map(r => r.generatorName === name ? { ...r, entries: r.entries.filter(e => e.id !== id) } : r));
            }}
            onAddReport={(name) => setReports(prev => [...prev, { generatorName: name, entries: [] }])}
          />
        )}

        {view === 'logs' && <LogsView logs={logs} />}
      </div>

      <GoogleSheetImportModal isOpen={isSheetModalOpen} onClose={() => setIsSheetModalOpen(false)} onImport={async () => {}} />
      <AIScanModal 
        isOpen={isAIModalOpen} 
        onClose={() => setIsAIModalOpen(false)} 
        generators={generators}
        onConfirmUpdate={handleAIUpdate}
      />
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { StoredGenerator } from '../types';

interface AIScanModalProps {
    isOpen: boolean;
    onClose: () => void;
    generators: StoredGenerator[];
    onConfirmUpdate: (id: number, fuel: number, hours: string) => void;
}

const AIScanModal: React.FC<AIScanModalProps> = ({ isOpen, onClose, generators, onConfirmUpdate }) => {
    const [mode, setMode] = useState<'upload' | 'camera' | 'screen'>('camera');
    const [image, setImage] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);
    const [results, setResults] = useState<{ fuel?: number; hours?: string; generatorId?: number } | null>(null);
    const [isStreamActive, setIsStreamActive] = useState(false);
    const [showHelp, setShowHelp] = useState(false);

    const fileInputRef = useRef<HTMLInputElement>(null);
    const videoRef = useRef<HTMLVideoElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const streamRef = useRef<MediaStream | null>(null);

    // SOPORTE PARA PEGAR DESDE EL PORTAPAPELES (Ideal para Flameshot)
    useEffect(() => {
        const handlePaste = (e: ClipboardEvent) => {
            const items = e.clipboardData?.items;
            if (!items) return;

            for (let i = 0; i < items.length; i++) {
                if (items[i].type.indexOf("image") !== -1) {
                    const blob = items[i].getAsFile();
                    if (blob) {
                        const reader = new FileReader();
                        reader.onload = (event) => {
                            const result = event.target?.result as string;
                            setImage(result);
                            stopMedia();
                            setMode('upload');
                        };
                        reader.readAsDataURL(blob);
                        break;
                    }
                }
            }
        };

        if (isOpen) {
            window.addEventListener('paste', handlePaste);
        }
        return () => window.removeEventListener('paste', handlePaste);
    }, [isOpen]);

    useEffect(() => {
        if (!isOpen) {
            stopMedia();
        }
    }, [isOpen]);

    const stopMedia = () => {
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
            streamRef.current = null;
        }
        if (videoRef.current) {
            videoRef.current.srcObject = null;
        }
        setIsStreamActive(false);
    };

    const handleStream = async (stream: MediaStream) => {
        if (videoRef.current) {
            videoRef.current.srcObject = stream;
            streamRef.current = stream;

            try {
                // Forzamos el play con manejo de promesa para navegadores modernos
                await videoRef.current.play();
                setIsStreamActive(true);
            } catch (err) {
                console.error("Error al iniciar reproducción:", err);
                setIsStreamActive(false);
            }
        }
    };

    const startCamera = async () => {
        stopMedia();
        setMode('camera');
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ 
                video: { facingMode: 'environment', width: { ideal: 1920 }, height: { ideal: 1080 } }, 
                audio: false 
            });
            await handleStream(stream);
        } catch (err) {
            console.error("Error de cámara:", err);
            alert("Acceso denegado a la cámara.");
            setMode('upload');
        }
    };

    const startScreenCapture = async () => {
        stopMedia();
        setMode('screen');
        try {
            const stream = await navigator.mediaDevices.getDisplayMedia({ 
                video: { 
                    cursor: "always",
                    displaySurface: "browser" 
                } as any, 
                audio: false 
            });

            await handleStream(stream);

            stream.getVideoTracks()[0].onended = () => {
                stopMedia();
            };
        } catch (err) {
            console.error("Error de captura:", err);
            const isLinux = navigator.userAgent.toLowerCase().includes('linux');
            if (isLinux) {
                setShowHelp(true);
            } else {
                alert("No se pudo iniciar la captura de pantalla.");
            }
            setIsStreamActive(false);
        }
    };

    const handleModeChange = (newMode: 'upload' | 'camera' | 'screen') => {
        setImage(null);
        setResults(null);
        setShowHelp(false);
        if (newMode === 'upload') {
            stopMedia();
            setMode('upload');
        } else if (newMode === 'camera') {
            startCamera();
        } else if (newMode === 'screen') {
            startScreenCapture();
        }
    };

    const captureFrame = () => {
        if (videoRef.current && canvasRef.current && isStreamActive) {
            const video = videoRef.current;
            const canvas = canvasRef.current;

            if (video.videoWidth === 0) return;

            canvas.width = video.videoWidth;
            canvas.height = video.videoHeight;
            const ctx = canvas.getContext('2d');
            if (ctx) {
                ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
                setImage(canvas.toDataURL('image/jpeg', 0.9));
                stopMedia();
            }
        }
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (ev) => setImage(ev.target?.result as string);
            reader.readAsDataURL(file);
        }
    };

    const runAI = async () => {
        if (!image) return;
        setLoading(true);
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const base64Data = image.split(',')[1];

            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: [{
                    parts: [
                        { text: "Analiza la imagen de este generador o tablero. Extrae: 1. Nivel de combustible (0-100), 2. Horas de ejecución (número o texto), 3. Nombre del generador si aparece. Devuelve JSON: { 'fuelLevel': number, 'executionHours': 'string', 'name': 'string' }." },
                        { inlineData: { mimeType: "image/jpeg", data: base64Data } }
                    ]
                }],
                config: { responseMimeType: "application/json" }
            });

            const data = JSON.parse(response.text || '{}');
            let matchedId: number | undefined;
            if (data.name) {
                const found = generators.find(g => g.name.toLowerCase().includes(data.name.toLowerCase()));
                if (found) matchedId = found.id;
            }

            setResults({
                fuel: data.fuelLevel,
                hours: data.executionHours,
                generatorId: matchedId
            });
        } catch (error) {
            console.error(error);
            alert("Error al procesar con IA. Intente con una imagen más clara.");
        } finally {
            setLoading(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-md flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-3xl shadow-2xl w-full max-w-5xl overflow-hidden border border-slate-200 flex flex-col max-h-[95vh]">
                {/* Header */}
                <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                    <div className="flex flex-col sm:flex-row sm:items-center gap-4">
                        <h2 className="text-xl font-black text-slate-800 tracking-tight flex items-center gap-2">
                            <span className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white text-xs">AI</span>
                            SISTEMA AUTOMATIZADO
                        </h2>
                        {!image && !loading && (
                            <div className="flex bg-slate-200 p-1 rounded-xl text-[10px] font-black tracking-wider">
                                <button onClick={() => handleModeChange('camera')} className={`px-4 py-2 rounded-lg transition-all ${mode === 'camera' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>CÁMARA</button>
                                <button onClick={() => handleModeChange('screen')} className={`px-4 py-2 rounded-lg transition-all ${mode === 'screen' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>PANTALLA</button>
                                <button onClick={() => handleModeChange('upload')} className={`px-4 py-2 rounded-lg transition-all ${mode === 'upload' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>ARCHIVO</button>
                            </div>
                        )}
                    </div>
                    <button onClick={onClose} className="text-slate-400 hover:text-slate-600 p-2 bg-slate-100 rounded-full transition-colors">
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                </div>

                {/* Content */}
                <div className="flex-1 overflow-y-auto p-6 bg-slate-50/50">
                    {!image ? (
                        <div className="h-[450px]">
                            {mode === 'camera' || mode === 'screen' ? (
                                <div className="relative h-full bg-slate-900 rounded-2xl overflow-hidden border-4 border-white shadow-2xl flex items-center justify-center">
                                    <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-contain" />

                                    {!isStreamActive && (
                                        <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-900 text-white gap-6 text-center px-6">
                                            {showHelp ? (
                                                <div className="max-w-md space-y-4">
                                                    <div className="bg-amber-500/10 border border-amber-500/20 p-4 rounded-xl text-amber-200 text-sm">
                                                        <p className="font-bold mb-2">Entorno Wayland Detectado</p>
                                                        <ul className="text-left space-y-2 list-disc pl-4 opacity-80">
                                                            <li>Instala <code>xdg-desktop-portal-gnome</code> (o el de tu escritorio).</li>
                                                            <li>Si usas Flameshot: captura, copia al portapapeles y presiona <b>Ctrl+V</b> aquí.</li>
                                                            <li>En Chrome/Edge: Activa <code>chrome://flags/#enable-webrtc-pipewire-capturer</code>.</li>
                                                        </ul>
                                                    </div>
                                                    <button onClick={() => handleModeChange('screen')} className="bg-white text-slate-900 px-6 py-2 rounded-xl font-bold">Reintentar Captura</button>
                                                </div>
                                            ) : (
                                                <>
                                                    <div className="w-16 h-16 bg-white/10 rounded-full flex items-center justify-center animate-pulse">
                                                        <svg className="w-8 h-8 text-white/40" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
                                                    </div>
                                                    <p className="text-lg font-bold">Fuente Inactiva</p>
                                                    <button onClick={() => mode === 'camera' ? startCamera() : startScreenCapture()} className="px-8 py-4 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl font-black text-sm uppercase tracking-widest transition-all">
                                                        Activar {mode === 'camera' ? 'Cámara' : 'Captura'}
                                                    </button>
                                                </>
                                            )}
                                        </div>
                                    )}

                                    {isStreamActive && (
                                        <div className="absolute bottom-10 left-0 right-0 flex flex-col items-center gap-4">
                                            <button onClick={captureFrame} className="group relative w-20 h-20 bg-white rounded-full p-1 shadow-2xl transition-all active:scale-90">
                                                <div className="w-full h-full rounded-full border-4 border-slate-100 flex items-center justify-center">
                                                    <div className="w-14 h-14 bg-indigo-600 rounded-full group-hover:bg-indigo-500" />
                                                </div>
                                            </button>
                                            <span className="text-white text-[10px] font-black tracking-widest uppercase bg-black/50 px-4 py-1.5 rounded-full">Tomar Captura</span>
                                        </div>
                                    )}
                                </div>
                            ) : (
                                <div onClick={() => fileInputRef.current?.click()} className="h-full border-4 border-dashed border-slate-200 rounded-3xl flex flex-col items-center justify-center gap-6 cursor-pointer hover:border-indigo-400 hover:bg-indigo-50/30 transition-all group bg-white">
                                    <div className="text-center">
                                        <p className="font-black text-slate-800 text-xl">Sube una Imagen o <span className="text-indigo-600 underline">Pega (Ctrl+V)</span></p>
                                        <p className="text-sm text-slate-500 max-w-xs mx-auto mt-2 italic">Tip: Usa Flameshot para capturar y pega aquí directamente.</p>
                                    </div>
                                    <span className="px-8 py-3 bg-slate-800 text-white rounded-2xl text-xs font-black uppercase tracking-widest transition-all">Seleccionar Archivo</span>
                                </div>
                            )}
                        </div>
                    ) : (
                        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 min-h-[450px]">
                            <div className="relative rounded-3xl overflow-hidden bg-slate-900 border-4 border-white shadow-2xl flex items-center justify-center">
                                <img src={image} className="max-w-full max-h-full object-contain" alt="Captured" />
                                <button onClick={() => {setImage(null); setResults(null); if (mode !== 'upload') handleModeChange(mode);}} className="absolute bottom-4 right-4 bg-white/90 hover:bg-white text-slate-800 px-4 py-2 rounded-xl text-xs font-black shadow-xl">REPETIR</button>
                            </div>

                            <div className="flex flex-col justify-center">
                                {loading ? (
                                    <div className="bg-white p-12 rounded-[2rem] border border-slate-200 shadow-xl flex flex-col items-center gap-4">
                                        <div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin" />
                                        <p className="text-xl font-black text-slate-800">Procesando con IA...</p>
                                    </div>
                                ) : results ? (
                                    <div className="bg-white p-8 rounded-[2rem] border border-slate-200 shadow-xl space-y-6">
                                        <div className="space-y-4">
                                            <div>
                                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Generador Detectado:</label>
                                                <select value={results.generatorId || ''} onChange={(e) => setResults({...results, generatorId: Number(e.target.value)})} className="w-full p-4 bg-slate-50 rounded-xl border border-slate-200 font-bold outline-none">
                                                    <option value="">-- Seleccionar Generador --</option>
                                                    {generators.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                                                </select>
                                            </div>
                                            <div className="grid grid-cols-2 gap-4">
                                                <div className="bg-slate-50 p-4 rounded-xl border border-slate-200">
                                                    <label className="text-[10px] font-black text-slate-400 uppercase">Combustible</label>
                                                    <input type="number" value={results.fuel || 0} onChange={(e) => setResults({...results, fuel: Number(e.target.value)})} className="w-full bg-transparent text-2xl font-black text-slate-800 focus:outline-none" />
                                                </div>
                                                <div className="bg-slate-50 p-4 rounded-xl border border-slate-200">
                                                    <label className="text-[10px] font-black text-slate-400 uppercase">Horas Ejec.</label>
                                                    <input type="text" value={results.hours || ''} onChange={(e) => setResults({...results, hours: e.target.value})} className="w-full bg-transparent text-xl font-black text-slate-800 focus:outline-none" />
                                                </div>
                                            </div>
                                        </div>
                                        <button disabled={!results.generatorId} onClick={() => { if (results.generatorId) onConfirmUpdate(results.generatorId, results.fuel || 0, results.hours || '0'); onClose(); }} className="w-full py-5 bg-emerald-600 hover:bg-emerald-500 text-white rounded-xl font-black text-lg shadow-xl transition-all disabled:opacity-50">Sincronizar Datos</button>
                                    </div>
                                ) : (
                                    <button onClick={runAI} className="w-full py-10 bg-indigo-600 hover:bg-indigo-500 text-white rounded-[2rem] font-black text-2xl shadow-xl transition-all">PROCESAR IMAGEN</button>
                                )}
                            </div>
                        </div>
                    )}
                </div>
                <canvas ref={canvasRef} className="hidden" />
                <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept="image/*" />
            </div>
        </div>
    );
};

