                      className="bg-slate-900/50 text-white rounded-lg border border-slate-700 px-3 py-1.5 text-sm print:hidden"
                  />
                  <span className="hidden print:inline text-sm font-bold">{controlDate.toLocaleDateString()}</span>
                </div>
              </div>
            )}
        </header>
    );
};

