                            onUpdateEntry={(entryId, key, val) => onUpdateEntry(report.id, entryId, key, val)}
                            onDeleteEntry={(entryId) => onDeleteEntry(report.id, entryId)}
                        />
                    ))
                )}
            </div>

            <div className="bg-slate-900 text-white font-black p-4 text-center rounded-2xl shadow-xl print:bg-slate-100 print:text-slate-900">
                INFO ADICIONAL: RECTIFICADOR TRAEMEC GUAICOS 101.1.255.32 - Pass: 28834
            </div>
        </div>
    );
};

