import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { StoredGenerator } from '../types';

interface AIScanModalProps {
    isOpen: boolean;
    onClose: () => void;
    generators: StoredGenerator[];
    onConfirmUpdate: (id: number, fuel: number, hours: string) => void;
}

const AIScanModal: React.FC<AIScanModalProps> = ({ isOpen, onClose, generators, onConfirmUpdate }) => {
    const [mode, setMode] = useState<'upload' | 'camera' | 'screen'>('camera');
    const [image, setImage] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);
    const [results, setResults] = useState<{ fuel?: number; hours?: string; generatorId?: number } | null>(null);
    const [isStreamActive, setIsStreamActive] = useState(false);
    const [flashEffect, setFlashEffect] = useState(false);

    const fileInputRef = useRef<HTMLInputElement>(null);
    const videoRef = useRef<HTMLVideoElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const streamRef = useRef<MediaStream | null>(null);

    useEffect(() => {
        const handlePaste = (e: ClipboardEvent) => {
            const items = e.clipboardData?.items;
            if (!items) return;

            for (let i = 0; i < items.length; i++) {
                if (items[i].type.indexOf("image") !== -1) {
                    const blob = items[i].getAsFile();
                    if (blob) {
                        const reader = new FileReader();
                        reader.onload = (event) => {
                            const result = event.target?.result as string;
                            setImage(result);
                            stopMedia();
                            setMode('upload');
                        };
                        reader.readAsDataURL(blob);
                        break;
                    }
                }
            }
        };

        if (isOpen) {
            window.addEventListener('paste', handlePaste);
        }
        return () => window.removeEventListener('paste', handlePaste);
    }, [isOpen]);

    useEffect(() => {
        if (!isOpen) {
            stopMedia();
        }
    }, [isOpen]);

    const stopMedia = () => {
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
            streamRef.current = null;
        }
        if (videoRef.current) {
            videoRef.current.srcObject = null;
        }
        setIsStreamActive(false);
    };

    const handleStream = async (stream: MediaStream) => {
        if (videoRef.current) {
            videoRef.current.srcObject = stream;
            streamRef.current = stream;

            try {
                await videoRef.current.play();
                setIsStreamActive(true);
            } catch (err) {
                console.error("Error al iniciar reproducción:", err);
                setIsStreamActive(false);
            }
        }
    };

    const startCamera = async () => {
        stopMedia();
        setMode('camera');
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ 
                video: { facingMode: 'environment', width: { ideal: 1920 }, height: { ideal: 1080 } }, 
                audio: false 
            });
            await handleStream(stream);
        } catch (err) {
            console.error("Error de cámara:", err);
            alert("Acceso denegado a la cámara.");
            setMode('upload');
        }
    };

    const startScreenCapture = async () => {
        stopMedia();
        setMode('screen');
        try {
            const stream = await navigator.mediaDevices.getDisplayMedia({ 
                video: { cursor: "always" } as any, 
                audio: false 
            });
            await handleStream(stream);
            stream.getVideoTracks()[0].onended = () => stopMedia();
        } catch (err) {
            console.error("Error de captura:", err);
            setIsStreamActive(false);
        }
    };

    const handleModeChange = (newMode: 'upload' | 'camera' | 'screen') => {
        setImage(null);
        setResults(null);
        if (newMode === 'upload') {
            stopMedia();
            setMode('upload');
        } else if (newMode === 'camera') {
            startCamera();
        } else if (newMode === 'screen') {
            startScreenCapture();
        }
    };

    const captureFrame = () => {
        if (videoRef.current && canvasRef.current && isStreamActive) {
            setFlashEffect(true);
            setTimeout(() => setFlashEffect(false), 300);

            const video = videoRef.current;
            const canvas = canvasRef.current;
            canvas.width = video.videoWidth;
            canvas.height = video.videoHeight;
            const ctx = canvas.getContext('2d');
            if (ctx) {
                ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
                setImage(canvas.toDataURL('image/jpeg', 0.95));
                setTimeout(() => stopMedia(), 100);
            }
        }
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (ev) => setImage(ev.target?.result as string);
            reader.readAsDataURL(file);
        }
    };

    const runAI = async () => {
        if (!image) return;
        setLoading(true);
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const base64Data = image.split(',')[1];

            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: [{
                    parts: [
                        { text: "Analiza la imagen de este generador o tablero. Extrae con precisión: 1. Nivel de combustible (número 0-100), 2. Horas de ejecución (número o texto como '456.1 h'), 3. Nombre del generador. Devuelve un objeto JSON con estas claves: 'fuelLevel', 'executionHours', 'name'." },
                        { inlineData: { mimeType: "image/jpeg", data: base64Data } }
                    ]
                }],
                config: { responseMimeType: "application/json" }
            });

            const data = JSON.parse(response.text || '{}');
            let matchedId: number | undefined;
            if (data.name) {
                const found = generators.find(g => g.name.toLowerCase().includes(data.name.toLowerCase()));
                if (found) matchedId = found.id;
            }

            setResults({
                fuel: data.fuelLevel,
                hours: data.executionHours,
                generatorId: matchedId
            });
        } catch (error) {
            console.error(error);
            alert("Error al procesar con IA. Asegúrese de que el texto sea legible.");
        } finally {
            setLoading(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-md flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-3xl shadow-2xl w-full max-w-5xl overflow-hidden border border-slate-200 flex flex-col max-h-[95vh]">
                <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                    <div className="flex flex-col sm:flex-row sm:items-center gap-4">
                        <h2 className="text-xl font-black text-slate-900 tracking-tight flex items-center gap-2">
                            <span className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white text-xs">AI</span>
                            SISTEMA AUTOMATIZADO
                        </h2>
                        {!image && !loading && (
                            <div className="flex bg-slate-200 p-1 rounded-xl text-[10px] font-black tracking-wider">
                                <button onClick={() => handleModeChange('camera')} className={`px-4 py-2 rounded-lg transition-all ${mode === 'camera' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>CÁMARA</button>
                                <button onClick={() => handleModeChange('screen')} className={`px-4 py-2 rounded-lg transition-all ${mode === 'screen' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>PANTALLA</button>
                                <button onClick={() => handleModeChange('upload')} className={`px-4 py-2 rounded-lg transition-all ${mode === 'upload' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>ARCHIVO</button>
                            </div>
                        )}
                    </div>
                    <button onClick={onClose} className="text-slate-400 hover:text-slate-600 p-2 bg-slate-100 rounded-full transition-colors">
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                </div>

                <div className="flex-1 overflow-y-auto p-6 bg-slate-50/50">
                    {!image ? (
                        <div className="h-[450px]">
                            {mode === 'camera' || mode === 'screen' ? (
                                <div className="relative h-full bg-slate-900 rounded-2xl overflow-hidden border-4 border-white shadow-2xl flex items-center justify-center">
                                    <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-contain" />
                                    {flashEffect && <div className="absolute inset-0 bg-white z-10 animate-pulse" />}
                                    {!isStreamActive && (
                                        <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-900 text-white gap-6 text-center px-6">
                                            <button onClick={() => mode === 'camera' ? startCamera() : startScreenCapture()} className="px-8 py-4 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl font-black text-sm uppercase tracking-widest transition-all">Activar Fuente</button>
                                            <p className="text-xs text-slate-500 max-w-xs">Permita el acceso para capturar el tablero directamente.</p>
                                        </div>
                                    )}
                                    {isStreamActive && (
                                        <div className="absolute bottom-10 left-0 right-0 flex flex-col items-center gap-4">
                                            <button 
                                                onClick={captureFrame} 
                                                className="group relative w-20 h-20 bg-white rounded-full p-1 shadow-2xl active:scale-90 transition-all border-4 border-slate-100"
                                            >
                                                <div className="w-full h-full rounded-full bg-indigo-600 group-hover:bg-indigo-500" />
                                                <span className="absolute -top-10 left-1/2 -translate-x-1/2 bg-indigo-600 text-white px-2 py-1 rounded text-[10px] font-black uppercase whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity">Capturar</span>
                                            </button>
                                        </div>
                                    )}
                                </div>
                            ) : (
                                <div onClick={() => fileInputRef.current?.click()} className="h-full border-4 border-dashed border-slate-200 rounded-3xl flex flex-col items-center justify-center gap-6 cursor-pointer hover:border-indigo-400 hover:bg-indigo-50/30 transition-all group bg-white">
                                    <div className="w-20 h-20 bg-slate-100 rounded-full flex items-center justify-center group-hover:bg-indigo-100 transition-colors">
                                        <svg className="w-10 h-10 text-slate-400 group-hover:text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                                    </div>
                                    <p className="font-black text-slate-900 text-xl text-center">Sube una Imagen o <br/><span className="text-indigo-600 underline">Pega desde Portapapeles</span></p>
                                    <span className="px-8 py-3 bg-slate-900 text-white rounded-2xl text-xs font-black uppercase tracking-widest">Seleccionar Archivo</span>
                                </div>
                            )}
                        </div>
                    ) : (
                        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 min-h-[450px]">
                            <div className="relative rounded-3xl overflow-hidden bg-slate-900 border-4 border-white shadow-2xl flex items-center justify-center">
                                <img src={image} className="max-w-full max-h-full object-contain" alt="Captured" />
                                <button onClick={() => {setImage(null); setResults(null); if (mode !== 'upload') handleModeChange(mode);}} className="absolute bottom-4 right-4 bg-white/90 hover:bg-white text-slate-900 px-4 py-2 rounded-xl text-xs font-black shadow-xl">REINICIAR</button>
                            </div>

                            <div className="flex flex-col justify-center">
                                {loading ? (
                                    <div className="bg-white p-12 rounded-[2rem] border border-slate-200 shadow-xl flex flex-col items-center gap-6 text-center">
                                        <div className="w-16 h-16 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin" />
                                        <div>
                                            <p className="text-2xl font-black text-slate-900 mb-2">Analizando Datos...</p>
                                            <p className="text-slate-500 text-sm">La inteligencia artificial está extrayendo información del tablero.</p>
                                        </div>
                                    </div>
                                ) : results ? (
                                    <div className="bg-white p-8 rounded-[2rem] border border-slate-200 shadow-xl space-y-6">
                                        <div className="space-y-4">
                                            <div>
                                                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1 block">Generador Detectado:</label>
                                                <div className="relative">
                                                    <select 
                                                        value={results.generatorId || ''} 
                                                        onChange={(e) => setResults({...results, generatorId: Number(e.target.value)})} 
                                                        className="w-full p-4 bg-slate-50 rounded-xl border border-slate-200 font-bold text-slate-900 outline-none appearance-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500"
                                                    >
                                                        <option value="" className="text-slate-400">-- Seleccionar Generador --</option>
                                                        {generators.map(g => <option key={g.id} value={g.id} className="text-slate-900">{g.name}</option>)}
                                                    </select>
                                                    <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
                                                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" /></svg>
                                                    </div>
                                                </div>
                                            </div>
                                            <div className="grid grid-cols-2 gap-4">
                                                <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 group focus-within:border-indigo-500 transition-colors">
                                                    <label className="text-[10px] font-black text-slate-500 uppercase block mb-1">Combustible %</label>
                                                    <input 
                                                        type="number" 
                                                        value={results.fuel || 0} 
                                                        onChange={(e) => setResults({...results, fuel: Number(e.target.value)})} 
                                                        className="w-full bg-transparent text-2xl font-black text-slate-900 focus:outline-none" 
                                                    />
                                                </div>
                                                <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 group focus-within:border-indigo-500 transition-colors">
                                                    <label className="text-[10px] font-black text-slate-500 uppercase block mb-1">Horas Ejec.</label>
                                                    <input 
                                                        type="text" 
                                                        value={results.hours || ''} 
                                                        onChange={(e) => setResults({...results, hours: e.target.value})} 
                                                        className="w-full bg-transparent text-xl font-black text-slate-900 focus:outline-none" 
                                                    />
                                                </div>
                                            </div>
                                        </div>
                                        <button 
                                            disabled={!results.generatorId} 
                                            onClick={() => { if (results.generatorId) onConfirmUpdate(results.generatorId, results.fuel || 0, results.hours || '0'); onClose(); }} 
                                            className="w-full py-5 bg-emerald-600 hover:bg-emerald-500 text-white rounded-2xl font-black text-lg shadow-xl transition-all disabled:opacity-30 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                                        >
                                            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" /></svg>
                                            Sincronizar Datos
                                        </button>
                                    </div>
                                ) : (
                                    <button 
                                        onClick={runAI} 
                                        className="w-full py-12 bg-indigo-600 hover:bg-indigo-500 text-white rounded-[2rem] font-black text-2xl shadow-xl transition-all flex flex-col items-center gap-4"
                                    >
                                        <span className="bg-white/20 px-4 py-1 rounded-full text-xs uppercase tracking-widest">IA Procesador</span>
                                        EXTRAER DATOS
                                    </button>
                                )}
                            </div>
                        </div>
                    )}
                </div>
                <canvas ref={canvasRef} className="hidden" />
                <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept="image/*" />
            </div>
        </div>
    );
};

export default AIScanModal;

export enum Status {
  Optimal = 'EN ESTADO OPTIMO',
  NeedsRecharge = 'NECESITA RECARGA',
  Warning = 'PROXIMO A DAR AVISO',
}

export interface Generator {
  id: number;
  name: string;
  executionHours: string;
  fuelLevel: number; // Percentage 0-100
  tankCapacity: number; // Capacidad total en litros
  lastRechargeLiters: number; // Litros cargados en la última operación
  status: Status;
  lastRechargeDate: string; // DD/MM/YYYY
  timeSinceLastRecharge: number; // in days
}

export type StoredGenerator = Omit<Generator, 'status' | 'timeSinceLastRecharge'>;

export interface SortConfig {
  key: keyof Generator;
  direction: 'ascending' | 'descending';
}

export interface ReportEntry {
  id: number;
  n: string;
  geLocalidad: string;
  fechaAltCarga: string;
  entradaEnFuncionamiento: string;
  hIn: string;
  hFin: string;
  tdfHs: string;
  autonomia: string;
  timestamp: string; // Para filtrado mensual
}

export interface Report {
  id: string;
  generatorName: string;
  month: string; // Formato YYYY-MM
  isFinalized: boolean;
  entries: ReportEntry[];
}

export interface ChangeLog {
  id: string;
  timestamp: string;
  generatorName: string;
  field: string;
  oldValue: string | number;
  newValue: string | number;
  source: 'Manual' | 'AI' | 'Excel';
}

import React, { useState, useMemo, useCallback, useEffect } from 'react';
import { Generator, StoredGenerator, Status, SortConfig, Report, ChangeLog, ReportEntry } from './types';
import { INITIAL_GENERATORS, EXCEL_GENERATORS } from './constants';
import GeneratorTable from './components/GeneratorTable';
import Header from './components/Header';
import Legend from './components/Legend';
import ReportsView from './components/ReportsView';
import GoogleSheetImportModal from './components/GoogleSheetImportModal';
import AIScanModal from './components/AIScanModal';
import LogsView from './components/LogsView';

declare var html2canvas: any;

const calculateDaysSince = (dateStr: string, fromDate: Date): number => {
  const parts = dateStr.split('/');
  if (parts.length !== 3) return 0;
  const [day, month, year] = parts;
  const formattedDate = new Date(`${year}-${month}-${day}`);
  if (isNaN(formattedDate.getTime())) return 0;

  const controlDate = new Date(fromDate);
  controlDate.setHours(0, 0, 0, 0);
  formattedDate.setHours(0,0,0,0);

  const diffTime = controlDate.getTime() - formattedDate.getTime();
  if (diffTime < 0) return 0;
  return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
};

const App: React.FC = () => {
  const [view, setView] = useState<'dashboard' | 'reports' | 'logs'>('dashboard');
  const [currentMonth, setCurrentMonth] = useState(() => new Date().toISOString().slice(0, 7));

  const [generators, setGenerators] = useState<StoredGenerator[]>(() => {
    try {
      const saved = localStorage.getItem('generators');
      return saved ? JSON.parse(saved) : INITIAL_GENERATORS;
    } catch {
      return INITIAL_GENERATORS;
    }
  });

  const [logs, setLogs] = useState<ChangeLog[]>(() => {
    try {
      const saved = localStorage.getItem('change_logs');
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  const [reports, setReports] = useState<Report[]>(() => {
    try {
        const saved = localStorage.getItem('reports_v2');
        return saved ? JSON.parse(saved) : [];
    } catch {
        return [];
    }
  });

  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'name', direction: 'ascending' });
  const [selectedRowId, setSelectedRowId] = useState<number | null>(null);
  const [editingCell, setEditingCell] = useState<{ id: number; key: keyof Generator } | null>(null);
  const [controlDate, setControlDate] = useState(new Date());
  const [isSheetModalOpen, setIsSheetModalOpen] = useState(false);
  const [isAIModalOpen, setIsAIModalOpen] = useState(false);

  useEffect(() => {
    const refreshInterval = setInterval(() => {
      setControlDate(new Date());
    }, 5 * 60 * 1000);
    return () => clearInterval(refreshInterval);
  }, []);

  useEffect(() => {
    localStorage.setItem('generators', JSON.stringify(generators));
    localStorage.setItem('reports_v2', JSON.stringify(reports));
    localStorage.setItem('change_logs', JSON.stringify(logs));
  }, [generators, reports, logs]);

  const addLog = (generatorName: string, field: string, oldVal: any, newVal: any, source: ChangeLog['source']) => {
    const newLog: ChangeLog = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toISOString(),
      generatorName,
      field,
      oldValue: oldVal,
      newValue: newVal,
      source
    };
    setLogs(prev => [newLog, ...prev].slice(0, 500));
  };

  const createReportEntryFromDashboard = (genName: string, fuel: number, hours: string) => {
    const month = new Date().toISOString().slice(0, 7);
    setReports(prev => {
      const existingReportIndex = prev.findIndex(r => r.generatorName === genName && r.month === month);
      const now = new Date();
      const timeStr = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;

      const newEntry: ReportEntry = {
        id: Date.now(),
        n: '',
        geLocalidad: genName,
        fechaAltCarga: now.toLocaleDateString('es-ES'),
        entradaEnFuncionamiento: 'SÍ',
        hIn: timeStr,
        hFin: timeStr,
        tdfHs: '0',
        autonomia: String(fuel),
        timestamp: now.toISOString()
      };

      if (existingReportIndex > -1) {
        if (prev[existingReportIndex].isFinalized) return prev;
        const updatedReports = [...prev];
        updatedReports[existingReportIndex] = {
          ...updatedReports[existingReportIndex],
          entries: [...updatedReports[existingReportIndex].entries, { ...newEntry, n: String(updatedReports[existingReportIndex].entries.length + 1) }]
        };
        return updatedReports;
      } else {
        const newReport: Report = {
          id: Math.random().toString(36).substr(2, 9),
          generatorName: genName,
          month,
          isFinalized: false,
          entries: [{ ...newEntry, n: '1' }]
        };
        return [...prev, newReport];
      }
    });
  };

  const calculateStatus = (fuelLevel: number): Status => {
    if (fuelLevel >= 71) return Status.Optimal;
    if (fuelLevel === 70) return Status.Warning;
    return Status.NeedsRecharge;
  };

  const processedGenerators: Generator[] = useMemo(() => {
    return generators.map(g => ({
      ...g,
      status: calculateStatus(g.fuelLevel),
      timeSinceLastRecharge: calculateDaysSince(g.lastRechargeDate, controlDate),
    }));
  }, [generators, controlDate]);

  const sortedGenerators = useMemo(() => {
    const sortableItems = [...processedGenerators];
    if (sortConfig.key) {
      sortableItems.sort((a, b) => {
        const aValue = a[sortConfig.key];
        const bValue = b[sortConfig.key];
        if (typeof aValue === 'string' && typeof bValue === 'string') {
          return sortConfig.direction === 'ascending' ? aValue.localeCompare(bValue) : bValue.localeCompare(aValue);
        }
        return sortConfig.direction === 'ascending' ? (aValue as number) - (bValue as number) : (bValue as number) - (aValue as number);
      });
    }
    return sortableItems;
  }, [processedGenerators, sortConfig]);

  const handleGeneratorUpdate = (id: number, key: keyof StoredGenerator, value: string, source: ChangeLog['source'] = 'Manual') => {
    setGenerators(prev => 
      prev.map(gen => {
        if (gen.id === id) {
          let updatedValue: string | number = value;
          let newFuelLevel = gen.fuelLevel;

          if (key === 'fuelLevel') {
            const numericValue = parseFloat(value.replace(',', '.'));
            updatedValue = isNaN(numericValue) ? gen[key] : numericValue;
            newFuelLevel = Number(updatedValue);
          } else if (key === 'lastRechargeLiters') {
            const liters = parseFloat(value.replace(',', '.'));
            updatedValue = isNaN(liters) ? gen[key] : liters;

            // Cálculos automáticos basados en la carga
            const currentLiters = (gen.fuelLevel / 100) * gen.tankCapacity;
            const totalLitersAfterRecharge = currentLiters + Number(updatedValue);
            newFuelLevel = Math.min(100, Math.round((totalLitersAfterRecharge / gen.tankCapacity) * 100));

            // Actualizar fecha de carga si hubo una recarga positiva
            if (Number(updatedValue) > 0) {
              handleGeneratorUpdate(id, 'lastRechargeDate', new Date().toLocaleDateString('es-ES'), source);
            }
          } else if (key === 'tankCapacity') {
             const cap = parseFloat(value.replace(',', '.'));
             updatedValue = isNaN(cap) ? gen[key] : cap;
          }

          if (gen[key] !== updatedValue || gen.fuelLevel !== newFuelLevel) {
            addLog(gen.name, key, gen[key], updatedValue, source);

            const updatedGen = { ...gen, [key]: updatedValue, fuelLevel: newFuelLevel };

            if (key === 'fuelLevel' || key === 'executionHours' || key === 'lastRechargeLiters') {
              createReportEntryFromDashboard(gen.name, newFuelLevel, updatedGen.executionHours);
            }

            return updatedGen;
          }
        }
        return gen;
      })
    );
    setEditingCell(null);
  };

  const handleAIUpdate = (id: number, fuel: number, hours: string) => {
    handleGeneratorUpdate(id, 'fuelLevel', String(fuel), 'AI');
    handleGeneratorUpdate(id, 'executionHours', hours, 'AI');
  };

  const handleFinalizeMonth = (month: string) => {
    if (window.confirm(`¿Estás seguro de finalizar el período ${month}? Esto archivará todos los reportes de este mes.`)) {
      setReports(prev => prev.map(r => r.month === month ? { ...r, isFinalized: true } : r));
    }
  };

  const handleDownloadJPG = async () => {
    const element = document.getElementById('capture-container');
    if (!element) return;

    // Ocultar botones y controles para la foto
    const uiElements = document.querySelectorAll('.print\\:hidden, button, input[type="date"], select');
    const originalVisibilities: string[] = [];
    uiElements.forEach((el: any) => {
      originalVisibilities.push(el.style.display);
      el.style.display = 'none';
    });

    try {
      const canvas = await html2canvas(element, {
        useCORS: true,
        scale: 2, // Mejor resolución
        backgroundColor: '#ffffff',
        logging: false,
        scrollX: 0,
        scrollY: -window.scrollY,
        onclone: (documentClone: any) => {
          const headers = documentClone.querySelectorAll('header');
          headers.forEach((h: any) => {
              h.style.background = '#0f172a'; // Slate-900 para que se vea profesional en la foto
              h.style.color = '#ffffff';
          });
          const container = documentClone.getElementById('capture-container');
          if (container) container.style.padding = '20px';
        }
      });

      const dataUrl = canvas.toDataURL('image/jpeg', 0.95);
      const link = document.createElement('a');
      link.download = `CAPTURADO_GENERADORES_${new Date().toISOString().slice(0,19).replace(/:/g, '-')}.jpg`;
      link.href = dataUrl;
      link.click();
    } catch (err) {
      console.error("Error al exportar JPG:", err);
      alert("Hubo un error al generar la imagen.");
    } finally {
      // Restaurar visibilidad
      uiElements.forEach((el: any, i) => {
        el.style.display = originalVisibilities[i];
      });
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 p-4 sm:p-6 lg:p-8 font-sans">
      <div id="capture-container" className="max-w-7xl mx-auto space-y-6 print:space-y-6 print:max-w-full print:p-4 print:bg-white">
        <Header 
          onAddGenerator={() => {
            const newId = generators.length > 0 ? Math.max(...generators.map(g => g.id)) + 1 : 1;
            setGenerators(prev => [...prev, {
              id: newId,
              name: `Generador ${newId}`,
              executionHours: '0 Hr',
              fuelLevel: 100,
              tankCapacity: 500,
              lastRechargeLiters: 0,
              lastRechargeDate: new Date().toLocaleDateString('es-ES')
            }]);
          }}
          onFileUpload={() => {}}
          onGoogleSheetImportClick={() => setIsSheetModalOpen(true)}
          onAIScanClick={() => setIsAIModalOpen(true)}
          controlDate={controlDate}
          onControlDateChange={(ds) => setControlDate(new Date(`${ds}T00:00:00`))}
          onSaveSessionCapture={() => alert('Sesión guardada')}
          onDownloadJPG={handleDownloadJPG}
          isHistoryView={false}
          onReturnToLive={() => setControlDate(new Date())}
          view={view}
          onToggleView={(v) => setView(v)}
        />

        {view === 'dashboard' && (
          <div className="bg-white rounded-xl shadow-xl border border-slate-200 overflow-hidden print:shadow-none print:border-none">
            <div className="overflow-x-auto">
              <GeneratorTable 
                generators={sortedGenerators} 
                onSort={(key) => setSortConfig(prev => ({ key, direction: prev.key === key && prev.direction === 'ascending' ? 'descending' : 'ascending' }))} 
                sortConfig={sortConfig}
                selectedRowId={selectedRowId}
                onRowClick={setSelectedRowId}
                editingCell={editingCell}
                onCellDoubleClick={(id, key) => setEditingCell({ id, key })}
                onUpdate={handleGeneratorUpdate}
                onCancelEdit={() => setEditingCell(null)}
                onDelete={(id) => setGenerators(prev => prev.filter(g => g.id !== id))}
                isReadOnly={false}
              />
            </div>
            <Legend />
          </div>
        )}

        {view === 'reports' && (
          <ReportsView 
            reports={reports}
            generators={generators}
            currentMonth={currentMonth}
            onMonthChange={setCurrentMonth}
            onFinalizeMonth={handleFinalizeMonth}
            onAddEntry={(reportId) => {
              setReports(prev => prev.map(r => r.id === reportId ? { ...r, entries: [...r.entries, { id: Date.now(), n: String(r.entries.length + 1), geLocalidad: r.generatorName, fechaAltCarga: '', entradaEnFuncionamiento: '', hIn: '', hFin: '', tdfHs: '', autonomia: '', timestamp: new Date().toISOString() }] } : r));
            }}
            onUpdateEntry={(reportId, entryId, key, val) => {
              setReports(prev => prev.map(r => r.id === reportId ? { ...r, entries: r.entries.map(e => e.id === entryId ? { ...e, [key]: val } : e) } : r));
            }}
            onDeleteEntry={(reportId, entryId) => {
              setReports(prev => prev.map(r => r.id === reportId ? { ...r, entries: r.entries.filter(e => e.id !== entryId) } : r));
            }}
            onAddReport={(name) => {
              setReports(prev => [...prev, { id: Math.random().toString(36).substr(2, 9), generatorName: name, month: currentMonth, isFinalized: false, entries: [] }]);
            }}
          />
        )}

        {view === 'logs' && <LogsView logs={logs} />}
      </div>

      <GoogleSheetImportModal isOpen={isSheetModalOpen} onClose={() => setIsSheetModalOpen(false)} onImport={async () => {}} />
      <AIScanModal 
        isOpen={isAIModalOpen} 
        onClose={() => setIsAIModalOpen(false)} 
        generators={generators}
        onConfirmUpdate={handleAIUpdate}
      />
    </div>
  );
};

export default App;

import React from 'react';
import { Generator, Status, SortConfig } from '../types';

interface GeneratorTableProps {
  generators: Generator[];
  onSort: (key: keyof Generator) => void;
  sortConfig: SortConfig;
  selectedRowId: number | null;
  onRowClick: (id: number) => void;
  editingCell: { id: number; key: keyof Generator } | null;
  onCellDoubleClick: (id: number, key: keyof Generator) => void;
  onUpdate: (id: number, key: keyof Generator, value: string) => void;
  onCancelEdit: () => void;
  onDelete: (id: number) => void;
  isReadOnly: boolean;
}

const getStatusClass = (status: Status): string => {
  switch (status) {
    case Status.Optimal:
      return 'bg-emerald-100 text-emerald-700 border-emerald-200';
    case Status.NeedsRecharge:
      return 'bg-rose-100 text-rose-700 border-rose-200';
    case Status.Warning:
      return 'bg-amber-100 text-amber-700 border-amber-200';
    default:
      return '';
  }
};

const GeneratorTable: React.FC<GeneratorTableProps> = ({ generators, onSort, sortConfig, onRowClick, selectedRowId, editingCell, onCellDoubleClick, onUpdate, onCancelEdit, onDelete }) => {
  const headers: { label: string; key: keyof Generator }[] = [
    { label: 'Generador', key: 'name' },
    { label: 'Horas', key: 'executionHours' },
    { label: 'Capacidad (L)', key: 'tankCapacity' },
    { label: 'Últ. Carga (L)', key: 'lastRechargeLiters' },
    { label: 'Combustible', key: 'fuelLevel' },
    { label: 'Estado', key: 'status' },
    { label: 'Últ. Fecha', key: 'lastRechargeDate' }
  ];

  return (
    <table className="w-full border-collapse">
      <thead>
        <tr className="bg-slate-50 border-b border-slate-200">
          {headers.map((h) => (
            <th 
              key={h.key} 
              onClick={() => onSort(h.key)}
              className="px-6 py-4 text-left text-[11px] font-black uppercase tracking-widest text-slate-500 cursor-pointer hover:text-red-600 transition-colors"
            >
              <div className="flex items-center gap-1">
                {h.label}
                {sortConfig.key === h.key && (sortConfig.direction === 'ascending' ? '↑' : '↓')}
              </div>
            </th>
          ))}
          <th className="px-6 py-4 text-right text-[11px] font-black uppercase tracking-widest text-slate-500">Acciones</th>
        </tr>
      </thead>
      <tbody className="divide-y divide-slate-100">
        {generators.map((g) => {
          const litersMissing = g.tankCapacity - ((g.fuelLevel / 100) * g.tankCapacity);
          const isFullyCharged = g.fuelLevel >= 100;

          return (
            <tr 
              key={g.id} 
              onClick={() => onRowClick(g.id)}
              className={`group transition-all ${selectedRowId === g.id ? 'bg-slate-100/50' : 'hover:bg-slate-50'}`}
            >
              <td className="px-6 py-4 font-bold text-slate-800" onDoubleClick={() => onCellDoubleClick(g.id, 'name')}>
                {editingCell?.id === g.id && editingCell.key === 'name' ? (
                  <input autoFocus onBlur={(e) => onUpdate(g.id, 'name', e.target.value)} defaultValue={g.name} className="border p-1 rounded" />
                ) : g.name}
              </td>
              <td className="px-6 py-4 text-slate-600 font-mono" onDoubleClick={() => onCellDoubleClick(g.id, 'executionHours')}>
                {editingCell?.id === g.id && editingCell.key === 'executionHours' ? (
                  <input autoFocus onBlur={(e) => onUpdate(g.id, 'executionHours', e.target.value)} defaultValue={g.executionHours} className="border p-1 rounded w-20" />
                ) : g.executionHours}
              </td>
              <td className="px-6 py-4 text-slate-600 font-mono" onDoubleClick={() => onCellDoubleClick(g.id, 'tankCapacity')}>
                {editingCell?.id === g.id && editingCell.key === 'tankCapacity' ? (
                  <input autoFocus type="number" onBlur={(e) => onUpdate(g.id, 'tankCapacity', e.target.value)} defaultValue={g.tankCapacity} className="border p-1 rounded w-16" />
                ) : `${g.tankCapacity} L`}
              </td>
              <td className="px-6 py-4" onDoubleClick={() => onCellDoubleClick(g.id, 'lastRechargeLiters')}>
                <div className="flex flex-col">
                  {editingCell?.id === g.id && editingCell.key === 'lastRechargeLiters' ? (
                    <input autoFocus type="number" onBlur={(e) => onUpdate(g.id, 'lastRechargeLiters', e.target.value)} defaultValue={g.lastRechargeLiters} className="border p-1 rounded w-16" />
                  ) : (
                    <div className="flex items-center gap-2">
                      <span className="font-black text-indigo-600">{g.lastRechargeLiters} L</span>
                      {g.lastRechargeLiters > 0 && !isFullyCharged && (
                        <span className="text-[9px] bg-red-50 text-red-500 px-1.5 py-0.5 rounded border border-red-100 font-bold" title={`Faltan ${litersMissing.toFixed(1)}L para el 100%`}>
                          -{litersMissing.toFixed(0)}L
                        </span>
                      )}
                      {isFullyCharged && g.lastRechargeLiters > 0 && (
                        <span className="text-[9px] bg-emerald-50 text-emerald-500 px-1.5 py-0.5 rounded border border-emerald-100 font-bold">
                          FULL
                        </span>
                      )}
                    </div>
                  )}
                </div>
              </td>
              <td className="px-6 py-4" onDoubleClick={() => onCellDoubleClick(g.id, 'fuelLevel')}>
                <div className="flex items-center gap-3">
                  <div className="w-16 h-2 bg-slate-200 rounded-full overflow-hidden">
                     <div className={`h-full ${g.fuelLevel < 30 ? 'bg-rose-500' : g.fuelLevel < 71 ? 'bg-amber-500' : 'bg-emerald-500'}`} style={{ width: `${g.fuelLevel}%` }} />
                  </div>
                  {editingCell?.id === g.id && editingCell.key === 'fuelLevel' ? (
                    <input autoFocus type="number" onBlur={(e) => onUpdate(g.id, 'fuelLevel', e.target.value)} defaultValue={g.fuelLevel} className="border p-1 rounded w-16" />
                  ) : <span className="text-xs font-black text-slate-800">{g.fuelLevel}%</span>}
                </div>
              </td>
              <td className="px-6 py-4">
                <span className={`px-3 py-1 rounded-lg text-[10px] font-black border ${getStatusClass(g.status)}`}>
                  {g.status}
                </span>
              </td>
              <td className="px-6 py-4 text-slate-500 text-sm" onDoubleClick={() => onCellDoubleClick(g.id, 'lastRechargeDate')}>
                {editingCell?.id === g.id && editingCell.key === 'lastRechargeDate' ? (
                  <input 
                    autoFocus 
                    onBlur={(e) => onUpdate(g.id, 'lastRechargeDate', e.target.value)} 
                    onKeyDown={(e) => e.key === 'Enter' && onUpdate(g.id, 'lastRechargeDate', e.currentTarget.value)}
                    defaultValue={g.lastRechargeDate} 
                    placeholder="DD/MM/YYYY"
                    className="border p-1 rounded w-28 text-xs font-bold" 
                  />
                ) : g.lastRechargeDate}
              </td>
              <td className="px-6 py-4 text-right">
                <button 
                  onClick={(e) => { e.stopPropagation(); onDelete(g.id); }}
                  className="opacity-0 group-hover:opacity-100 p-2 text-rose-400 hover:text-rose-600 transition-all"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                </button>
              </td>
            </tr>
          );
        })}
      </tbody>
    </table>
  );
};

export default GeneratorTable;

export enum Status {
  Optimal = 'EN ESTADO OPTIMO',
  NeedsRecharge = 'NECESITA RECARGA',
  Warning = 'PROXIMO A DAR AVISO',
}

export interface Generator {
  id: number;
  name: string;
  executionHours: string;
  fuelLevel: number; // Porcentaje 0-100
  tankCapacity: string; // Capacidad (ahora string)
  lastRechargeLiters: string; // Litros última carga (ahora string)
  status: Status;
  lastRechargeDate: string; // DD/MM/YYYY
  timeSinceLastRecharge: number; // en días
}

export type StoredGenerator = Omit<Generator, 'status' | 'timeSinceLastRecharge'>;

export interface SortConfig {
  key: keyof Generator;
  direction: 'ascending' | 'descending';
}

export interface ReportEntry {
  id: number;
  n: string;
  geLocalidad: string;
  fechaAltCarga: string;
  entradaEnFuncionamiento: string;
  hIn: string;
  hFin: string;
  tdfHs: string;
  autonomia: string;
  timestamp: string; // Para filtrado mensual
}

export interface Report {
  id: string;
  generatorName: string;
  month: string; // Formato YYYY-MM
  isFinalized: boolean;
  entries: ReportEntry[];
}

export interface ChangeLog {
  id: string;
  timestamp: string;
  generatorName: string;
  field: string;
  oldValue: string | number;
  newValue: string | number;
  source: 'Manual' | 'AI' | 'Excel';
}

import React, { useState, useMemo, useCallback, useEffect } from 'react';
import { Generator, StoredGenerator, Status, SortConfig, Report, ChangeLog, ReportEntry } from './types';
import { INITIAL_GENERATORS, EXCEL_GENERATORS } from './constants';
import GeneratorTable from './components/GeneratorTable';
import Header from './components/Header';
import Legend from './components/Legend';
import ReportsView from './components/ReportsView';
import GoogleSheetImportModal from './components/GoogleSheetImportModal';
import AIScanModal from './components/AIScanModal';
import LogsView from './components/LogsView';

declare var html2canvas: any;

const calculateDaysSince = (dateStr: string, fromDate: Date): number => {
  const parts = dateStr.split('/');
  if (parts.length !== 3) return 0;
  const [day, month, year] = parts;
  const formattedDate = new Date(`${year}-${month}-${day}`);
  if (isNaN(formattedDate.getTime())) return 0;

  const controlDate = new Date(fromDate);
  controlDate.setHours(0, 0, 0, 0);
  formattedDate.setHours(0,0,0,0);

  const diffTime = controlDate.getTime() - formattedDate.getTime();
  if (diffTime < 0) return 0;
  return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
};

const extractNumber = (val: string | number): number => {
  if (typeof val === 'number') return val;
  const match = val.match(/(\d+[,.]?\d*)/);
  if (!match) return 0;
  return parseFloat(match[0].replace(',', '.'));
};

const App: React.FC = () => {
  const [view, setView] = useState<'dashboard' | 'reports' | 'logs'>('dashboard');
  const [currentMonth, setCurrentMonth] = useState(() => new Date().toISOString().slice(0, 7));

  const [generators, setGenerators] = useState<StoredGenerator[]>(() => {
    try {
      const saved = localStorage.getItem('generators');
      return saved ? JSON.parse(saved) : INITIAL_GENERATORS;
    } catch {
      return INITIAL_GENERATORS;
    }
  });

  const [logs, setLogs] = useState<ChangeLog[]>(() => {
    try {
      const saved = localStorage.getItem('change_logs');
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  const [reports, setReports] = useState<Report[]>(() => {
    try {
        const saved = localStorage.getItem('reports_v2');
        return saved ? JSON.parse(saved) : [];
    } catch {
        return [];
    }
  });

  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'name', direction: 'ascending' });
  const [selectedRowId, setSelectedRowId] = useState<number | null>(null);
  const [editingCell, setEditingCell] = useState<{ id: number; key: keyof Generator } | null>(null);
  const [controlDate, setControlDate] = useState(new Date());
  const [isSheetModalOpen, setIsSheetModalOpen] = useState(false);
  const [isAIModalOpen, setIsAIModalOpen] = useState(false);

  useEffect(() => {
    const refreshInterval = setInterval(() => {
      setControlDate(new Date());
    }, 5 * 60 * 1000);
    return () => clearInterval(refreshInterval);
  }, []);

  useEffect(() => {
    localStorage.setItem('generators', JSON.stringify(generators));
    localStorage.setItem('reports_v2', JSON.stringify(reports));
    localStorage.setItem('change_logs', JSON.stringify(logs));
  }, [generators, reports, logs]);

  const addLog = (generatorName: string, field: string, oldVal: any, newVal: any, source: ChangeLog['source']) => {
    const newLog: ChangeLog = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toISOString(),
      generatorName,
      field,
      oldValue: oldVal,
      newValue: newVal,
      source
    };
    setLogs(prev => [newLog, ...prev].slice(0, 500));
  };

  const createReportEntryFromDashboard = (genName: string, fuel: number, hours: string) => {
    const month = new Date().toISOString().slice(0, 7);
    setReports(prev => {
      const existingReportIndex = prev.findIndex(r => r.generatorName === genName && r.month === month);
      const now = new Date();
      const timeStr = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;

      const newEntry: ReportEntry = {
        id: Date.now(),
        n: '',
        geLocalidad: genName,
        fechaAltCarga: now.toLocaleDateString('es-ES'),
        entradaEnFuncionamiento: 'SÍ',
        hIn: timeStr,
        hFin: timeStr,
        tdfHs: '0',
        autonomia: String(fuel),
        timestamp: now.toISOString()
      };

      if (existingReportIndex > -1) {
        if (prev[existingReportIndex].isFinalized) return prev;
        const updatedReports = [...prev];
        updatedReports[existingReportIndex] = {
          ...updatedReports[existingReportIndex],
          entries: [...updatedReports[existingReportIndex].entries, { ...newEntry, n: String(updatedReports[existingReportIndex].entries.length + 1) }]
        };
        return updatedReports;
      } else {
        const newReport: Report = {
          id: Math.random().toString(36).substr(2, 9),
          generatorName: genName,
          month,
          isFinalized: false,
          entries: [{ ...newEntry, n: '1' }]
        };
        return [...prev, newReport];
      }
    });
  };

  const calculateStatus = (fuelLevel: number): Status => {
    if (fuelLevel >= 71) return Status.Optimal;
    if (fuelLevel >= 70) return Status.Warning;
    return Status.NeedsRecharge;
  };

  const processedGenerators: Generator[] = useMemo(() => {
    return generators.map(g => ({
      ...g,
      status: calculateStatus(g.fuelLevel),
      timeSinceLastRecharge: calculateDaysSince(g.lastRechargeDate, controlDate),
    }));
  }, [generators, controlDate]);

  const sortedGenerators = useMemo(() => {
    const sortableItems = [...processedGenerators];
    if (sortConfig.key) {
      sortableItems.sort((a, b) => {
        const aValue = a[sortConfig.key];
        const bValue = b[sortConfig.key];
        if (typeof aValue === 'string' && typeof bValue === 'string') {
          return sortConfig.direction === 'ascending' ? aValue.localeCompare(bValue) : bValue.localeCompare(aValue);
        }
        return sortConfig.direction === 'ascending' ? (aValue as number) - (bValue as number) : (bValue as number) - (aValue as number);
      });
    }
    return sortableItems;
  }, [processedGenerators, sortConfig]);

  const handleGeneratorUpdate = (id: number, key: keyof StoredGenerator, value: string, source: ChangeLog['source'] = 'Manual') => {
    setGenerators(prev => 
      prev.map(gen => {
        if (gen.id === id) {
          let updatedValue: string | number = value;
          let newFuelLevel = gen.fuelLevel;

          if (key === 'fuelLevel') {
            const numericValue = parseFloat(value.replace(',', '.'));
            updatedValue = isNaN(numericValue) ? gen[key] : numericValue;
            newFuelLevel = Number(updatedValue);
          } else if (key === 'lastRechargeLiters') {
            updatedValue = value;
            const liters = extractNumber(value);
            const tankCap = extractNumber(gen.tankCapacity);

            if (tankCap > 0) {
              const currentLiters = (gen.fuelLevel / 100) * tankCap;
              const totalLitersAfterRecharge = currentLiters + liters;
              newFuelLevel = Math.min(100, Math.round((totalLitersAfterRecharge / tankCap) * 100));
            }

            if (liters > 0) {
              handleGeneratorUpdate(id, 'lastRechargeDate', new Date().toLocaleDateString('es-ES'), source);
            }
          } else if (key === 'tankCapacity') {
             updatedValue = value;
          }

          if (gen[key] !== updatedValue || gen.fuelLevel !== newFuelLevel) {
            addLog(gen.name, key, gen[key], updatedValue, source);
            const updatedGen = { ...gen, [key]: updatedValue, fuelLevel: newFuelLevel };

            if (key === 'fuelLevel' || key === 'executionHours' || key === 'lastRechargeLiters') {
              createReportEntryFromDashboard(gen.name, newFuelLevel, updatedGen.executionHours);
            }
            return updatedGen;
          }
        }
        return gen;
      })
    );
    setEditingCell(null);
  };

  const handleAIUpdate = (id: number, fuel: number, hours: string) => {
    handleGeneratorUpdate(id, 'fuelLevel', String(fuel), 'AI');
    handleGeneratorUpdate(id, 'executionHours', hours, 'AI');
  };

  const handleDownloadJPG = async () => {
    const element = document.getElementById('capture-container');
    if (!element) return;

    const uiElements = document.querySelectorAll('.print\\:hidden, button, input[type="date"], select');
    const originalVisibilities: string[] = [];
    uiElements.forEach((el: any) => {
      originalVisibilities.push(el.style.display);
      el.style.display = 'none';
    });

    try {
      const canvas = await html2canvas(element, {
        useCORS: true,
        scale: 2,
        backgroundColor: '#ffffff',
        logging: false,
        scrollX: 0,
        scrollY: -window.scrollY,
        onclone: (documentClone: any) => {
          const headers = documentClone.querySelectorAll('header');
          headers.forEach((h: any) => {
              h.style.background = '#0f172a';
              h.style.color = '#ffffff';
          });
          const container = documentClone.getElementById('capture-container');
          if (container) container.style.padding = '20px';
        }
      });

      const dataUrl = canvas.toDataURL('image/jpeg', 0.95);
      const link = document.createElement('a');
      link.download = `CAPTURADO_GENERADORES_${new Date().toISOString().slice(0,19).replace(/:/g, '-')}.jpg`;
      link.href = dataUrl;
      link.click();
    } catch (err) {
      console.error("Error al exportar JPG:", err);
      alert("Hubo un error al generar la imagen.");
    } finally {
      uiElements.forEach((el: any, i) => {
        el.style.display = originalVisibilities[i];
      });
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 p-4 sm:p-6 lg:p-8 font-sans">
      <div id="capture-container" className="max-w-7xl mx-auto space-y-6 print:space-y-6 print:max-w-full print:p-4 print:bg-white">
        <Header 
          onAddGenerator={() => {
            const newId = generators.length > 0 ? Math.max(...generators.map(g => g.id)) + 1 : 1;
            setGenerators(prev => [...prev, {
              id: newId,
              name: `Generador ${newId}`,
              executionHours: '0 Hr',
              fuelLevel: 100,
              tankCapacity: '500 L',
              lastRechargeLiters: '0',
              lastRechargeDate: new Date().toLocaleDateString('es-ES')
            }]);
          }}
          onFileUpload={() => {}}
          onGoogleSheetImportClick={() => setIsSheetModalOpen(true)}
          onAIScanClick={() => setIsAIModalOpen(true)}
          controlDate={controlDate}
          onControlDateChange={(ds) => setControlDate(new Date(`${ds}T00:00:00`))}
          onSaveSessionCapture={() => alert('Sesión guardada')}
          onDownloadJPG={handleDownloadJPG}
          isHistoryView={false}
          onReturnToLive={() => setControlDate(new Date())}
          view={view}
          onToggleView={(v) => setView(v)}
        />

        {view === 'dashboard' && (
          <div className="bg-white rounded-xl shadow-xl border border-slate-200 overflow-hidden print:shadow-none print:border-none">
            <div className="overflow-x-auto">
              <GeneratorTable 
                generators={sortedGenerators} 
                onSort={(key) => setSortConfig(prev => ({ key, direction: prev.key === key && prev.direction === 'ascending' ? 'descending' : 'ascending' }))} 
                sortConfig={sortConfig}
                selectedRowId={selectedRowId}
                onRowClick={setSelectedRowId}
                editingCell={editingCell}
                onCellDoubleClick={(id, key) => setEditingCell({ id, key })}
                onUpdate={handleGeneratorUpdate}
                onCancelEdit={() => setEditingCell(null)}
                onDelete={(id) => setGenerators(prev => prev.filter(g => g.id !== id))}
                isReadOnly={false}
              />
            </div>
            <Legend />
          </div>
        )}

        {view === 'reports' && (
          <ReportsView 
            reports={reports}
            generators={generators}
            currentMonth={currentMonth}
            onMonthChange={setCurrentMonth}
            onFinalizeMonth={handleFinalizeMonth}
            onAddEntry={(reportId) => {
              setReports(prev => prev.map(r => r.id === reportId ? { ...r, entries: [...r.entries, { id: Date.now(), n: String(r.entries.length + 1), geLocalidad: r.generatorName, fechaAltCarga: '', entradaEnFuncionamiento: '', hIn: '', hFin: '', tdfHs: '', autonomia: '', timestamp: new Date().toISOString() }] } : r));
            }}
            onUpdateEntry={(reportId, entryId, key, val) => {
              setReports(prev => prev.map(r => r.id === reportId ? { ...r, entries: r.entries.map(e => e.id === entryId ? { ...e, [key]: val } : e) } : r));
            }}
            onDeleteEntry={(reportId, entryId) => {
              setReports(prev => prev.map(r => r.id === reportId ? { ...r, entries: r.entries.filter(e => e.id !== entryId) } : r));
            }}
            onAddReport={(name) => {
              setReports(prev => [...prev, { id: Math.random().toString(36).substr(2, 9), generatorName: name, month: currentMonth, isFinalized: false, entries: [] }]);
            }}
          />
        )}

        {view === 'logs' && <LogsView logs={logs} />}
      </div>

      <GoogleSheetImportModal isOpen={isSheetModalOpen} onClose={() => setIsSheetModalOpen(false)} onImport={async () => {}} />
      <AIScanModal 
        isOpen={isAIModalOpen} 
        onClose={() => setIsAIModalOpen(false)} 
        generators={generators}
        onConfirmUpdate={handleAIUpdate}
      />
    </div>
  );
};

export default App;

import React from 'react';
import { Generator, Status, SortConfig } from '../types';

interface GeneratorTableProps {
  generators: Generator[];
  onSort: (key: keyof Generator) => void;
  sortConfig: SortConfig;
  selectedRowId: number | null;
  onRowClick: (id: number) => void;
  editingCell: { id: number; key: keyof Generator } | null;
  onCellDoubleClick: (id: number, key: keyof Generator) => void;
  onUpdate: (id: number, key: keyof Generator, value: string) => void;
  onCancelEdit: () => void;
  onDelete: (id: number) => void;
  isReadOnly: boolean;
}

const getStatusClass = (status: Status): string => {
  switch (status) {
    case Status.Optimal:
      return 'bg-emerald-600 text-white border-emerald-700 shadow-sm';
    case Status.NeedsRecharge:
      return 'bg-rose-600 text-white border-rose-700 shadow-sm';
    case Status.Warning:
      return 'bg-amber-500 text-white border-amber-600 shadow-sm';
    default:
      return 'bg-slate-400 text-white';
  }
};

const extractNumber = (val: string | number): number => {
  if (typeof val === 'number') return val;
  const match = val.match(/(\d+[,.]?\d*)/);
  if (!match) return 0;
  return parseFloat(match[0].replace(',', '.'));
};

const GeneratorTable: React.FC<GeneratorTableProps> = ({ generators, onSort, sortConfig, onRowClick, selectedRowId, editingCell, onCellDoubleClick, onUpdate, onCancelEdit, onDelete }) => {
  const headers: { label: string; key: keyof Generator }[] = [
    { label: 'Generador', key: 'name' },
    { label: 'Horas', key: 'executionHours' },
    { label: 'Capacidad', key: 'tankCapacity' },
    { label: 'Últ. Carga', key: 'lastRechargeLiters' },
    { label: 'Combustible', key: 'fuelLevel' },
    { label: 'Estado', key: 'status' },
    { label: 'Últ. Fecha', key: 'lastRechargeDate' }
  ];

  return (
    <table className="w-full border-collapse">
      <thead>
        <tr className="bg-slate-100 border-b border-slate-300">
          {headers.map((h) => (
            <th 
              key={h.key} 
              onClick={() => onSort(h.key)}
              className="px-6 py-4 text-left text-[11px] font-black uppercase tracking-widest text-slate-600 cursor-pointer hover:text-red-600 transition-colors"
            >
              <div className="flex items-center gap-1">
                {h.label}
                {sortConfig.key === h.key && (sortConfig.direction === 'ascending' ? '↑' : '↓')}
              </div>
            </th>
          ))}
          <th className="px-6 py-4 text-right text-[11px] font-black uppercase tracking-widest text-slate-600">Acciones</th>
        </tr>
      </thead>
      <tbody className="divide-y divide-slate-200">
        {generators.map((g) => {
          const tankCapNum = extractNumber(g.tankCapacity);
          const litersMissing = tankCapNum - ((g.fuelLevel / 100) * tankCapNum);
          const isFullyCharged = g.fuelLevel >= 100;

          return (
            <tr 
              key={g.id} 
              onClick={() => onRowClick(g.id)}
              className={`group transition-all ${selectedRowId === g.id ? 'bg-slate-100' : 'hover:bg-slate-50'}`}
            >
              <td className="px-6 py-4 font-bold text-slate-900" onDoubleClick={() => onCellDoubleClick(g.id, 'name')}>
                {editingCell?.id === g.id && editingCell.key === 'name' ? (
                  <input autoFocus onBlur={(e) => onUpdate(g.id, 'name', e.target.value)} defaultValue={g.name} className="border border-indigo-300 p-1.5 rounded w-full outline-none focus:ring-2 focus:ring-indigo-200" />
                ) : g.name}
              </td>
              <td className="px-6 py-4 text-slate-700 font-mono font-medium" onDoubleClick={() => onCellDoubleClick(g.id, 'executionHours')}>
                {editingCell?.id === g.id && editingCell.key === 'executionHours' ? (
                  <input autoFocus onBlur={(e) => onUpdate(g.id, 'executionHours', e.target.value)} defaultValue={g.executionHours} className="border border-indigo-300 p-1.5 rounded w-24 outline-none focus:ring-2 focus:ring-indigo-200" />
                ) : g.executionHours}
              </td>
              <td className="px-6 py-4 text-slate-700 font-bold" onDoubleClick={() => onCellDoubleClick(g.id, 'tankCapacity')}>
                {editingCell?.id === g.id && editingCell.key === 'tankCapacity' ? (
                  <input autoFocus type="text" onBlur={(e) => onUpdate(g.id, 'tankCapacity', e.target.value)} defaultValue={g.tankCapacity} className="border border-indigo-300 p-1.5 rounded w-20 outline-none focus:ring-2 focus:ring-indigo-200" />
                ) : g.tankCapacity}
              </td>
              <td className="px-6 py-4" onDoubleClick={() => onCellDoubleClick(g.id, 'lastRechargeLiters')}>
                <div className="flex flex-col">
                  {editingCell?.id === g.id && editingCell.key === 'lastRechargeLiters' ? (
                    <input autoFocus type="text" onBlur={(e) => onUpdate(g.id, 'lastRechargeLiters', e.target.value)} defaultValue={g.lastRechargeLiters} className="border border-indigo-300 p-1.5 rounded w-20 outline-none focus:ring-2 focus:ring-indigo-200" />
                  ) : (
                    <div className="flex items-center gap-2">
                      <span className="font-black text-indigo-700">{g.lastRechargeLiters}</span>
                      {tankCapNum > 0 && extractNumber(g.lastRechargeLiters) > 0 && !isFullyCharged && (
                        <span className="text-[9px] bg-red-100 text-red-700 px-1.5 py-0.5 rounded border border-red-200 font-black" title={`Faltan aprox. ${litersMissing.toFixed(1)}L para el 100%`}>
                          -{litersMissing.toFixed(0)}L
                        </span>
                      )}
                      {isFullyCharged && extractNumber(g.lastRechargeLiters) > 0 && (
                        <span className="text-[9px] bg-emerald-100 text-emerald-700 px-1.5 py-0.5 rounded border border-emerald-200 font-black uppercase">
                          Lleno
                        </span>
                      )}
                    </div>
                  )}
                </div>
              </td>
              <td className="px-6 py-4" onDoubleClick={() => onCellDoubleClick(g.id, 'fuelLevel')}>
                <div className="flex items-center gap-3">
                  <div className="w-16 h-2 bg-slate-200 rounded-full overflow-hidden">
                     <div className={`h-full ${g.fuelLevel < 30 ? 'bg-rose-500' : g.fuelLevel < 71 ? 'bg-amber-500' : 'bg-emerald-500'}`} style={{ width: `${g.fuelLevel}%` }} />
                  </div>
                  {editingCell?.id === g.id && editingCell.key === 'fuelLevel' ? (
                    <input autoFocus type="number" onBlur={(e) => onUpdate(g.id, 'fuelLevel', e.target.value)} defaultValue={g.fuelLevel} className="border border-indigo-300 p-1.5 rounded w-16 outline-none focus:ring-2 focus:ring-indigo-200" />
                  ) : <span className="text-xs font-black text-slate-900">{g.fuelLevel}%</span>}
                </div>
              </td>
              <td className="px-6 py-4">
                <span className={`px-3 py-1.5 rounded-lg text-[9px] font-black border uppercase tracking-widest ${getStatusClass(g.status)}`}>
                  {g.status}
                </span>
              </td>
              <td className="px-6 py-4 text-slate-700 text-sm font-semibold" onDoubleClick={() => onCellDoubleClick(g.id, 'lastRechargeDate')}>
                {editingCell?.id === g.id && editingCell.key === 'lastRechargeDate' ? (
                  <input 
                    autoFocus 
                    onBlur={(e) => onUpdate(g.id, 'lastRechargeDate', e.target.value)} 
                    onKeyDown={(e) => e.key === 'Enter' && onUpdate(g.id, 'lastRechargeDate', e.currentTarget.value)}
                    defaultValue={g.lastRechargeDate} 
                    placeholder="DD/MM/YYYY"
                    className="border border-indigo-300 p-1.5 rounded w-28 text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-200" 
                  />
                ) : g.lastRechargeDate}
              </td>
              <td className="px-6 py-4 text-right">
                <button 
                  onClick={(e) => { e.stopPropagation(); onDelete(g.id); }}
                  className="opacity-0 group-hover:opacity-100 p-2 text-rose-500 hover:bg-rose-50 rounded-lg transition-all"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                </button>
              </td>
            </tr>
          );
        })}
      </tbody>
    </table>
  );
};

