const calculateDaysSince = (dateStr: string, fromDate: Date): number => {
  const parts = dateStr.split('/');
  if (parts.length !== 3) return 0;
  const [day, month, year] = parts;
  const formattedDate = new Date(`${year}-${month}-${day}`);
  if (isNaN(formattedDate.getTime())) return 0;

  const controlDate = new Date(fromDate);
  controlDate.setHours(0, 0, 0, 0);
  formattedDate.setHours(0,0,0,0);

  const diffTime = controlDate.getTime() - formattedDate.getTime();
  if (diffTime < 0) return 0;
  return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
};

const extractNumber = (val: string | number): number => {
  if (typeof val === 'number') return val;
  const match = val.match(/(\d+[,.]?\d*)/);
  if (!match) return 0;
  return parseFloat(match[0].replace(',', '.'));
};

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(() => localStorage.getItem('is_auth') === 'true');
  const [view, setView] = useState<'dashboard' | 'reports' | 'logs' | 'fuel'>('dashboard');
  const [currentMonth, setCurrentMonth] = useState(() => new Date().toISOString().slice(0, 7));

  const [generators, setGenerators] = useState<StoredGenerator[]>(() => {
    try {
      const saved = localStorage.getItem('generators');
      return saved ? JSON.parse(saved) : INITIAL_GENERATORS;
    } catch {
      return INITIAL_GENERATORS;
    }
  });

  const [fuelLoads, setFuelLoads] = useState<FuelLoad[]>(() => {
    try {
      const saved = localStorage.getItem('fuel_loads');
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  const [logs, setLogs] = useState<ChangeLog[]>(() => {
    try {
      const saved = localStorage.getItem('change_logs');
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  const [reports, setReports] = useState<Report[]>(() => {
    try {
        const saved = localStorage.getItem('reports_v2');
        return saved ? JSON.parse(saved) : [];
    } catch {
        return [];
    }
  });

  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'name', direction: 'ascending' });
  const [selectedRowId, setSelectedRowId] = useState<number | null>(null);
  const [editingCell, setEditingCell] = useState<{ id: number; key: keyof Generator } | null>(null);
  const [controlDate, setControlDate] = useState(new Date());
  const [isSheetModalOpen, setIsSheetModalOpen] = useState(false);
  const [isAIModalOpen, setIsAIModalOpen] = useState(false);

  useEffect(() => {
    const refreshInterval = setInterval(() => {
      setControlDate(new Date());
    }, 5 * 60 * 1000);
    return () => clearInterval(refreshInterval);
  }, []);

  useEffect(() => {
    localStorage.setItem('generators', JSON.stringify(generators));
    localStorage.setItem('reports_v2', JSON.stringify(reports));
    localStorage.setItem('change_logs', JSON.stringify(logs));
    localStorage.setItem('fuel_loads', JSON.stringify(fuelLoads));
    localStorage.setItem('is_auth', String(isAuthenticated));
  }, [generators, reports, logs, fuelLoads, isAuthenticated]);

  const addLog = (generatorName: string, field: string, oldVal: any, newVal: any, source: ChangeLog['source']) => {
    const newLog: ChangeLog = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toISOString(),
      generatorName,
      field,
      oldValue: oldVal,
      newValue: newVal,
      source
    };
    setLogs(prev => [newLog, ...prev].slice(0, 500));
  };

  const calculateStatus = (fuelLevel: number): Status => {
    if (fuelLevel >= 71) return Status.Optimal;
    if (fuelLevel >= 70) return Status.Warning;
    return Status.NeedsRecharge;
  };

  const processedGenerators: Generator[] = useMemo(() => {
    return generators.map(g => ({
      ...g,
      status: calculateStatus(g.fuelLevel),
      timeSinceLastRecharge: calculateDaysSince(g.lastRechargeDate, controlDate),
    }));
  }, [generators, controlDate]);

  const sortedGenerators = useMemo(() => {
    const sortableItems = [...processedGenerators];
    if (sortConfig.key) {
      sortableItems.sort((a, b) => {
        const aValue = a[sortConfig.key];
        const bValue = b[sortConfig.key];
        if (typeof aValue === 'string' && typeof bValue === 'string') {
          return sortConfig.direction === 'ascending' ? aValue.localeCompare(bValue) : bValue.localeCompare(aValue);
        }
        return sortConfig.direction === 'ascending' ? (aValue as number) - (bValue as number) : (bValue as number) - (aValue as number);
      });
    }
    return sortableItems;
  }, [processedGenerators, sortConfig]);

  const handleGeneratorUpdate = (id: number, key: keyof StoredGenerator, value: string, source: ChangeLog['source'] = 'Manual') => {
    setGenerators(prev => 
      prev.map(gen => {
        if (gen.id === id) {
          let updatedValue: string | number = value;
          let newFuelLevel = gen.fuelLevel;

          if (key === 'fuelLevel') {
            const numericValue = parseFloat(value.replace(',', '.'));
            updatedValue = isNaN(numericValue) ? gen[key] : numericValue;
            newFuelLevel = Number(updatedValue);
          } else if (key === 'tankCapacity') {
             updatedValue = value;
          }

          if (gen[key] !== updatedValue || gen.fuelLevel !== newFuelLevel) {
            addLog(gen.name, key, gen[key], updatedValue, source);
            return { ...gen, [key]: updatedValue, fuelLevel: newFuelLevel };
          }
        }
        return gen;
      })
    );
    setEditingCell(null);
  };

  const handleAddFuelLoad = (genId: number, liters: string, date: string) => {
    const gen = generators.find(g => g.id === genId);
    if (!gen) return;

    const litVal = extractNumber(liters);
    const tankCap = extractNumber(gen.tankCapacity);
    const currentLiters = (gen.fuelLevel / 100) * tankCap;
    const newTotalLiters = currentLiters + litVal;
    const newLevel = Math.min(100, Math.round((newTotalLiters / tankCap) * 100));

    const newLoad: FuelLoad = {
      id: Math.random().toString(36).substr(2, 9),
      generatorId: genId,
      generatorName: gen.name,
      liters,
      date,
      previousLevel: gen.fuelLevel,
      newLevel
    };

    setFuelLoads(prev => [newLoad, ...prev]);
    setGenerators(prev => prev.map(g => g.id === genId ? {
      ...g,
      fuelLevel: newLevel,
      lastRechargeDate: date,
      lastRechargeLiters: liters
    } : g));

    addLog(gen.name, 'fuelLevel', gen.fuelLevel, newLevel, 'Manual');
    addLog(gen.name, 'lastRechargeDate', gen.lastRechargeDate, date, 'Manual');
  };

  const handleAIUpdate = (id: number, fuel: number, hours: string) => {
    handleGeneratorUpdate(id, 'fuelLevel', String(fuel), 'AI');
    handleGeneratorUpdate(id, 'executionHours', hours, 'AI');
  };

  const handleFinalizeMonth = (month: string) => {
    setReports(prev => prev.map(r => r.month === month ? { ...r, isFinalized: true } : r));
  };

  // Implementamos los manejadores de reportes que faltaban para guardar información cargada
  const handleAddReportEntry = (reportId: string) => {
    setReports(prev => prev.map(r => {
      if (r.id === reportId) {
        const newEntry: ReportEntry = {
          id: Date.now(),
          n: String(r.entries.length + 1),
          geLocalidad: r.generatorName,
          fechaAltCarga: new Date().toLocaleDateString('es-ES'),
          entradaEnFuncionamiento: 'SÍ',
          hIn: '00:00',
          hFin: '00:00',
          tdfHs: '0',
          autonomia: '100',
          timestamp: new Date().toISOString()
        };
        return { ...r, entries: [...r.entries, newEntry] };
      }
      return r;
    }));
  };

  const handleUpdateReportEntry = (reportId: string, entryId: number, key: keyof ReportEntry, value: string) => {
    setReports(prev => prev.map(r => {
      if (r.id === reportId) {
        return {
          ...r,
          entries: r.entries.map(e => e.id === entryId ? { ...e, [key]: value } : e)
        };
      }
      return r;
    }));
  };

  const handleDeleteReportEntry = (reportId: string, entryId: number) => {
    setReports(prev => prev.map(r => {
      if (r.id === reportId) {
        return {
          ...r,
          entries: r.entries.filter(e => e.id !== entryId)
        };
      }
      return r;
    }));
  };

  const handleAddReport = (generatorName: string) => {
    const newReport: Report = {
      id: Math.random().toString(36).substr(2, 9),
      generatorName,
      month: currentMonth,
      isFinalized: false,
      entries: []
    };
    setReports(prev => [...prev, newReport]);
  };

  if (!isAuthenticated) {
    return <LoginView onLogin={() => setIsAuthenticated(true)} />;
  }

  return (
    <div className="min-h-screen bg-slate-50 p-4 sm:p-6 lg:p-8 font-sans">
      <div id="capture-container" className="max-w-7xl mx-auto space-y-6 print:space-y-6 print:max-w-full print:p-4 print:bg-white">
        <Header 
          onAddGenerator={() => {
            const newId = generators.length > 0 ? Math.max(...generators.map(g => g.id)) + 1 : 1;
            setGenerators(prev => [...prev, {
              id: newId,
              name: `Generador ${newId}`,
              executionHours: '0 Hr',
              fuelLevel: 100,
              tankCapacity: '500 L',
              lastRechargeLiters: '0',
              lastRechargeDate: new Date().toLocaleDateString('es-ES')
            }]);
          }}
          onFileUpload={() => {}}
          onGoogleSheetImportClick={() => setIsSheetModalOpen(true)}
          onAIScanClick={() => setIsAIModalOpen(true)}
          controlDate={controlDate}
          onControlDateChange={(ds) => setControlDate(new Date(`${ds}T00:00:00`))}
          onSaveSessionCapture={() => alert('Sesión guardada')}
          onDownloadJPG={() => {}}
          isHistoryView={false}
          onReturnToLive={() => setControlDate(new Date())}
          view={view}
          onToggleView={(v) => setView(v)}
        />

        {view === 'dashboard' && (
          <div className="bg-white rounded-xl shadow-xl border border-slate-200 overflow-hidden print:shadow-none print:border-none">
            <div className="overflow-x-auto">
              <GeneratorTable 
                generators={sortedGenerators} 
                onSort={(key) => setSortConfig(prev => ({ key, direction: prev.key === key && prev.direction === 'ascending' ? 'descending' : 'ascending' }))} 
                sortConfig={sortConfig}
                selectedRowId={selectedRowId}
                onRowClick={setSelectedRowId}
                editingCell={editingCell}
                onCellDoubleClick={(id, key) => setEditingCell({ id, key })}
                onUpdate={handleGeneratorUpdate}
                onCancelEdit={() => setEditingCell(null)}
                onDelete={(id) => setGenerators(prev => prev.filter(g => g.id !== id))}
                isReadOnly={false}
              />
            </div>
            <Legend />
          </div>
        )}

        {view === 'fuel' && (
          <FuelManagementView 
            generators={generators}
            fuelLoads={fuelLoads}
            onAddLoad={handleAddFuelLoad}
            onDeleteLoad={(id) => setFuelLoads(prev => prev.filter(l => l.id !== id))}
          />
        )}

        {view === 'reports' && (
          <ReportsView 
            reports={reports}
            generators={generators}
            currentMonth={currentMonth}
            onMonthChange={setCurrentMonth}
            onFinalizeMonth={handleFinalizeMonth}
            onAddEntry={handleAddReportEntry}
            onUpdateEntry={handleUpdateReportEntry}
            onDeleteEntry={handleDeleteReportEntry}
            onAddReport={handleAddReport}
          />
        )}

        {view === 'logs' && <LogsView logs={logs} />}
      </div>

      <div className="fixed bottom-4 right-4 print:hidden">
        <button 
          onClick={() => {
            setIsAuthenticated(false);
            localStorage.setItem('is_auth', 'false');
          }}
          className="bg-slate-800 text-white px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-red-600 transition-all shadow-xl border border-slate-700"
        >
          Cerrar Sesión
        </button>
      </div>

      <GoogleSheetImportModal isOpen={isSheetModalOpen} onClose={() => setIsSheetModalOpen(false)} onImport={async () => {}} />
      <AIScanModal 
        isOpen={isAIModalOpen} 
        onClose={() => setIsAIModalOpen(false)} 
        generators={generators}
        onConfirmUpdate={handleAIUpdate}
      />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { FuelLoad, StoredGenerator } from '../types';

interface FuelManagementViewProps {
    generators: StoredGenerator[];
    fuelLoads: FuelLoad[];
    onAddLoad: (genId: number, liters: string, date: string) => void;
    onDeleteLoad: (id: string) => void;
}

const FuelManagementView: React.FC<FuelManagementViewProps> = ({ generators, fuelLoads, onAddLoad, onDeleteLoad }) => {
    const [selectedGenId, setSelectedGenId] = useState<number | ''>('');
    const [liters, setLiters] = useState('');
    const [date, setDate] = useState(new Date().toLocaleDateString('es-ES'));
    const [confirmDelete, setConfirmDelete] = useState<{ id: string; stage: 0 | 1 | 2 }>({ id: '', stage: 0 });

    const handleSave = () => {
        if (!selectedGenId || !liters) {
            alert("Por favor complete el generador y los litros.");
            return;
        }
        onAddLoad(Number(selectedGenId), liters, date);
        setLiters('');
    };

    const handleDeleteClick = (id: string) => {
        if (confirmDelete.id === id) {
            if (confirmDelete.stage === 1) {
                setConfirmDelete({ id, stage: 2 });
            } else if (confirmDelete.stage === 2) {
                onDeleteLoad(id);
                setConfirmDelete({ id: '', stage: 0 });
            }
        } else {
            setConfirmDelete({ id, stage: 1 });
        }
    };

    const selectedGen = generators.find(g => g.id === selectedGenId);

    return (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Formulario de Carga */}
            <div className="lg:col-span-1 bg-white p-6 rounded-2xl shadow-xl border border-slate-200">
                <h2 className="text-xl font-black text-slate-800 mb-6 flex items-center gap-2">
                    <span className="w-8 h-8 bg-indigo-600 rounded flex items-center justify-center text-white text-xs">C</span>
                    REGISTRAR CARGA
                </h2>

                <div className="space-y-4">
                    <div>
                        <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest block mb-1">Seleccionar Generador:</label>
                        <select 
                            value={selectedGenId}
                            onChange={(e) => setSelectedGenId(e.target.value ? Number(e.target.value) : '')}
                            className="w-full bg-white text-slate-900 border border-slate-200 p-3 rounded-xl font-bold focus:ring-2 focus:ring-indigo-500 outline-none"
                        >
                            <option value="">-- Seleccionar --</option>
                            {generators.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                        </select>
                    </div>

                    {selectedGen && (
                        <div className="p-4 bg-slate-50 rounded-xl border border-slate-100">
                            <div className="flex justify-between items-center mb-1">
                                <span className="text-[10px] font-black text-slate-400 uppercase">Estado Actual:</span>
                                <span className="text-xs font-black text-slate-700">{selectedGen.fuelLevel}%</span>
                            </div>
                            <div className="w-full h-2 bg-slate-200 rounded-full overflow-hidden">
                                <div className="h-full bg-emerald-500" style={{ width: `${selectedGen.fuelLevel}%` }} />
                            </div>
                            <p className="text-[9px] text-slate-400 mt-2">Capacidad: {selectedGen.tankCapacity}</p>
                        </div>
                    )}

                    <div>
                        <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest block mb-1">Litros Recargados:</label>
                        <input 
                            type="text" 
                            placeholder="Ej: 100"
                            value={liters}
                            onChange={(e) => setLiters(e.target.value)}
                            className="w-full bg-white text-slate-900 border border-slate-200 p-3 rounded-xl font-bold focus:ring-2 focus:ring-indigo-500 outline-none"
                        />
                    </div>

                    <div>
                        <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest block mb-1">Fecha de Carga:</label>
                        <input 
                            type="text" 
                            value={date}
                            onChange={(e) => setDate(e.target.value)}
                            className="w-full bg-white text-slate-900 border border-slate-200 p-3 rounded-xl font-bold focus:ring-2 focus:ring-indigo-500 outline-none"
                        />
                    </div>

                    <button 
                        onClick={handleSave}
                        className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl font-black text-sm uppercase tracking-widest shadow-lg shadow-indigo-600/20 transition-all"
                    >
                        Guardar Registro
                    </button>
                </div>
            </div>

            {/* Historial de Cargas */}
            <div className="lg:col-span-2 bg-white rounded-2xl shadow-xl border border-slate-200 overflow-hidden">
                <div className="p-6 bg-slate-50 border-b border-slate-100">
                    <h2 className="text-xl font-black text-slate-800 tracking-tight">HISTORIAL DE CARGAS</h2>
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                        <thead className="bg-slate-50 text-slate-500 font-bold uppercase text-[10px] tracking-widest border-b border-slate-100">
                            <tr>
                                <th className="px-6 py-4 text-left">Generador</th>
                                <th className="px-6 py-4 text-center">Litros</th>
                                <th className="px-6 py-4 text-center">Fecha</th>
                                <th className="px-6 py-4 text-center">Nivel Resultante</th>
                                <th className="px-6 py-4 text-right">Acción</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50">
                            {fuelLoads.length === 0 ? (
                                <tr>
                                    <td colSpan={5} className="px-6 py-12 text-center text-slate-400 italic">No hay registros de carga.</td>
                                </tr>
                            ) : (
                                fuelLoads.map((load) => (
                                    <tr key={load.id} className="hover:bg-slate-50 transition-colors">
                                        <td className="px-6 py-4 font-bold text-slate-800">{load.generatorName}</td>
                                        <td className="px-6 py-4 text-center font-black text-indigo-600">{load.liters} L</td>
                                        <td className="px-6 py-4 text-center text-slate-600 font-mono">{load.date}</td>
                                        <td className="px-6 py-4 text-center">
                                            <div className="flex items-center justify-center gap-2">
                                                <span className="text-[10px] text-slate-400">{load.previousLevel}%</span>
                                                <svg className="w-3 h-3 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
                                                <span className="font-black text-emerald-600">{load.newLevel}%</span>
                                            </div>
                                        </td>
                                        <td className="px-6 py-4 text-right">
                                            <div className="flex justify-end gap-1">
                                                <button 
                                                    onClick={() => handleDeleteClick(load.id)}
                                                    className={`px-3 py-1 rounded-lg text-[10px] font-black uppercase transition-all shadow-sm ${
                                                        confirmDelete.id === load.id 
                                                            ? confirmDelete.stage === 1 
                                                                ? 'bg-amber-500 text-white' 
                                                                : 'bg-red-600 text-white'
                                                            : 'bg-slate-100 text-slate-400 hover:text-red-500'
                                                    }`}
                                                >
                                                    {confirmDelete.id === load.id 
                                                        ? confirmDelete.stage === 1 ? '¿Confirmar?' : '¡ELIMINAR!'
                                                        : <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                                                    }
                                                </button>
                                                {confirmDelete.id === load.id && (
                                                    <button 
                                                        onClick={() => setConfirmDelete({ id: '', stage: 0 })}
                                                        className="px-2 py-1 bg-slate-200 text-slate-600 rounded-lg text-[10px] font-black uppercase"
                                                    >
                                                        X
                                                    </button>
                                                )}
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

export default FuelManagementView;

