                                <th className="px-6 py-4 text-center">Horario</th>
                                <th className="px-6 py-4 text-center">Duración</th>
                                <th className="px-6 py-4 text-center">Impacto Fuel</th>
                                <th className="px-6 py-4 text-right"></th>
                            </tr>
                        </thead>
