  const [password, setPassword] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [rememberMe, setRememberMe] = useState(() => !!localStorage.getItem('remembered_username'));

  const [adminUser, setAdminUser] = useState('');
  const [adminPass, setAdminPass] = useState('');
  const [showAdminPass, setShowAdminPass] = useState(false);

  const [mode, setMode] = useState<'login' | 'recovery' | 'admin_auth' | 'change'>('login');
  const [error, setError] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [showNewPass, setShowNewPass] = useState(false);

  const getStoredPassword = () => localStorage.getItem('app_password') || 'm4r4ndu#c0m';

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const storedPass = getStoredPassword();
    if (username === 'noc' && password === storedPass) {
      if (rememberMe) {
        localStorage.setItem('remembered_username', username);
      } else {
        localStorage.removeItem('remembered_username');
      }
      onLogin();
    } else {
      setError('Credenciales de operador incorrectas.');
    }
  };

  const handleAdminAuth = (e: React.FormEvent) => {
    e.preventDefault();
    if (adminUser === 'admin' && adminPass === 'Marandu2025') {
      setMode('change');
      setError('');
      setAdminPass('');
    } else {
      setError('Acceso denegado: Credenciales de administrador inválidas.');
    }
  };

  const handleChangePassword = (e: React.FormEvent) => {
    e.preventDefault();
    if (newPassword.length < 6) {
      setError('La nueva contraseña debe tener al menos 6 caracteres.');
      return;
    }
    localStorage.setItem('app_password', newPassword);
