export default Header;

export enum Status {
  Optimal = 'EN ESTADO OPTIMO',
  NeedsRecharge = 'NECESITA RECARGA',
  Warning = 'PROXIMO A DAR AVISO',
}

export interface Outage {
  id: string;
  generatorId: number;
  generatorName: string;
  date: string;
  startTime: string;
  endTime: string;
  durationHours: number;
  fuelDeducted: number;
  operator: string;
}

export interface FuelLoad {
  id: string;
  generatorId: number;
  generatorName: string;
  liters: string;
  date: string;
  previousLevel: number;
  newLevel: number;
  operator: string;
}

export interface Generator {
  id: number;
  name: string;
  executionHours: string;
  fuelLevel: number; // Porcentaje 0-100
  tankCapacity: string; 
  powerKVA: string; // Nueva columna basada en la imagen
  lastRechargeLiters: string; 
  status: Status;
  lastRechargeDate: string; // DD/MM/YYYY
  timeSinceLastRecharge: number; // en días
  operator?: string;
}

export type StoredGenerator = Omit<Generator, 'status' | 'timeSinceLastRecharge'>;

export interface SortConfig {
  key: keyof Generator;
  direction: 'ascending' | 'descending';
}

export interface ReportEntry {
  id: number;
  n: string;
  geLocalidad: string;
  fechaAltCarga: string;
  entradaEnFuncionamiento: string;
  hIn: string;
  hFin: string;
  tdfHs: string;
