                                                                <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                                                            </button>
                                                        </div>
                                                    ) : (
                                                        <button 
                                                            onClick={() => setEditingOutageId(outage.id)}
                                                            className="text-[9px] font-black text-indigo-600 underline hover:text-indigo-800"
                                                        >
                                                            Fijar Restablecimiento
                                                        </button>
                                                    )}
                                                </div>
                                            )}
                                        </td>
                                        <td className="px-6 py-4 text-center font-bold text-slate-700">
                                            {outage.endTime ? `${outage.durationHours.toFixed(1)} Hr` : '-'}
                                        </td>
                                        <td className="px-6 py-4 text-center">
                                            {outage.endTime ? (
                                                <div className="flex flex-col items-center">
                                                    <span className="font-black text-rose-600 text-xs">-{outage.fuelDeducted}%</span>
                                                    <div className="w-12 h-1 bg-rose-100 rounded-full overflow-hidden mt-1">
                                                        <div className="h-full bg-rose-500" style={{ width: `${outage.fuelDeducted}%` }} />
                                                    </div>
                                                </div>
                                            ) : (
                                                <span className="text-[10px] font-black text-slate-300 italic uppercase">Pendiente</span>
                                            )}
                                        </td>
                                        <td className="px-6 py-4 text-right">
                                            <button 
                                                onClick={() => onDeleteOutage(outage.id)}
                                                className="opacity-0 group-hover:opacity-100 text-slate-300 hover:text-rose-500 transition-all p-2"
                                            >
                                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                                            </button>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

