const runAI = async () => {
  if (!image) return;

  // ⚠️ IMPORTANTE: en React/Vite las variables deben empezar con REACT_APP_ o VITE_
  if (!process.env.REACT_APP_API_KEY) {
    console.error("API_KEY no encontrada. Verifique su entorno local.");
    alert("Error: La clave de API no está configurada en este entorno.");
    return;
  }

  setLoading(true);
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.REACT_APP_API_KEY });
    const base64Data = image.split(',')[1];

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { text: "Analiza la imagen de este generador o tablero de control industrial. Identifica y extrae con máxima precisión: 1. Nivel de combustible actual (valor numérico 0-100), 2. Horas totales de ejecución (valor numérico), 3. Nombre o identificación del equipo si es visible." },
          { inlineData: { mimeType: "image/jpeg", data: base64Data } }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            fuelLevel: { type: Type.NUMBER },
            executionHours: { type: Type.NUMBER },
            name: { type: Type.STRING }
          }
        }
      }
    });

    // ✅ CORRECCIÓN: usar await response.text()
    const textResponse = await response.text();
    let data: any = {};
    try {
      data = JSON.parse(textResponse || '{}');
    } catch (parseErr) {
      console.error("Error al parsear respuesta IA:", parseErr);
    }

    let matchedId: number | undefined;
    if (data.name) {
      const found = generators.find(g =>
        g.name.toLowerCase().includes(data.name.toLowerCase()) ||
        data.name.toLowerCase().includes(g.name.toLowerCase())
      );
      if (found) matchedId = found.id;
    }

    setResults({
      fuel: data.fuelLevel ?? undefined,
      hours: data.executionHours ? String(data.executionHours) : undefined,
      generatorId: matchedId
    });
  } catch (error) {
    console.error("Error en proceso de IA:", error);
    alert("No se pudo procesar la imagen. Asegúrese de que sea nítida y legible.");
  } finally {
    setLoading(false);
  }
};

