          tdfHs: '0',
          autonomia: '100',
          timestamp: new Date().toISOString(),
          operator: currentOperator
        };
        return { ...r, entries: [...r.entries, newEntry] };
      }
      return r;
    }));
  };

  const handleUpdateReportEntry = (reportId: string, entryId: number, key: keyof ReportEntry, value: string) => {
    setReports(prev => prev.map(r => {
      if (r.id === reportId) {
        return {
          ...r,
          entries: r.entries.map(e => e.id === entryId ? { ...e, [key]: value } : e)
        };
      }
      return r;
