import React, { useState, useRef, useEffect } from "react";
import { StoredGenerator } from "../types";

interface AIScanModalProps {
  isOpen: boolean;
  onClose: () => void;
  generators: StoredGenerator[];
  onConfirmUpdate: (id: number, fuel: number, hours: string) => void;
}

const AIScanModal: React.FC<AIScanModalProps> = ({
  isOpen,
  onClose,
  generators,
  onConfirmUpdate,
}) => {
  const [mode, setMode] = useState<"upload" | "camera" | "screen">("camera");
  const [image, setImage] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const fileInputRef = useRef<HTMLInputElement | null>(null);

  useEffect(() => {
    if (!isOpen) {
      setImage(null);
      setLoading(false);
      setMode("camera");
    }
  }, [isOpen]);

  if (!isOpen) return null;

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = () => setImage(reader.result as string);
    reader.readAsDataURL(file);
  };

  return (
    <div className="fixed inset-0 z-50 bg-slate-950/90 backdrop-blur-md flex items-center justify-center p-4">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-3xl max-h-[95vh] overflow-hidden border border-slate-200 flex flex-col">

        {/* HEADER */}
        <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-50">
          <h2 className="text-xl font-black text-slate-900 tracking-tight flex items-center gap-2">
            <span className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white text-xs">
              AI
            </span>
            <span>SISTEMA AUTOMATIZADO</span>
          </h2>

          <button
            onClick={onClose}
            className="text-slate-500 hover:text-slate-900 text-sm font-semibold"
          >
            ✕ Cerrar
          </button>
        </div>

        {/* BODY */}
        <div className="flex-1 overflow-y-auto p-6 space-y-6">

          {/* MODE SELECTOR */}
          <div className="flex gap-3">
            {["camera", "upload", "screen"].map((m) => (
              <button
                key={m}
                onClick={() => setMode(m as any)}
                className={`px-4 py-2 rounded-lg text-sm font-semibold transition ${
                  mode === m
                    ? "bg-indigo-600 text-white"
                    : "bg-slate-100 text-slate-700 hover:bg-slate-200"
                }`}
              >
                {m.toUpperCase()}
              </button>
            ))}
          </div>

          {/* CONTENT */}
