import React, { useState, useRef, useEffect } from "react";
import { GoogleGenAI, Type } from "@google/genai";
import { StoredGenerator } from "../types";

interface AIScanModalProps {
  isOpen: boolean;
  onClose: () => void;
  generators: StoredGenerator[];
  onConfirmUpdate: (id: number, fuel: number, hours: string) => void;
}

const AIScanModal: React.FC<AIScanModalProps> = ({
  isOpen,
  onClose,
  generators,
  onConfirmUpdate,
}) => {
  const [mode, setMode] = useState<"upload" | "camera" | "screen">("camera");
  const [image, setImage] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [isStreamActive, setIsStreamActive] = useState(false);
  const [flashEffect, setFlashEffect] = useState(false);
  const [results, setResults] = useState<{ fuel?: number; hours?: string; generatorId?: number; equipmentName?: string } | null>(null);

  const fileInputRef = useRef<HTMLInputElement | null>(null);
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const streamRef = useRef<MediaStream | null>(null);

  useEffect(() => {
    if (!isOpen) {
      stopMedia();
      setImage(null);
      setResults(null);
      setLoading(false);
    }
  }, [isOpen]);

  const stopMedia = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    setIsStreamActive(false);
  };

  const startCamera = async () => {
    stopMedia();
    setMode("camera");
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: "environment", width: { ideal: 1920 }, height: { ideal: 1080 } },
        audio: false
      });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        streamRef.current = stream;
        setIsStreamActive(true);
      }
    } catch (err) {
      console.error("Cámara no disponible:", err);
      alert("No se pudo acceder a la cámara. Por favor verifique los permisos en su navegador.");
      setMode("upload");
    }
  };

  const startScreenCapture = async () => {
    stopMedia();
    setMode("screen");
    try {
      const stream = await navigator.mediaDevices.getDisplayMedia({ video: true });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        streamRef.current = stream;
        setIsStreamActive(true);
      }
    } catch (err) {
      console.error("Captura de pantalla no disponible:", err);
      setMode("upload");
    }
  };

  const captureFrame = () => {
    if (videoRef.current && canvasRef.current && isStreamActive) {
      setFlashEffect(true);
      setTimeout(() => setFlashEffect(false), 200);

      const canvas = canvasRef.current;
      const video = videoRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext("2d");
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL("image/jpeg", 0.9);
        setImage(dataUrl);
        stopMedia();
      }
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => setImage(reader.result as string);
    reader.readAsDataURL(file);
  };

  const runAIAnalysis = async () => {
    if (!image) return;
    setLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const base64Data = image.split(",")[1];

      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: {
          parts: [
            { text: "Analiza la imagen de este tablero de control industrial de un generador. Extrae con precisión: 1. Nivel de combustible (porcentaje 0-100), 2. Horas totales de ejecución (running hours), 3. Cualquier identificación o nombre del equipo visible." },
            { inlineData: { mimeType: "image/jpeg", data: base64Data } }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              fuelLevel: { type: Type.NUMBER, description: "Nivel de combustible entre 0 y 100" },
              runningHours: { type: Type.NUMBER, description: "Horas de ejecución totales como número" },
              equipmentId: { type: Type.STRING, description: "Identificación o nombre del equipo detectado" }
            },
            required: ["fuelLevel", "runningHours"]
          }
        }
      });

      const data = JSON.parse(response.text || "{}");

      let matchedId: number | undefined;
      if (data.equipmentId) {
        const found = generators.find(g => 
          g.name.toLowerCase().includes(data.equipmentId.toLowerCase()) ||
          data.equipmentId.toLowerCase().includes(g.name.toLowerCase())
        );
        if (found) matchedId = found.id;
      }

      setResults({
        fuel: data.fuelLevel,
        hours: String(data.runningHours),
        generatorId: matchedId,
        equipmentName: data.equipmentId
      });
    } catch (error: any) {
      console.error("Error en IA:", error);
      if (error.message?.includes("entity was not found")) {
        alert("La API Key es inválida. Por favor re-conéctela.");
        if (window.aistudio) await window.aistudio.openSelectKey();
      } else {
        alert("No se pudo procesar la imagen. Asegúrese de que el tablero sea legible y esté bien iluminado.");
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 bg-slate-950/90 backdrop-blur-md flex items-center justify-center p-4">
      <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-4xl max-h-[95vh] overflow-hidden border border-slate-200 flex flex-col">

        {/* CABECERA */}
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
          <div className="flex flex-col">
            <h2 className="text-xl font-black text-slate-900 tracking-tight flex items-center gap-2 uppercase">
              <span className="w-10 h-10 bg-indigo-600 rounded-2xl flex items-center justify-center text-white text-xs shadow-lg shadow-indigo-200">AI</span>
              SISTEMA AUTOMATIZADO
            </h2>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">Escaneo Multimodal Industrial v3.2</p>
          </div>

          <button
            onClick={onClose}
            className="w-10 h-10 rounded-full bg-slate-100 text-slate-500 hover:bg-rose-50 hover:text-rose-600 flex items-center justify-center transition-all font-bold"
          >
            ✕
          </button>
        </div>

        {/* CUERPO */}
        <div className="flex-1 overflow-y-auto p-8 space-y-8">

          {/* SELECTOR DE MODO */}
          {!image && !results && (
            <div className="flex bg-slate-100 p-1.5 rounded-2xl w-fit mx-auto border border-slate-200 shadow-inner">
              <button
                onClick={startCamera}
                className={`px-6 py-2 rounded-xl text-[11px] font-black uppercase tracking-widest transition-all ${mode === "camera" ? "bg-white text-indigo-600 shadow-md" : "text-slate-500 hover:text-slate-700"}`}
              >
                Cámara
              </button>
              <button
                onClick={startScreenCapture}
                className={`px-6 py-2 rounded-xl text-[11px] font-black uppercase tracking-widest transition-all ${mode === "screen" ? "bg-white text-indigo-600 shadow-md" : "text-slate-500 hover:text-slate-700"}`}
              >
                Pantalla
              </button>
              <button
                onClick={() => { stopMedia(); setMode("upload"); }}
                className={`px-6 py-2 rounded-xl text-[11px] font-black uppercase tracking-widest transition-all ${mode === "upload" ? "bg-white text-indigo-600 shadow-md" : "text-slate-500 hover:text-slate-700"}`}
              >
                Archivo
              </button>
            </div>
          )}

          {/* VISOR DE ESCANEO */}
          <div className="relative aspect-video bg-slate-900 rounded-[2rem] overflow-hidden border-4 border-white shadow-2xl flex items-center justify-center">
            {flashEffect && <div className="absolute inset-0 bg-white z-20 animate-pulse" />}

            {isStreamActive ? (
              <>
                <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover" />
                {/* Overlay de escaneo */}
                <div className="absolute inset-0 border-[40px] border-black/20 pointer-events-none">
                   <div className="w-full h-full border-2 border-indigo-400/50 rounded-lg relative">
                      <div className="absolute top-0 left-0 w-8 h-8 border-t-4 border-l-4 border-indigo-500"></div>
                      <div className="absolute top-0 right-0 w-8 h-8 border-t-4 border-r-4 border-indigo-500"></div>
                      <div className="absolute bottom-0 left-0 w-8 h-8 border-b-4 border-l-4 border-indigo-500"></div>
                      <div className="absolute bottom-0 right-0 w-8 h-8 border-b-4 border-r-4 border-indigo-500"></div>
                      <div className="absolute top-1/2 left-0 right-0 h-0.5 bg-indigo-500/30 animate-scan"></div>
                   </div>
                </div>
                <div className="absolute bottom-8 left-0 right-0 flex justify-center">
                  <button 
                    onClick={captureFrame}
                    className="w-20 h-20 bg-white rounded-full p-1 shadow-2xl active:scale-90 transition-all border-4 border-slate-100 flex items-center justify-center"
                  >
                    <div className="w-full h-full rounded-full bg-indigo-600 border-2 border-white shadow-inner" />
                  </button>
                </div>
              </>
            ) : image ? (
              <img src={image} className="w-full h-full object-contain" alt="Capturada" />
            ) : mode === "upload" ? (
              <div onClick={() => fileInputRef.current?.click()} className="flex flex-col items-center gap-4 cursor-pointer hover:bg-slate-800 transition-colors w-full h-full justify-center group">
                 <div className="w-20 h-20 bg-slate-800 rounded-full flex items-center justify-center text-slate-500 group-hover:bg-indigo-600 group-hover:text-white transition-all shadow-xl">
                    <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
                 </div>
                 <p className="text-slate-400 font-bold uppercase tracking-widest text-[11px]">Subir imagen del tablero</p>
                 <input ref={fileInputRef} type="file" accept="image/*" className="hidden" onChange={handleFileUpload} />
              </div>
            ) : (
              <p className="text-slate-500 font-black uppercase text-xs tracking-widest">Iniciando fuente de video...</p>
            )}
          </div>

          {/* RESULTADOS DE IA */}
          {results && (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-in slide-in-from-bottom-4 fade-in duration-500">
               <div className="space-y-4">
                  <div>
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest block mb-2">Equipo Detectado:</label>
                    <div className="relative">
                      <select 
                        value={results.generatorId || ""}
                        onChange={(e) => setResults({...results, generatorId: Number(e.target.value)})}
                        className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl font-black text-slate-800 focus:ring-4 focus:ring-indigo-500/10 outline-none appearance-none"
                      >
                        <option value="">-- Seleccione el generador --</option>
                        {generators.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                      </select>
                      <div className="absolute right-5 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" /></svg>
                      </div>
                    </div>
                    {results.equipmentName && (
                      <p className="text-[10px] font-bold text-indigo-500 uppercase mt-2">IA detectó: "{results.equipmentName}"</p>
                    )}
                  </div>
               </div>
               <div className="grid grid-cols-2 gap-4">
                  <div className="p-6 bg-indigo-50 rounded-[2rem] border border-indigo-100 flex flex-col justify-center text-center shadow-inner">
                      <span className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-1">Combustible</span>
                      <div className="flex items-center justify-center gap-1">
                        <input 
                          type="number"
                          value={results.fuel || 0}
                          onChange={(e) => setResults({...results, fuel: Number(e.target.value)})}
                          className="bg-transparent text-4xl font-black text-indigo-700 text-center outline-none w-24"
                        />
                        <span className="text-xl font-black text-indigo-600">%</span>
                      </div>
                  </div>
                  <div className="p-6 bg-emerald-50 rounded-[2rem] border border-emerald-100 flex flex-col justify-center text-center shadow-inner">
                      <span className="text-[10px] font-black text-emerald-400 uppercase tracking-widest mb-1">Horas Ejec.</span>
                      <div className="flex items-center justify-center gap-1">
                        <input 
                          type="text"
                          value={results.hours || ""}
                          onChange={(e) => setResults({...results, hours: e.target.value})}
                          className="bg-transparent text-3xl font-black text-emerald-700 text-center outline-none w-24"
                        />
                        <span className="text-xs font-black text-emerald-600">Hr</span>
                      </div>
                  </div>
               </div>
            </div>
          )}
        </div>

        {/* PIE DE PÁGINA */}
        <div className="p-6 border-t border-slate-100 bg-slate-50 flex justify-between items-center px-8">
          <button
            onClick={() => { setImage(null); setResults(null); stopMedia(); if(mode !== "upload") mode === "camera" ? startCamera() : startScreenCapture(); }}
            className="px-6 py-3 rounded-2xl bg-slate-200 text-slate-700 font-black text-[10px] uppercase tracking-widest hover:bg-slate-300 transition-all"
          >
            Reiniciar
          </button>

          <div className="flex gap-4">
            {!results ? (
              <button
                disabled={!image || loading}
                onClick={runAIAnalysis}
                className="px-12 py-4 rounded-2xl bg-indigo-600 text-white font-black text-[10px] uppercase tracking-[0.2em] shadow-xl shadow-indigo-600/20 disabled:opacity-50 transition-all flex items-center gap-3 active:scale-95"
              >
                {loading ? (
                  <>
                    <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                    Analizando Tablero...
                  </>
                ) : "Extraer Información"}
              </button>
            ) : (
              <button
                disabled={!results.generatorId || results.fuel === undefined || !results.hours}
                onClick={() => {
                  if (results.generatorId && results.fuel !== undefined && results.hours) {
                    onConfirmUpdate(results.generatorId, results.fuel, results.hours);
                    onClose();
                  }
                }}
                className="px-12 py-4 rounded-2xl bg-emerald-600 text-white font-black text-[10px] uppercase tracking-[0.2em] shadow-xl shadow-emerald-600/20 disabled:opacity-50 transition-all active:scale-95"
              >
                Confirmar y Sincronizar
              </button>
            )}
          </div>
        </div>
      </div>
      <canvas ref={canvasRef} className="hidden" />
      <style>{`
        @keyframes scan {
          0% { top: 0%; }
          100% { top: 100%; }
        }
        .animate-scan {
          animation: scan 2.5s linear infinite;
        }
      `}</style>
    </div>
  );
};

export default AIScanModal;

import React, { useState, useMemo } from 'react';
import { Report, ReportEntry, StoredGenerator } from '../types';
import ReportTable from './ReportTable';

interface ReportsViewProps {
    reports: Report[];
    generators: StoredGenerator[];
    currentMonth: string;
    onMonthChange: (month: string) => void;
    onFinalizeMonth: (month: string) => void;
    onAddEntry: (reportId: string) => void;
    onUpdateEntry: (reportId: string, entryId: number, key: keyof ReportEntry, value: string) => void;
    onDeleteEntry: (reportId: string, entryId: number) => void;
    onAddReport: (generatorName: string) => void;
}

const ReportsView: React.FC<ReportsViewProps> = ({ 
    reports, 
    generators, 
    currentMonth, 
    onMonthChange, 
    onFinalizeMonth,
    onAddEntry, 
    onUpdateEntry, 
    onDeleteEntry, 
    onAddReport 
}) => {
    const [selectedGeneratorToAdd, setSelectedGeneratorToAdd] = useState('');

    const filteredReports = useMemo(() => {
        return reports.filter(r => r.month === currentMonth);
    }, [reports, currentMonth]);

    const generatorsWithReportThisMonth = useMemo(() => new Set(filteredReports.map(r => r.generatorName)), [filteredReports]);

    const generatorsWithoutReportThisMonth = useMemo(() => 
        generators.filter(g => !generatorsWithReportThisMonth.has(g.name))
    , [generators, generatorsWithReportThisMonth]);

    const handleAddClick = () => {
        if (selectedGeneratorToAdd) {
            onAddReport(selectedGeneratorToAdd);
            setSelectedGeneratorToAdd('');
        }
    };

    const isMonthFinalized = useMemo(() => {
        return filteredReports.length > 0 && filteredReports.every(r => r.isFinalized);
    }, [filteredReports]);

    return (
        <div className="space-y-8 mt-4">
            <div className="bg-white p-6 rounded-2xl shadow-xl border border-slate-200 flex flex-wrap items-center justify-between gap-6 print:hidden">
                <div className="flex items-center gap-6">
                    <div>
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Período Mensual:</label>
                        <input 
                            type="month" 
                            value={currentMonth} 
                            onChange={(e) => onMonthChange(e.target.value)}
                            className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 font-bold text-slate-700 focus:ring-2 focus:ring-red-500 outline-none"
                        />
                    </div>
                    {isMonthFinalized ? (
                      <div className="flex items-center gap-2 px-4 py-2 bg-emerald-100 text-emerald-700 rounded-xl border border-emerald-200 text-sm font-black">
