                  </div>
                  <div>
                    <h3 className="text-sm font-black uppercase tracking-wider">Rectificador Itaembé Guazú</h3>
                    <p className="text-[11px] font-bold text-slate-400 uppercase">Configuración de Red y Acceso</p>
