import React, { useState, useRef, useEffect } from "react";
import { StoredGenerator } from "../types";

interface ManualCaptureModalProps {
  isOpen: boolean;
  onClose: () => void;
  generators: StoredGenerator[];
  onConfirmUpdate: (id: number, fuel: number, hours: string) => void;
}

const ManualCaptureModal: React.FC<ManualCaptureModalProps> = ({
  isOpen,
  onClose,
  generators,
  onConfirmUpdate,
}) => {
  const [mode, setMode] = useState<"upload" | "camera" | "screen">("camera");
  const [image, setImage] = useState<string | null>(null);
  const [isStreamActive, setIsStreamActive] = useState(false);
  const [flashEffect, setFlashEffect] = useState(false);

  // Datos manuales
  const [selectedGenId, setSelectedGenId] = useState<number | ''>('');
  const [fuelValue, setFuelValue] = useState<number>(100);
  const [hoursValue, setHoursValue] = useState<string>('');

  const fileInputRef = useRef<HTMLInputElement | null>(null);
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const streamRef = useRef<MediaStream | null>(null);

  useEffect(() => {
    if (!isOpen) {
      stopMedia();
      setImage(null);
      setSelectedGenId('');
      setFuelValue(100);
      setHoursValue('');
    }
  }, [isOpen]);

  const stopMedia = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    setIsStreamActive(false);
  };

  const startCamera = async () => {
    stopMedia();
    setMode("camera");
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: "environment", width: { ideal: 1920 }, height: { ideal: 1080 } },
        audio: false
      });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        streamRef.current = stream;
        setIsStreamActive(true);
      }
    } catch (err) {
      console.error("Cámara no disponible:", err);
      alert("No se pudo acceder a la cámara. Por favor verifique los permisos.");
      setMode("upload");
    }
  };

  const startScreenCapture = async () => {
    stopMedia();
    setMode("screen");
    try {
      const stream = await navigator.mediaDevices.getDisplayMedia({ video: true });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        streamRef.current = stream;
        setIsStreamActive(true);
      }
    } catch (err) {
      console.error("Captura de pantalla no disponible:", err);
      setMode("upload");
    }
  };

  const captureFrame = () => {
    if (videoRef.current && canvasRef.current && isStreamActive) {
      setFlashEffect(true);
      setTimeout(() => setFlashEffect(false), 200);

      const canvas = canvasRef.current;
      const video = videoRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext("2d");
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL("image/jpeg", 0.9);
        setImage(dataUrl);
        stopMedia();
      }
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => setImage(reader.result as string);
    reader.readAsDataURL(file);
  };

  const handleConfirm = () => {
    if (selectedGenId && fuelValue !== undefined && hoursValue) {
      onConfirmUpdate(Number(selectedGenId), fuelValue, hoursValue);
      onClose();
    } else {
      alert("Por favor complete todos los campos (Generador, Combustible y Horas).");
    }
  };

  return (
    <div className="fixed inset-0 z-50 bg-slate-950/90 backdrop-blur-md flex items-center justify-center p-4">
      <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-5xl max-h-[95vh] overflow-hidden border border-slate-200 flex flex-col">

        {/* CABECERA */}
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
          <div className="flex flex-col">
            <h2 className="text-xl font-black text-slate-900 tracking-tight flex items-center gap-2 uppercase">
              <span className="w-10 h-10 bg-indigo-600 rounded-2xl flex items-center justify-center text-white text-xs shadow-lg shadow-indigo-200">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /></svg>
              </span>
              ASISTENTE DE CAPTURA VISUAL
            </h2>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">Soporte fotográfico para registro manual</p>
          </div>

          <button
            onClick={onClose}
            className="w-10 h-10 rounded-full bg-slate-100 text-slate-500 hover:bg-rose-50 hover:text-rose-600 flex items-center justify-center transition-all font-bold"
          >
            ✕
          </button>
        </div>

        {/* CUERPO */}
        <div className="flex-1 overflow-y-auto p-6 md:p-8 flex flex-col lg:grid lg:grid-cols-2 gap-8">

          {/* LADO IZQUIERDO: VISOR */}
          <div className="space-y-4">
            {!image && (
              <div className="flex bg-slate-100 p-1.5 rounded-2xl w-fit mx-auto border border-slate-200 shadow-inner">
                <button
                  onClick={startCamera}
                  className={`px-6 py-2 rounded-xl text-[11px] font-black uppercase tracking-widest transition-all ${mode === "camera" ? "bg-white text-indigo-600 shadow-md" : "text-slate-500 hover:text-slate-700"}`}
                >
                  Cámara
                </button>
                <button
                  onClick={startScreenCapture}
                  className={`px-6 py-2 rounded-xl text-[11px] font-black uppercase tracking-widest transition-all ${mode === "screen" ? "bg-white text-indigo-600 shadow-md" : "text-slate-500 hover:text-slate-700"}`}
                >
                  Pantalla
                </button>
                <button
                  onClick={() => { stopMedia(); setMode("upload"); }}
                  className={`px-6 py-2 rounded-xl text-[11px] font-black uppercase tracking-widest transition-all ${mode === "upload" ? "bg-white text-indigo-600 shadow-md" : "text-slate-500 hover:text-slate-700"}`}
                >
                  Archivo
                </button>
              </div>
            )}

            <div className="relative aspect-video bg-slate-900 rounded-[2rem] overflow-hidden border-4 border-white shadow-2xl flex items-center justify-center group">
              {flashEffect && <div className="absolute inset-0 bg-white z-20 animate-pulse" />}

              {isStreamActive ? (
                <>
                  <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover" />
                  <div className="absolute inset-0 border-[40px] border-black/20 pointer-events-none">
                     <div className="w-full h-full border-2 border-indigo-400/50 rounded-lg relative">
                        <div className="absolute top-0 left-0 w-8 h-8 border-t-4 border-l-4 border-indigo-500"></div>
                        <div className="absolute bottom-0 right-0 w-8 h-8 border-b-4 border-r-4 border-indigo-500"></div>
                     </div>
                  </div>
                  <div className="absolute bottom-8 left-0 right-0 flex justify-center">
                    <button 
                      onClick={captureFrame}
                      className="w-16 h-16 bg-white rounded-full p-1 shadow-2xl active:scale-90 transition-all border-4 border-slate-100 flex items-center justify-center"
                    >
                      <div className="w-full h-full rounded-full bg-indigo-600 border-2 border-white shadow-inner" />
                    </button>
                  </div>
                </>
              ) : image ? (
                <>
                  <img src={image} className="w-full h-full object-contain" alt="Referencia" />
                  <button 
                    onClick={() => { setImage(null); startCamera(); }}
                    className="absolute top-4 right-4 bg-black/50 hover:bg-black/70 text-white px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all backdrop-blur-sm"
                  >
                    Nueva Foto
                  </button>
                </>
              ) : mode === "upload" ? (
                <div onClick={() => fileInputRef.current?.click()} className="flex flex-col items-center gap-4 cursor-pointer hover:bg-slate-800 transition-colors w-full h-full justify-center group/btn">
                   <div className="w-16 h-16 bg-slate-800 rounded-full flex items-center justify-center text-slate-500 group-hover/btn:bg-indigo-600 group-hover/btn:text-white transition-all shadow-xl">
                      <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
                   </div>
                   <p className="text-slate-400 font-bold uppercase tracking-widest text-[10px]">Cargar imagen del tablero</p>
                   <input ref={fileInputRef} type="file" accept="image/*" className="hidden" onChange={handleFileUpload} />
                </div>
              ) : (
                <p className="text-slate-500 font-black uppercase text-xs tracking-widest">Iniciando fuente...</p>
              )}
            </div>
            <p className="text-[9px] text-slate-400 font-bold text-center uppercase tracking-widest">Capture la imagen para usarla como referencia visual durante la carga</p>
          </div>

          {/* LADO DERECHO: FORMULARIO */}
          <div className="bg-slate-50 rounded-[2rem] p-8 border border-slate-200 space-y-6">
             <div className="space-y-4">
                <div>
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest block mb-2">Generador Seleccionado:</label>
                  <select 
                    value={selectedGenId}
                    onChange={(e) => setSelectedGenId(Number(e.target.value))}
                    className="w-full p-4 bg-white border border-slate-200 rounded-2xl font-black text-slate-800 focus:ring-4 focus:ring-indigo-500/10 outline-none"
                  >
                    <option value="">-- Elija el equipo --</option>
                    {generators.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                  </select>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="p-6 bg-white rounded-3xl border border-slate-200 flex flex-col justify-center text-center shadow-sm">
                      <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Combustible</span>
                      <div className="flex items-center justify-center gap-1">
                        <input 
                          type="number"
                          value={fuelValue}
                          onChange={(e) => setFuelValue(Number(e.target.value))}
                          className="bg-transparent text-4xl font-black text-indigo-600 text-center outline-none w-24"
                        />
                        <span className="text-xl font-black text-indigo-400">%</span>
                      </div>
                  </div>
                  <div className="p-6 bg-white rounded-3xl border border-slate-200 flex flex-col justify-center text-center shadow-sm">
                      <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Horas Ejec.</span>
                      <div className="flex items-center justify-center gap-1">
                        <input 
                          type="text"
                          value={hoursValue}
                          onChange={(e) => setHoursValue(e.target.value)}
                          placeholder="0.0"
                          className="bg-transparent text-3xl font-black text-emerald-600 text-center outline-none w-24 placeholder:text-slate-100"
                        />
                        <span className="text-xs font-black text-emerald-400 uppercase">Hr</span>
                      </div>
                  </div>
                </div>

                <div className="bg-indigo-600 p-6 rounded-3xl text-white shadow-xl shadow-indigo-200">
                  <div className="flex items-start gap-4">
                    <div className="w-10 h-10 bg-white/20 rounded-xl flex items-center justify-center text-white shrink-0">
                      <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                    </div>
                    <div>
                      <h4 className="font-black text-[10px] uppercase tracking-wider mb-1">Nota de Operación</h4>
                      <p className="text-[11px] font-medium leading-relaxed opacity-90">Transcriba los valores que observa en el visor izquierdo. Al confirmar, los datos se sincronizarán con el Dashboard principal y quedarán registrados en los Logs.</p>
                    </div>
                  </div>
                </div>
             </div>

             <div className="pt-4">
                <button
                  disabled={!selectedGenId || !hoursValue}
                  onClick={handleConfirm}
                  className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-xl shadow-slate-200 disabled:opacity-30 transition-all active:scale-95"
                >
                  Confirmar y Sincronizar
                </button>
             </div>
          </div>
        </div>

        {/* PIE DE PÁGINA */}
        <div className="p-6 border-t border-slate-100 bg-slate-50 flex justify-end">
           <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest italic">Modo de Captura Visual sin Procesamiento Automático</p>
        </div>
      </div>
      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

