import FuelManagementView from './components/FuelManagementView';
import LoginView from './components/LoginView';
import OutagesView from './components/OutagesView';

declare var html2canvas: any;

const calculateDaysSince = (dateStr: string, fromDate: Date): number => {
  const parts = dateStr.split('/');
  if (parts.length !== 3) return 0;
  const [day, month, year] = parts;
  const formattedDate = new Date(`${year}-${month}-${day}`);
  if (isNaN(formattedDate.getTime())) return 0;

  const controlDate = new Date(fromDate);
  controlDate.setHours(0, 0, 0, 0);
  formattedDate.setHours(0,0,0,0);

  const diffTime = controlDate.getTime() - formattedDate.getTime();
  if (diffTime < 0) return 0;
  return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
};

const extractNumber = (val: string | number): number => {
  if (typeof val === 'number') return val;
  const match = val.match(/(\d+[,.]?\d*)/);
  if (!match) return 0;
  return parseFloat(match[0].replace(',', '.'));
};

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(() => localStorage.getItem('is_auth') === 'true');
  const [view, setView] = useState<'dashboard' | 'reports' | 'logs' | 'fuel' | 'outages'>('dashboard');
  const [currentMonth, setCurrentMonth] = useState(() => new Date().toISOString().slice(0, 7));
  const [currentOperator, setCurrentOperator] = useState(() => localStorage.getItem('current_operator') || 'Operador NOC');

  const [generators, setGenerators] = useState<StoredGenerator[]>(() => {
    try {
      const saved = localStorage.getItem('generators');
      return saved ? JSON.parse(saved) : INITIAL_GENERATORS;
    } catch {
      return INITIAL_GENERATORS;
    }
  });

  const [fuelLoads, setFuelLoads] = useState<FuelLoad[]>(() => {
    try {
      const saved = localStorage.getItem('fuel_loads');
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  const [outages, setOutages] = useState<Outage[]>(() => {
    try {
      const saved = localStorage.getItem('outages');
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  const [logs, setLogs] = useState<ChangeLog[]>(() => {
    try {
      const saved = localStorage.getItem('change_logs');
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  const [reports, setReports] = useState<Report[]>(() => {
    try {
        const saved = localStorage.getItem('reports_v2');
        return saved ? JSON.parse(saved) : [];
    } catch {
        return [];
    }
  });

  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'name', direction: 'ascending' });
  const [selectedRowId, setSelectedRowId] = useState<number | null>(null);
  const [editingCell, setEditingCell] = useState<{ id: number; key: keyof Generator } | null>(null);
  const [controlDate, setControlDate] = useState(new Date());
  const [isSheetModalOpen, setIsSheetModalOpen] = useState(false);
  const [isCaptureModalOpen, setIsCaptureModalOpen] = useState(false);

  useEffect(() => {
    localStorage.setItem('generators', JSON.stringify(generators));
    localStorage.setItem('reports_v2', JSON.stringify(reports));
    localStorage.setItem('change_logs', JSON.stringify(logs));
    localStorage.setItem('fuel_loads', JSON.stringify(fuelLoads));
    localStorage.setItem('outages', JSON.stringify(outages));
    localStorage.setItem('is_auth', String(isAuthenticated));
    localStorage.setItem('current_operator', currentOperator);
  }, [generators, reports, logs, fuelLoads, outages, isAuthenticated, currentOperator]);

  const addLog = (generatorName: string, field: string, oldVal: any, newVal: any, source: ChangeLog['source'], operator: string = currentOperator) => {
    const newLog: ChangeLog = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toISOString(),
      generatorName,
      field,
      oldValue: oldVal,
      newValue: newVal,
      source,
      operator
    };
    setLogs(prev => [newLog, ...prev].slice(0, 500));
  };

  const calculateStatus = (fuelLevel: number): Status => {
    if (fuelLevel >= 71) return Status.Optimal;
    if (fuelLevel >= 70) return Status.Warning;
    return Status.NeedsRecharge;
  };

  const processedGenerators: Generator[] = useMemo(() => {
    return generators.map(g => ({
      ...g,
      status: calculateStatus(g.fuelLevel),
      timeSinceLastRecharge: calculateDaysSince(g.lastRechargeDate, controlDate),
    }));
  }, [generators, controlDate]);

  const sortedGenerators = useMemo(() => {
    const sortableItems = [...processedGenerators];
    if (sortConfig.key) {
      sortableItems.sort((a, b) => {
        const aValue = a[sortConfig.key];
        const bValue = b[sortConfig.key];
        if (typeof aValue === 'string' && typeof bValue === 'string') {
          return sortConfig.direction === 'ascending' ? aValue.localeCompare(bValue) : bValue.localeCompare(aValue);
        }
        return sortConfig.direction === 'ascending' ? (aValue as number) - (bValue as number) : (bValue as number) - (aValue as number);
      });
    }
    return sortableItems;
  }, [processedGenerators, sortConfig]);

  const handleGeneratorUpdate = (id: number, key: keyof StoredGenerator, value: string, source: ChangeLog['source'] = 'Manual') => {
    setGenerators(prev => 
      prev.map(gen => {
        if (gen.id === id) {
          let updatedValue: string | number = value;
          if (key === 'fuelLevel') {
            const numericValue = parseFloat(value.replace(',', '.'));
            updatedValue = isNaN(numericValue) ? gen[key] : numericValue;
          }

          if (gen[key] !== updatedValue) {
            addLog(gen.name, key, gen[key], updatedValue, source);
            return { ...gen, [key]: updatedValue };
          }
        }
        return gen;
      })
    );
    setEditingCell(null);
  };

  const handleCaptureUpdate = (id: number, fuel: number, hours: string) => {
    handleGeneratorUpdate(id, 'fuelLevel', String(fuel), 'Manual');
    handleGeneratorUpdate(id, 'executionHours', hours, 'Manual');
    setView('dashboard'); // Volver al dashboard después de capturar
  };

  const handleAddFuelLoad = (genId: number, liters: string, date: string, operator: string) => {
    const gen = generators.find(g => g.id === genId);
    if (!gen) return;

    const added_liters = extractNumber(liters);
    const tank_cap = extractNumber(gen.tankCapacity);

    const current_liters = (gen.fuelLevel / 100) * tank_cap;
    const new_liters = current_liters + added_liters;
    const new_level = tank_cap > 0 ? Math.min(100, Math.round((new_liters / tank_cap) * 100)) : 100;

    const newLoad: FuelLoad = {
      id: Math.random().toString(36).substr(2, 9),
      generatorId: genId,
      generatorName: gen.name,
      liters,
      date,
      previousLevel: gen.fuelLevel,
      newLevel: new_level,
      operator
    };

    setFuelLoads(prev => [newLoad, ...prev]);
    setGenerators(prev => prev.map(g => g.id === genId ? { ...g, fuelLevel: new_level, lastRechargeLiters: liters, lastRechargeDate: date } : g));
    addLog(gen.name, 'fuelLevel', gen.fuelLevel, new_level, 'Manual', operator);
  };

  const handleDownloadJPG = async () => {
    const element = document.getElementById('capture-container');
    if (!element) return;

    try {
      const canvas = await html2canvas(element, {
        scale: 2,
        useCORS: true,
        backgroundColor: '#f8fafc',
        logging: false
      });

      const image = canvas.toDataURL("image/jpeg", 0.9);
      const link = document.createElement('a');
      link.download = `dashboard-generadores-${new Date().toISOString().split('T')[0]}.jpg`;
      link.href = image;
      link.click();
    } catch (err) {
      console.error("Error capturando pantalla:", err);
      alert("Hubo un error al generar la captura de imagen.");
    }
  };

  if (!isAuthenticated) {
    return <LoginView onLogin={() => setIsAuthenticated(true)} />;
  }

  return (
    <div className="min-h-screen bg-slate-50 p-4 sm:p-6 lg:p-8 font-sans">
      <div id="capture-container" className="max-w-7xl mx-auto space-y-6 print:space-y-6 print:max-w-full print:p-4 print:bg-white">
        <Header 
          onAddGenerator={() => {
            const newId = generators.length > 0 ? Math.max(...generators.map(g => g.id)) + 1 : 1;
            setGenerators(prev => [...prev, {
              id: newId,
              name: `Nuevo GE ${newId}`,
              executionHours: '0 Hr',
              fuelLevel: 100,
              tankCapacity: '50 Lts',
              powerKVA: '22KVA',
              lastRechargeLiters: '0',
              lastRechargeDate: new Date().toLocaleDateString('es-ES')
            }]);
          }}
          onFileUpload={() => {}}
          onGoogleSheetImportClick={() => setIsSheetModalOpen(true)}
          onAIScanClick={() => setIsCaptureModalOpen(true)}
          controlDate={controlDate}
          onControlDateChange={(ds) => setControlDate(new Date(`${ds}T00:00:00`))}
          onSaveSessionCapture={() => alert('Sesión guardada')}
          onDownloadJPG={handleDownloadJPG}
          isHistoryView={false}
          onReturnToLive={() => setControlDate(new Date())}
          view={view}
          onToggleView={(v) => setView(v)}
          currentOperator={currentOperator}
          onOperatorChange={setCurrentOperator}
        />

        {view === 'dashboard' && (
          <div className="space-y-4">
            <div className="flex justify-end gap-2 print:hidden">
               <button 
                onClick={() => setIsSheetModalOpen(true)}
                className="bg-white border border-slate-200 text-slate-600 px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-50 transition-all shadow-sm flex items-center gap-2"
               >
                 <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
                 Importar Datos Externos
               </button>
            </div>
            <div className="bg-white rounded-xl shadow-xl border border-slate-200 overflow-hidden print:shadow-none print:border-none">
              <div className="overflow-x-auto">
                <GeneratorTable 
                  generators={sortedGenerators} 
                  onSort={(key) => setSortConfig(prev => ({ key, direction: prev.key === key && prev.direction === 'ascending' ? 'descending' : 'ascending' }))} 
                  sortConfig={sortConfig}
                  selectedRowId={selectedRowId}
                  onRowClick={setSelectedRowId}
                  editingCell={editingCell}
                  onCellDoubleClick={(id, key) => setEditingCell({ id, key })}
                  onUpdate={handleGeneratorUpdate}
                  onCancelEdit={() => setEditingCell(null)}
                  onDelete={(id) => setGenerators(prev => prev.filter(g => g.id !== id))}
                  isReadOnly={false}
                />
              </div>
              <Legend />
            </div>
          </div>
        )}

        {view === 'fuel' && (
          <FuelManagementView 
            generators={generators}
            fuelLoads={fuelLoads}
            onAddLoad={handleAddFuelLoad}
            onDeleteLoad={(id) => setFuelLoads(prev => prev.filter(l => l.id !== id))}
            defaultOperator={currentOperator}
          />
        )}

        {view === 'outages' && (
          <OutagesView 
            generators={generators}
            outages={outages}
            onAddOutage={(genId, date, start, end, operator) => {
              // Lógica de cortes de energía (calcula consumo automáticamente)
            }}
            onSetOutageEnd={(id, end) => {}}
            onDeleteOutage={(id) => {}}
            defaultOperator={currentOperator}
          />
        )}

        {view === 'reports' && (
          <ReportsView 
            reports={reports}
            generators={generators}
            currentMonth={currentMonth}
            onMonthChange={setCurrentMonth}
            onFinalizeMonth={(m) => {
              setReports(prev => prev.map(r => r.month === m ? { ...r, isFinalized: true } : r));
            }}
            onAddEntry={() => {}}
            onUpdateEntry={() => {}}
            onDeleteEntry={() => {}}
            onAddReport={() => {}}
          />
        )}

        {view === 'logs' && <LogsView logs={logs} />}
      </div>

      <div className="fixed bottom-4 right-4 print:hidden">
        <button 
          onClick={() => {
            setIsAuthenticated(false);
            localStorage.setItem('is_auth', 'false');
          }}
          className="bg-slate-800 text-white px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-red-600 transition-all shadow-xl border border-slate-700"
        >
          Cerrar Sesión
        </button>
      </div>

      <GoogleSheetImportModal isOpen={isSheetModalOpen} onClose={() => setIsSheetModalOpen(false)} onImport={async () => {}} />
      <ManualCaptureModal 
        isOpen={isCaptureModalOpen} 
        onClose={() => setIsCaptureModalOpen(false)} 
        generators={generators}
        onConfirmUpdate={handleCaptureUpdate}
      />
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from "react";
import { StoredGenerator } from "../types";

interface ManualCaptureModalProps {
  isOpen: boolean;
  onClose: () => void;
  generators: StoredGenerator[];
  onConfirmUpdate: (id: number, fuel: number, hours: string) => void;
}

const ManualCaptureModal: React.FC<ManualCaptureModalProps> = ({
  isOpen,
  onClose,
  generators,
  onConfirmUpdate,
}) => {
  const [mode, setMode] = useState<"upload" | "camera" | "screen">("camera");
  const [image, setImage] = useState<string | null>(null);
  const [isStreamActive, setIsStreamActive] = useState(false);
  const [flashEffect, setFlashEffect] = useState(false);

  const [selectedGenId, setSelectedGenId] = useState<number | ''>('');
  const [fuelValue, setFuelValue] = useState<number>(100);
  const [hoursValue, setHoursValue] = useState<string>('');

  const fileInputRef = useRef<HTMLInputElement | null>(null);
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const streamRef = useRef<MediaStream | null>(null);

  useEffect(() => {
    if (!isOpen) {
      stopMedia();
      setImage(null);
      setSelectedGenId('');
      setFuelValue(100);
      setHoursValue('');
    }
  }, [isOpen]);

  const stopMedia = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    setIsStreamActive(false);
  };

  const startCamera = async () => {
    stopMedia();
    setMode("camera");
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: "environment", width: { ideal: 1920 }, height: { ideal: 1080 } },
        audio: false
      });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        streamRef.current = stream;
        setIsStreamActive(true);
      }
    } catch (err) {
      console.error("Cámara no disponible:", err);
      alert("No se pudo acceder a la cámara. Por favor verifique los permisos.");
      setMode("upload");
    }
  };

  const startScreenCapture = async () => {
    stopMedia();
    setMode("screen");
    try {
      const stream = await navigator.mediaDevices.getDisplayMedia({ video: true });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        streamRef.current = stream;
        setIsStreamActive(true);
      }
    } catch (err) {
      console.error("Captura de pantalla no disponible:", err);
      setMode("upload");
    }
  };

  const captureFrame = () => {
    if (videoRef.current && canvasRef.current && isStreamActive) {
      setFlashEffect(true);
      setTimeout(() => setFlashEffect(false), 200);

      const canvas = canvasRef.current;
      const video = videoRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext("2d");
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL("image/jpeg", 0.9);
        setImage(dataUrl);
        stopMedia();
      }
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => setImage(reader.result as string);
    reader.readAsDataURL(file);
  };

  const handleConfirm = () => {
    if (selectedGenId && fuelValue !== undefined && hoursValue) {
      onConfirmUpdate(Number(selectedGenId), fuelValue, hoursValue);
      onClose();
    } else {
      alert("Por favor complete todos los campos obligatorios.");
    }
  };

  return (
    <div className="fixed inset-0 z-50 bg-slate-950/90 backdrop-blur-md flex items-center justify-center p-4">
      <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-5xl max-h-[90vh] overflow-hidden border border-slate-200 flex flex-col">

        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
          <div className="flex flex-col">
            <h2 className="text-xl font-black text-slate-900 tracking-tight flex items-center gap-2 uppercase">
              <span className="w-10 h-10 bg-indigo-600 rounded-2xl flex items-center justify-center text-white text-xs shadow-lg">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
              </span>
              Asistente de Captura Tablero
            </h2>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">Soporte visual para transcripción de horas y combustible</p>
          </div>

          <button
            onClick={onClose}
            className="w-10 h-10 rounded-full bg-slate-100 text-slate-500 hover:bg-rose-50 hover:text-rose-600 flex items-center justify-center transition-all font-bold"
          >
            ✕
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 lg:p-10 flex flex-col lg:grid lg:grid-cols-2 gap-10">

          <div className="space-y-4">
            {!image && (
              <div className="flex bg-slate-100 p-1.5 rounded-2xl w-fit mx-auto border border-slate-200 shadow-inner">
                <button
                  onClick={startCamera}
                  className={`px-6 py-2 rounded-xl text-[11px] font-black uppercase tracking-widest transition-all ${mode === "camera" ? "bg-white text-indigo-600 shadow-md" : "text-slate-500 hover:text-slate-700"}`}
                >
                  Cámara
                </button>
                <button
                  onClick={startScreenCapture}
                  className={`px-6 py-2 rounded-xl text-[11px] font-black uppercase tracking-widest transition-all ${mode === "screen" ? "bg-white text-indigo-600 shadow-md" : "text-slate-500 hover:text-slate-700"}`}
                >
                  Pantalla
                </button>
                <button
                  onClick={() => { stopMedia(); setMode("upload"); }}
                  className={`px-6 py-2 rounded-xl text-[11px] font-black uppercase tracking-widest transition-all ${mode === "upload" ? "bg-white text-indigo-600 shadow-md" : "text-slate-500 hover:text-slate-700"}`}
                >
                  Archivo
                </button>
              </div>
            )}

            <div className="relative aspect-video bg-slate-900 rounded-[2.5rem] overflow-hidden border-4 border-white shadow-2xl flex items-center justify-center">
              {flashEffect && <div className="absolute inset-0 bg-white z-20 animate-pulse" />}

              {isStreamActive ? (
                <>
                  <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover" />
                  <div className="absolute inset-0 border-[30px] border-black/10 pointer-events-none">
                     <div className="w-full h-full border-2 border-indigo-400/30 rounded-lg"></div>
                  </div>
                  <div className="absolute bottom-8 left-0 right-0 flex justify-center">
                    <button 
                      onClick={captureFrame}
                      className="w-16 h-16 bg-white rounded-full p-1 shadow-2xl active:scale-95 transition-all border-4 border-slate-100 flex items-center justify-center"
                    >
                      <div className="w-full h-full rounded-full bg-red-600 border-2 border-white" />
                    </button>
                  </div>
                </>
              ) : image ? (
                <>
                  <img src={image} className="w-full h-full object-contain" alt="Referencia" />
                  <button 
                    onClick={() => { setImage(null); startCamera(); }}
                    className="absolute top-4 right-4 bg-black/60 hover:bg-black/80 text-white px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all backdrop-blur-md"
                  >
                    Tomar Otra Foto
                  </button>
                </>
              ) : mode === "upload" ? (
                <div onClick={() => fileInputRef.current?.click()} className="flex flex-col items-center gap-4 cursor-pointer hover:bg-slate-800 transition-colors w-full h-full justify-center group">
                   <div className="w-16 h-16 bg-slate-800 rounded-full flex items-center justify-center text-slate-500 group-hover:bg-indigo-600 group-hover:text-white transition-all">
                      <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
                   </div>
                   <p className="text-slate-400 font-bold uppercase tracking-widest text-[10px]">Cargar archivo de imagen</p>
                   <input ref={fileInputRef} type="file" accept="image/*" className="hidden" onChange={handleFileUpload} />
                </div>
              ) : (
                <div className="text-center space-y-2">
                   <div className="w-10 h-10 border-4 border-slate-700 border-t-indigo-500 rounded-full animate-spin mx-auto"></div>
                   <p className="text-slate-500 font-black uppercase text-[10px] tracking-widest">Iniciando fuente de video...</p>
                </div>
              )}
            </div>
            <p className="text-[10px] text-slate-400 font-bold text-center uppercase tracking-widest bg-slate-100 py-2 rounded-xl">Use la imagen de la izquierda como guía para transcribir los datos</p>
          </div>

          <div className="bg-slate-50 rounded-[2.5rem] p-8 lg:p-10 border border-slate-200 space-y-8 flex flex-col justify-center shadow-inner">
             <div className="space-y-6">
                <div>
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest block mb-3 ml-1">1. Seleccionar Generador:</label>
                  <select 
                    value={selectedGenId}
                    onChange={(e) => setSelectedGenId(Number(e.target.value))}
                    className="w-full p-5 bg-white border border-slate-200 rounded-3xl font-black text-slate-800 focus:ring-4 focus:ring-red-600/10 focus:border-red-600 outline-none transition-all shadow-sm"
                  >
                    <option value="">-- Seleccionar Equipo --</option>
                    {generators.map(g => <option key={g.id} value={g.id}>{g.name} ({g.powerKVA})</option>)}
                  </select>
                </div>

                <div className="grid grid-cols-2 gap-6">
                  <div className="p-8 bg-white rounded-[2rem] border border-slate-200 flex flex-col justify-center text-center shadow-sm">
                      <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">2. Combustible (%)</span>
                      <div className="flex items-center justify-center gap-1">
                        <input 
                          type="number"
                          value={fuelValue}
                          onChange={(e) => setFuelValue(Number(e.target.value))}
                          className="bg-transparent text-5xl font-black text-red-600 text-center outline-none w-28"
                          placeholder="0"
                        />
                        <span className="text-2xl font-black text-red-400">%</span>
                      </div>
                  </div>
                  <div className="p-8 bg-white rounded-[2rem] border border-slate-200 flex flex-col justify-center text-center shadow-sm">
