import ManualCaptureModal from './components/ManualCaptureModal';
import LogsView from './components/LogsView';
import FuelManagementView from './components/FuelManagementView';
import LoginView from './components/LoginView';
import OutagesView from './components/OutagesView';

declare var html2canvas: any;

const calculateDaysSince = (dateStr: string, fromDate: Date): number => {
  const parts = dateStr.split('/');
  if (parts.length !== 3) return 0;
  const [day, month, year] = parts;
  const formattedDate = new Date(`${year}-${month}-${day}`);
  if (isNaN(formattedDate.getTime())) return 0;

  const controlDate = new Date(fromDate);
  controlDate.setHours(0, 0, 0, 0);
  formattedDate.setHours(0,0,0,0);

  const diffTime = controlDate.getTime() - formattedDate.getTime();
  if (diffTime < 0) return 0;
  return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
};

const extractNumber = (val: string | number): number => {
  if (typeof val === 'number') return val;
  const match = val.match(/(\d+[,.]?\d*)/);
  if (!match) return 0;
  return parseFloat(match[0].replace(',', '.'));
};

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(() => localStorage.getItem('is_auth') === 'true');
  const [view, setView] = useState<'dashboard' | 'reports' | 'logs' | 'fuel' | 'outages'>('dashboard');
  const [currentMonth, setCurrentMonth] = useState(() => new Date().toISOString().slice(0, 7));
  const [currentOperator, setCurrentOperator] = useState(() => localStorage.getItem('current_operator') || 'Operador NOC');

  const [generators, setGenerators] = useState<StoredGenerator[]>(() => {
    try {
      const saved = localStorage.getItem('generators');
      return saved ? JSON.parse(saved) : INITIAL_GENERATORS;
    } catch {
      return INITIAL_GENERATORS;
    }
  });

  const [fuelLoads, setFuelLoads] = useState<FuelLoad[]>(() => {
    try {
      const saved = localStorage.getItem('fuel_loads');
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  const [outages, setOutages] = useState<Outage[]>(() => {
    try {
      const saved = localStorage.getItem('outages');
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  const [logs, setLogs] = useState<ChangeLog[]>(() => {
    try {
      const saved = localStorage.getItem('change_logs');
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  const [reports, setReports] = useState<Report[]>(() => {
    try {
        const saved = localStorage.getItem('reports_v2');
        return saved ? JSON.parse(saved) : [];
    } catch {
        return [];
    }
  });

  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'name', direction: 'ascending' });
  const [selectedRowId, setSelectedRowId] = useState<number | null>(null);
  const [editingCell, setEditingCell] = useState<{ id: number; key: keyof Generator } | null>(null);
  const [controlDate, setControlDate] = useState(new Date());
  const [isSheetModalOpen, setIsSheetModalOpen] = useState(false);
  const [isCaptureModalOpen, setIsCaptureModalOpen] = useState(false);

  useEffect(() => {
    localStorage.setItem('generators', JSON.stringify(generators));
    localStorage.setItem('reports_v2', JSON.stringify(reports));
    localStorage.setItem('change_logs', JSON.stringify(logs));
    localStorage.setItem('fuel_loads', JSON.stringify(fuelLoads));
    localStorage.setItem('outages', JSON.stringify(outages));
    localStorage.setItem('is_auth', String(isAuthenticated));
    localStorage.setItem('current_operator', currentOperator);
  }, [generators, reports, logs, fuelLoads, outages, isAuthenticated, currentOperator]);

  const addLog = (generatorName: string, field: string, oldVal: any, newVal: any, source: ChangeLog['source'], operator: string = currentOperator) => {
    const newLog: ChangeLog = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toISOString(),
      generatorName,
      field,
      oldValue: oldVal,
      newValue: newVal,
      source,
      operator
    };
    setLogs(prev => [newLog, ...prev].slice(0, 500));
  };

  const calculateStatus = (fuelLevel: number): Status => {
    if (fuelLevel >= 71) return Status.Optimal;
    if (fuelLevel >= 70) return Status.Warning;
    return Status.NeedsRecharge;
  };

  const processedGenerators: Generator[] = useMemo(() => {
    return generators.map(g => ({
      ...g,
      status: calculateStatus(g.fuelLevel),
      timeSinceLastRecharge: calculateDaysSince(g.lastRechargeDate, controlDate),
    }));
  }, [generators, controlDate]);

  const sortedGenerators = useMemo(() => {
    const sortableItems = [...processedGenerators];
    if (sortConfig.key) {
      sortableItems.sort((a, b) => {
        const aValue = a[sortConfig.key];
        const bValue = b[sortConfig.key];
        if (typeof aValue === 'string' && typeof bValue === 'string') {
          return sortConfig.direction === 'ascending' ? aValue.localeCompare(bValue) : bValue.localeCompare(aValue);
        }
        return sortConfig.direction === 'ascending' ? (aValue as number) - (bValue as number) : (bValue as number) - (aValue as number);
      });
    }
    return sortableItems;
  }, [processedGenerators, sortConfig]);

  const handleGeneratorUpdate = (id: number, key: keyof StoredGenerator, value: string, source: ChangeLog['source'] = 'Manual') => {
    setGenerators(prev => 
      prev.map(gen => {
        if (gen.id === id) {
          let updatedValue: string | number = value;
          if (key === 'fuelLevel') {
            const numericValue = parseFloat(value.replace(',', '.'));
            updatedValue = isNaN(numericValue) ? gen[key] : numericValue;
          }

          if (gen[key] !== updatedValue) {
            addLog(gen.name, key, gen[key], updatedValue, source);
            return { ...gen, [key]: updatedValue };
          }
        }
        return gen;
      })
    );
    setEditingCell(null);
  };

  const handleCaptureUpdate = (id: number, fuel: number, hours: string) => {
    handleGeneratorUpdate(id, 'fuelLevel', String(fuel), 'Manual');
    handleGeneratorUpdate(id, 'executionHours', hours, 'Manual');
    setView('dashboard'); // Siempre volver al dashboard al finalizar la captura
  };

  const handleAddFuelLoad = (genId: number, liters: string, date: string, operator: string) => {
    const gen = generators.find(g => g.id === genId);
    if (!gen) return;

    const added_liters = extractNumber(liters);
    const tank_cap = extractNumber(gen.tankCapacity);

    const current_liters = (gen.fuelLevel / 100) * tank_cap;
    const new_liters = current_liters + added_liters;
    const new_level = tank_cap > 0 ? Math.min(100, Math.round((new_liters / tank_cap) * 100)) : 100;

    const newLoad: FuelLoad = {
      id: Math.random().toString(36).substr(2, 9),
      generatorId: genId,
      generatorName: gen.name,
      liters,
      date,
      previousLevel: gen.fuelLevel,
      newLevel: new_level,
      operator
    };

    setFuelLoads(prev => [newLoad, ...prev]);
    setGenerators(prev => prev.map(g => g.id === genId ? { ...g, fuelLevel: new_level, lastRechargeLiters: liters, lastRechargeDate: date } : g));
    addLog(gen.name, 'fuelLevel', gen.fuelLevel, new_level, 'Manual', operator);
  };

  const handleDownloadJPG = async () => {
    const element = document.getElementById('capture-container');
    if (!element) return;

    try {
      const canvas = await html2canvas(element, {
        scale: 2,
        useCORS: true,
        backgroundColor: '#f8fafc',
        logging: false
      });

      const image = canvas.toDataURL("image/jpeg", 0.9);
      const link = document.createElement('a');
      link.download = `dashboard-generadores-${new Date().toISOString().split('T')[0]}.jpg`;
      link.href = image;
      link.click();
    } catch (err) {
      console.error("Error capturando pantalla:", err);
      alert("Hubo un error al generar la captura de imagen.");
    }
  };

  if (!isAuthenticated) {
    return <LoginView onLogin={() => setIsAuthenticated(true)} />;
  }

  return (
    <div className="min-h-screen bg-slate-50 p-4 sm:p-6 lg:p-8 font-sans">
      <div id="capture-container" className="max-w-7xl mx-auto space-y-6 print:space-y-6 print:max-w-full print:p-4 print:bg-white">
        <Header 
          onAddGenerator={() => {
            const newId = generators.length > 0 ? Math.max(...generators.map(g => g.id)) + 1 : 1;
            setGenerators(prev => [...prev, {
              id: newId,
              name: `Nuevo GE ${newId}`,
              executionHours: '0 Hr',
              fuelLevel: 100,
              tankCapacity: '50 Lts',
              powerKVA: '22KVA',
              lastRechargeLiters: '0',
              lastRechargeDate: new Date().toLocaleDateString('es-ES')
            }]);
          }}
          onFileUpload={() => {}}
          onGoogleSheetImportClick={() => setIsSheetModalOpen(true)}
          onAIScanClick={() => setIsCaptureModalOpen(true)}
          controlDate={controlDate}
          onControlDateChange={(ds) => setControlDate(new Date(`${ds}T00:00:00`))}
          onSaveSessionCapture={() => alert('Sesión guardada')}
          onDownloadJPG={handleDownloadJPG}
          isHistoryView={false}
          onReturnToLive={() => setControlDate(new Date())}
          view={view}
          onToggleView={(v) => setView(v)}
          currentOperator={currentOperator}
          onOperatorChange={setCurrentOperator}
        />

        {view === 'dashboard' && (
          <div className="space-y-4">
            <div className="flex justify-end gap-2 print:hidden">
               <button 
                onClick={() => setIsSheetModalOpen(true)}
                className="bg-white border border-slate-200 text-slate-600 px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-50 transition-all shadow-sm flex items-center gap-2"
               >
                 <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
                 Importar Datos Externos
               </button>
            </div>
            <div className="bg-white rounded-xl shadow-xl border border-slate-200 overflow-hidden print:shadow-none print:border-none">
              <div className="overflow-x-auto">
                <GeneratorTable 
                  generators={sortedGenerators} 
                  onSort={(key) => setSortConfig(prev => ({ key, direction: prev.key === key && prev.direction === 'ascending' ? 'descending' : 'ascending' }))} 
                  sortConfig={sortConfig}
                  selectedRowId={selectedRowId}
                  onRowClick={setSelectedRowId}
                  editingCell={editingCell}
                  onCellDoubleClick={(id, key) => setEditingCell({ id, key })}
                  onUpdate={handleGeneratorUpdate}
                  onCancelEdit={() => setEditingCell(null)}
                  onDelete={(id) => setGenerators(prev => prev.filter(g => g.id !== id))}
                  isReadOnly={false}
                />
              </div>
              <Legend />
            </div>
          </div>
        )}

        {view === 'fuel' && (
          <FuelManagementView 
            generators={generators}
            fuelLoads={fuelLoads}
            onAddLoad={handleAddFuelLoad}
            onDeleteLoad={(id) => setFuelLoads(prev => prev.filter(l => l.id !== id))}
            defaultOperator={currentOperator}
          />
        )}

        {view === 'outages' && (
          <OutagesView 
            generators={generators}
            outages={outages}
            onAddOutage={(genId, date, start, end, operator) => {
              // Lógica de cortes de energía (calcula consumo automáticamente)
            }}
            onSetOutageEnd={(id, end) => {}}
            onDeleteOutage={(id) => {}}
            defaultOperator={currentOperator}
          />
        )}

        {view === 'reports' && (
          <ReportsView 
            reports={reports}
            generators={generators}
            currentMonth={currentMonth}
            onMonthChange={setCurrentMonth}
            onFinalizeMonth={(m) => {
              setReports(prev => prev.map(r => r.month === m ? { ...r, isFinalized: true } : r));
            }}
            onAddEntry={() => {}}
            onUpdateEntry={() => {}}
            onDeleteEntry={() => {}}
            onAddReport={() => {}}
          />
        )}

        {view === 'logs' && <LogsView logs={logs} />}
      </div>

      <div className="fixed bottom-4 right-4 print:hidden">
        <button 
          onClick={() => {
            setIsAuthenticated(false);
            localStorage.setItem('is_auth', 'false');
          }}
          className="bg-slate-800 text-white px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-red-600 transition-all shadow-xl border border-slate-700"
        >
          Cerrar Sesión
        </button>
      </div>

      <GoogleSheetImportModal isOpen={isSheetModalOpen} onClose={() => setIsSheetModalOpen(false)} onImport={async () => {}} />
      <ManualCaptureModal 
        isOpen={isCaptureModalOpen} 
        onClose={() => setIsCaptureModalOpen(false)} 
        generators={generators}
        onConfirmUpdate={handleCaptureUpdate}
      />
    </div>
  );
};

