import React, { useState, useRef, useEffect } from "react";
import { GoogleGenAI, Type } from "@google/genai";
import { StoredGenerator } from "../types";

interface AIScanResult {
  hours: string;
  fuel: number;
}

interface ManualCaptureModalProps {
  isOpen: boolean;
  onClose: () => void;
  generators: StoredGenerator[];
  onAIScanConfirm: (id: number, fuel: number, hours: string) => void;
}

const ManualCaptureModal: React.FC<ManualCaptureModalProps> = ({
  isOpen,
  onClose,
  generators,
  onAIScanConfirm,
}) => {
  const [isScanning, setIsScanning] = useState(false);
  const [result, setResult] = useState<AIScanResult | null>(null);
  const [selectedGenId, setSelectedGenId] = useState<number | "">("");
  const [mode, setMode] = useState<"camera" | "upload" | "screen">("camera");
  const [image, setImage] = useState<string | null>(null);
  const [streamActive, setStreamActive] = useState(false);

  const videoRef = useRef<HTMLVideoElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const streamRef = useRef<MediaStream | null>(null);

  useEffect(() => {
    if (isOpen && mode === "camera") {
      startCamera();
    } else {
      stopMedia();
    }
    return () => stopMedia();
  }, [isOpen, mode]);

  const stopMedia = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((track) => track.stop());
      streamRef.current = null;
    }
    setStreamActive(false);
  };

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: "environment" },
      });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        streamRef.current = stream;
        setStreamActive(true);
      }
    } catch (err) {
      console.error("No se pudo acceder a la cámara:", err);
      setMode("upload");
    }
  };

  const captureImage = () => {
    if (videoRef.current && canvasRef.current) {
      const canvas = canvasRef.current;
      const video = videoRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext("2d");
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL("image/jpeg", 0.8);
        setImage(dataUrl);
        stopMedia();
        processImageWithAI(dataUrl);
      }
    }
  };

  const processImageWithAI = async (base64Data: string) => {
    setIsScanning(true);
    setResult(null);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Extract the execution hours (as string) and fuel level percentage (as number 0-100) from this generator control panel image. Return strictly JSON.`;

      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: [
          {
            parts: [
              { text: prompt },
              {
                inlineData: {
                  mimeType: "image/jpeg",
                  data: base64Data.split(",")[1],
                },
              },
            ],
          },
        ],
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              hours: { type: Type.STRING, description: "Total running hours" },
              fuel: { type: Type.NUMBER, description: "Fuel percentage 0 to 100" },
            },
            required: ["hours", "fuel"],
          },
        },
      });

      const parsed = JSON.parse(response.text || "{}");
      setResult({
        hours: parsed.hours || "N/A",
        fuel: typeof parsed.fuel === 'number' ? parsed.fuel : 0
      });
    } catch (err) {
      console.error("Error IA:", err);
      alert("No se pudo procesar la imagen. Asegúrese de que el tablero sea legible.");
    } finally {
      setIsScanning(false);
    }
  };

  const handleApply = () => {
    if (selectedGenId && result) {
      onAIScanConfirm(Number(selectedGenId), result.fuel, result.hours);
      onClose();
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 bg-slate-950/90 backdrop-blur-sm flex items-center justify-center p-4">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-4xl max-h-[90vh] overflow-hidden flex flex-col border border-slate-200">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
          <div>
            <h2 className="text-xl font-black text-slate-900 tracking-tight flex items-center gap-2 uppercase">
                <span className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white">IA</span>
                Asistente de Captura Inteligente
            </h2>
            <p className="text-slate-500 text-xs font-bold uppercase tracking-widest mt-1">Lectura Automática de Tableros</p>
          </div>
          <button onClick={onClose} className="w-10 h-10 rounded-full bg-slate-100 text-slate-500 hover:bg-slate-200 flex items-center justify-center transition-all">✕</button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 flex flex-col lg:flex-row gap-8">
          <div className="flex-1 space-y-4">
            <div className="relative aspect-video bg-slate-900 rounded-2xl overflow-hidden border-4 border-slate-800 shadow-inner group">
              {mode === "camera" && streamActive && !image && (
                <>
                  <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover" />
                  <div className="absolute inset-0 border-2 border-dashed border-indigo-500/30 m-8 pointer-events-none rounded-xl" />
                  <div className="absolute bottom-6 left-1/2 -translate-x-1/2">
                    <button 
                        onClick={captureImage}
                        className="w-16 h-16 bg-white rounded-full p-1 shadow-2xl active:scale-95 transition-all border-4 border-slate-300"
                    >
                        <div className="w-full h-full rounded-full bg-indigo-600 border-2 border-white" />
                    </button>
                  </div>
                </>
              )}
              {image && (
                <div className="relative w-full h-full">
                  <img src={image} className="w-full h-full object-contain" alt="Captura" />
                  {isScanning && (
                    <div className="absolute inset-0 bg-indigo-600/20 flex flex-col items-center justify-center backdrop-blur-[2px]">
                        <div className="w-12 h-12 border-4 border-white/20 border-t-white rounded-full animate-spin mb-4" />
                        <p className="text-white font-black uppercase text-[10px] tracking-[0.3em] animate-pulse">Analizando Tablero...</p>
                    </div>
                  )}
                </div>
              )}
              {!image && mode === "upload" && (
                <label className="w-full h-full flex flex-col items-center justify-center cursor-pointer hover:bg-slate-800/50 transition-all">
                    <svg className="w-12 h-12 text-slate-600 mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
                    <span className="text-slate-500 font-bold uppercase text-[10px] tracking-widest">Cargar Foto del Tablero</span>
                    <input type="file" className="hidden" accept="image/*" onChange={(e) => {
                        const file = e.target.files?.[0];
                        if (file) {
                            const reader = new FileReader();
                            reader.onload = (re) => {
                                const base64 = re.target?.result as string;
                                setImage(base64);
                                processImageWithAI(base64);
                            };
                            reader.readAsDataURL(file);
                        }
                    }} />
                </label>
              )}
            </div>

            <div className="flex bg-slate-100 p-1 rounded-xl w-fit">
              <button onClick={() => { stopMedia(); setImage(null); setMode("camera"); }} className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase transition-all ${mode === "camera" ? "bg-white text-indigo-600 shadow-sm" : "text-slate-500"}`}>Cámara</button>
              <button onClick={() => { stopMedia(); setImage(null); setMode("upload"); }} className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase transition-all ${mode === "upload" ? "bg-white text-indigo-600 shadow-sm" : "text-slate-500"}`}>Archivo</button>
            </div>
          </div>

          <div className="w-full lg:w-80 space-y-6">
            <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest block ml-1">Vincular a Generador:</label>
                <select 
                    value={selectedGenId}
                    onChange={(e) => setSelectedGenId(Number(e.target.value))}
                    className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold text-slate-900 focus:ring-4 focus:ring-indigo-500/10 outline-none transition-all"
                >
                    <option value="">-- Seleccionar Equipo --</option>
                    {generators.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                </select>
            </div>

            <div className={`p-6 rounded-2xl border transition-all ${result ? 'bg-emerald-50 border-emerald-100' : 'bg-slate-50 border-slate-100 opacity-50'}`}>
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Datos Detectados por IA</h3>
                <div className="space-y-4">
                    <div className="flex justify-between items-center">
                        <span className="text-xs font-bold text-slate-500 uppercase">Horas Ej.</span>
                        <span className="text-lg font-black text-slate-900">{result?.hours || '--'}</span>
                    </div>
                    <div className="flex justify-between items-center">
                        <span className="text-xs font-bold text-slate-500 uppercase">Combustible</span>
                        <span className="text-lg font-black text-emerald-600">{result ? `${result.fuel}%` : '--'}</span>
                    </div>
                </div>
            </div>

            <button 
                disabled={!result || !selectedGenId || isScanning}
                onClick={handleApply}
                className="w-full py-5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-xl shadow-indigo-600/20 transition-all disabled:opacity-30 active:scale-95"
            >
                Confirmar y Sincronizar
            </button>

            {result && (
                <button 
                    onClick={() => { setImage(null); setResult(null); if(mode === "camera") startCamera(); }}
                    className="w-full text-[10px] font-black text-slate-400 uppercase hover:text-red-500 transition-colors"
                >
                    Reintentar Captura
                </button>
            )}
          </div>
        </div>
      </div>
      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

