import React, { useState, useRef, useEffect } from "react";
import { GoogleGenAI, Type } from "@google/genai";
import { StoredGenerator } from "../types";

interface SyncResult {
  generatorName: string;
  hours: string;
  fuel: number;
}

interface ManualCaptureModalProps {
  isOpen: boolean;
  onClose: () => void;
  generators: StoredGenerator[];
  onAIScanConfirm: (id: number, fuel: number, hours: string) => void;
}

const ManualCaptureModal: React.FC<ManualCaptureModalProps> = ({
  isOpen,
  onClose,
  generators,
  onAIScanConfirm,
}) => {
  const [isProcessing, setIsProcessing] = useState(false);
  const [results, setResults] = useState<SyncResult[]>([]);
  const [pastedImage, setPastedImage] = useState<string | null>(null);
  const [selectedMatches, setSelectedMatches] = useState<Record<number, number>>({});

  useEffect(() => {
    const handlePaste = (e: ClipboardEvent) => {
      if (!isOpen) return;
      const items = e.clipboardData?.items;
      if (items) {
        for (let i = 0; i < items.length; i++) {
          if (items[i].type.indexOf("image") !== -1) {
            const blob = items[i].getAsFile();
            if (blob) {
              const reader = new FileReader();
              reader.onload = (event) => {
                const base64 = event.target?.result as string;
                setPastedImage(base64);
                processCapture(base64);
              };
              reader.readAsDataURL(blob);
            }
          }
        }
      }
    };

    window.addEventListener("paste", handlePaste);
    return () => window.removeEventListener("paste", handlePaste);
  }, [isOpen]);

  const processCapture = async (base64Data: string) => {
    setIsProcessing(true);
    setResults([]);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Act as an OCR data extractor. Read the provided screenshot from a generator monitoring system. 
      Identify:
      1. Generator/Site Name
      2. Execution/Running Hours
      3. Fuel Level (Percentage 0-100)

      Return a list of objects in JSON format. Do not add any text other than the JSON.`;

      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: [
          {
            parts: [
              { text: prompt },
              {
                inlineData: {
                  mimeType: "image/jpeg",
                  data: base64Data.split(",")[1],
                },
              },
            ],
          },
        ],
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                generatorName: { type: Type.STRING },
                hours: { type: Type.STRING },
                fuel: { type: Type.NUMBER },
              },
              required: ["generatorName", "hours", "fuel"],
            },
          },
        },
      });

      const extracted = JSON.parse(response.text || "[]") as SyncResult[];
      setResults(extracted);

      // Auto-match based on names
      const matches: Record<number, number> = {};
      extracted.forEach((res, idx) => {
        const found = generators.find(g => 
            g.name.toLowerCase().includes(res.generatorName.toLowerCase()) || 
            res.generatorName.toLowerCase().includes(g.name.toLowerCase())
        );
        if (found) matches[idx] = found.id;
      });
      setSelectedMatches(matches);

    } catch (err) {
      console.error("Error procesando captura:", err);
      alert("No se pudo leer la información de la imagen automáticamente.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleConfirmAll = () => {
    results.forEach((res, idx) => {
      const genId = selectedMatches[idx];
      if (genId) {
        onAIScanConfirm(genId, res.fuel, res.hours);
      }
    });
    onClose();
    setResults([]);
    setPastedImage(null);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 bg-slate-950/95 backdrop-blur-md flex items-center justify-center p-4">
      <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-5xl max-h-[90vh] overflow-hidden flex flex-col border border-slate-200">

        <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
          <div>
            <h2 className="text-2xl font-black text-slate-900 tracking-tight flex items-center gap-3 uppercase">
                <div className="w-10 h-10 bg-indigo-600 rounded-2xl flex items-center justify-center text-white shadow-lg">
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-3 7h3m-3 4h3m-6-4h.01M9 16h.01" /></svg>
                </div>
                Sincronización de Datos Externos
            </h2>
            <p className="text-slate-500 text-[10px] font-black uppercase tracking-[0.2em] mt-2 ml-1">Pega una captura de pantalla (Ctrl+V) para actualizar los generadores</p>
          </div>
          <button onClick={onClose} className="w-12 h-12 rounded-full bg-slate-100 text-slate-400 hover:bg-rose-100 hover:text-rose-500 flex items-center justify-center transition-all">✕</button>
        </div>

        <div className="flex-1 overflow-hidden flex flex-col lg:flex-row">

          {/* Lado Izquierdo: Visualización de la Captura */}
          <div className="flex-1 p-8 bg-slate-100/50 border-r border-slate-100 flex flex-col gap-4">
             <div className="flex-1 relative rounded-3xl border-4 border-dashed border-slate-200 bg-white flex flex-col items-center justify-center overflow-hidden transition-all group hover:border-indigo-300">
                {pastedImage ? (
                    <img src={pastedImage} className="w-full h-full object-contain" alt="Pasted" />
                ) : (
                    <div className="text-center p-8 space-y-4">
                        <div className="w-20 h-20 bg-slate-100 rounded-full flex items-center justify-center mx-auto text-slate-300 group-hover:scale-110 group-hover:bg-indigo-50 group-hover:text-indigo-400 transition-all">
                            <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                        </div>
                        <p className="text-slate-400 font-bold uppercase text-[10px] tracking-widest">Esperando Captura...</p>
                        <p className="text-slate-300 text-[9px] italic">Presiona Control + V para pegar la imagen del otro sistema</p>
                    </div>
                )}
                {isProcessing && (
                    <div className="absolute inset-0 bg-indigo-900/40 backdrop-blur-sm flex flex-col items-center justify-center">
                        <div className="w-16 h-16 border-4 border-white/20 border-t-white rounded-full animate-spin mb-6 shadow-2xl" />
                        <p className="text-white font-black uppercase text-xs tracking-[0.4em] animate-pulse">Analizando Pixeles...</p>
                    </div>
                )}
             </div>
             {pastedImage && (
                 <button onClick={() => setPastedImage(null)} className="text-[10px] font-black text-slate-400 uppercase hover:text-rose-500 transition-colors">Limpiar Imagen</button>
             )}
          </div>

          {/* Lado Derecho: Resultados de la Lectura */}
          <div className="w-full lg:w-[400px] p-8 flex flex-col gap-6 bg-white overflow-y-auto">
             <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
                Resultados Detectados
                {results.length > 0 && <span className="bg-emerald-100 text-emerald-600 px-2 py-0.5 rounded-md">{results.length}</span>}
             </h3>

             {results.length === 0 ? (
                 <div className="flex-1 flex flex-col items-center justify-center text-center opacity-30 space-y-3">
                    <svg className="w-12 h-12 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
                    <p className="text-xs font-black uppercase">Sin datos para procesar</p>
                 </div>
             ) : (
                 <div className="space-y-4 flex-1">
                    {results.map((res, idx) => (
                        <div key={idx} className="p-5 rounded-3xl bg-slate-50 border border-slate-100 space-y-4 shadow-sm hover:shadow-md transition-all border-l-4 border-l-indigo-500">
