                               <label className="text-[9px] font-black text-slate-400 uppercase">Detectado como:</label>
                               <span className="text-sm font-black text-slate-800 uppercase leading-none">{res.generatorName}</span>
                           </div>

                           <div className="flex items-center gap-3">
                                <div className="flex-1 bg-white p-2 rounded-xl border border-slate-200">
                                    <span className="text-[8px] font-black text-slate-400 uppercase block">Horas</span>
                                    <span className="text-xs font-black text-slate-700">{res.hours}</span>
