                                </select>
                           </div>
                        </div>
                    ))}
                 </div>
             )}

             <div className="space-y-3 pt-6 border-t border-slate-100">
                <button 
                    disabled={results.length === 0 || isProcessing}
                    onClick={handleConfirmAll}
                    className="w-full py-5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-3xl font-black text-xs uppercase tracking-[0.2em] shadow-xl shadow-indigo-600/20 transition-all disabled:opacity-30 active:scale-95"
                >
                    Aplicar Cambios
                </button>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
